const { execSync } = require('child_process');
const fs = require('fs');

try {
    execSync('npx tsc --noEmit --pretty false', { encoding: 'utf8' });
    console.log('No errors found.');
} catch (error) {
    fs.writeFileSync('tsc_full_errors.txt', error.output.join('\n'));
    console.log('Errors caught in tsc_full_errors.txt');
}

import { initializeApp } from "firebase/app";
import { getFirestore, collection, query, orderBy, limit, getDocs } from "firebase/firestore";
import * as dotenv from 'dotenv';
import path from 'path';

dotenv.config({ path: '.env.local' });

const firebaseConfig = {
    apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY,
    authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN,
    projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID,
    storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET,
    messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID,
    appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID,
};

const app = initializeApp(firebaseConfig);
const db = getFirestore(app);

async function getIssues() {
    try {
        const q = query(collection(db, "system_issues"), orderBy("timestamp", "desc"), limit(10));
        const snapshot = await getDocs(q);
        const issues = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        console.log(JSON.stringify(issues, null, 2));
    } catch (error) {
        console.error("Error fetching issues:", error);
    }
}

getIssues();

"use client";

import Link from "next/link";
import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { GraduationCap, BookOpen, Loader2, AlertCircle, ArrowLeft, BarChart3, BrainCircuit, TrendingUp, Zap } from "lucide-react";
import { useAuth } from "@/context/auth-context";

const HIGHLIGHTS = [
    { icon: BarChart3, text: "Placement readiness scores" },
    { icon: BrainCircuit, text: "AI-powered risk analysis" },
    { icon: TrendingUp, text: "CGPA trend analytics" },
    { icon: Zap, text: "Real-time Firestore sync" },
];

export default function LoginPage() {
    const [role, setRole] = useState<"student" | "faculty">("student");
    const [loading, setLoading] = useState(false);
    const [googleLoading, setGoogleLoading] = useState(false);
    const { login, user, googleLogin, isLoading, handleRoleRedirection } = useAuth(); // Use unified redirection
    const router = useRouter();

    useEffect(() => {
        if (!isLoading && user) {
            handleRoleRedirection(user);
        }
    }, [user, isLoading, handleRoleRedirection]);

    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [error, setError] = useState("");

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError("");
        try {
            await login({ email, password });
        } catch (err: any) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    const handleGoogleLogin = async () => {
        setGoogleLoading(true);
        setError("");
        try {
            // Explicitly pass the current local role to ensure intent is preserved
            await googleLogin(role);
        } catch (err: any) {
            setError(err.message);
        } finally {
            setGoogleLoading(false);
        }
    };

    return (
        <div className="min-h-[100dvh] flex bg-white">
            {/* ΓöÇΓöÇ Left Branding Panel ΓöÇΓöÇ */}
            <div className="hidden lg:flex flex-col justify-between w-[46%] xl:w-[42%] relative overflow-hidden p-12 bg-gradient-to-br from-violet-600 via-indigo-600 to-indigo-800">
                {/* Subtle inner light */}
                <div className="absolute top-0 right-0 w-[60%] h-[50%] rounded-full bg-white/10 blur-[100px] pointer-events-none" />
                <div className="absolute bottom-0 left-0 w-[50%] h-[40%] rounded-full bg-indigo-900/30 blur-[80px] pointer-events-none" />
                {/* Dot pattern */}
                <div className="absolute inset-0 pointer-events-none opacity-[0.12]"
                    style={{ backgroundImage: "radial-gradient(circle, white 1px, transparent 1px)", backgroundSize: "32px 32px" }} />

                <div className="relative z-10">
                    <Link href="/" className="inline-flex items-center gap-2 text-white/70 hover:text-white text-sm font-medium transition-colors">
                        <ArrowLeft className="h-4 w-4" />Back to home
                    </Link>
                </div>

                <div className="relative z-10 space-y-8">
                    <div className="p-3 rounded-2xl bg-white/15 backdrop-blur border border-white/20 w-fit">
                        <GraduationCap className="h-10 w-10 text-white" />
                    </div>
                    <div className="space-y-3">
                        <h2 className="text-4xl font-black text-white leading-tight">
                            Your academic <br />intelligence hub.
                        </h2>
                        <p className="text-white/70 text-base max-w-xs leading-relaxed">
                            ALSA transforms complex academic data into clear, actionable placement insights.
                        </p>
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                        {HIGHLIGHTS.map((h) => (
                            <div key={h.text} className="flex items-center gap-2.5 bg-white/10 border border-white/15 rounded-xl px-4 py-3">
                                <h.icon className="h-4 w-4 text-white/80 shrink-0" />
                                <span className="text-xs font-medium text-white/80">{h.text}</span>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="relative z-10">
                    <p className="text-xs text-white/40 font-medium">┬⌐ 2026 ALSA ┬╖ Academic Learning &amp; Skills Analyzer</p>
                </div>
            </div>

            {/* ΓöÇΓöÇ Right Form Panel ΓöÇΓöÇ */}
            <div className="flex-1 flex flex-col items-center justify-center px-6 py-12 sm:px-12 bg-white relative">
                {/* Mobile back */}
                <div className="lg:hidden absolute top-6 left-6">
                    <Link href="/" className="inline-flex items-center gap-2 text-slate-400 hover:text-slate-700 text-sm font-medium transition-colors">
                        <ArrowLeft className="h-4 w-4" />Home
                    </Link>
                </div>

                <div className="w-full max-w-sm space-y-7 animate-in fade-in slide-in-from-bottom-6 duration-700">
                    <div className="space-y-1.5">
                        <h1 className="text-3xl font-black text-slate-900 tracking-tight">Welcome back</h1>
                        <p className="text-slate-400 text-sm">Sign in to your ALSA account</p>
                    </div>

                    {/* Role toggle */}
                    <div className="flex p-1 gap-1 rounded-2xl bg-slate-100 border-2 border-slate-300">
                        {(["student", "faculty"] as const).map((r) => (
                            <button key={r} onClick={() => {
                                setRole(r);
                                localStorage.setItem("alsa_preferred_role", r);
                            }}
                                suppressHydrationWarning
                                className={`flex-1 flex items-center justify-center gap-2 h-10 rounded-xl text-sm font-semibold transition-all duration-300 ${role === r
                                    ? "bg-gradient-to-r from-violet-600 to-indigo-600 text-white shadow-md"
                                    : "text-slate-500 hover:text-slate-700"}`}>
                                {r === "student" ? <GraduationCap className="h-4 w-4" /> : <BookOpen className="h-4 w-4" />}
                                <span className="capitalize">{r}</span>
                            </button>
                        ))}
                    </div>

                    {/* Google */}
                    <button type="button" onClick={handleGoogleLogin} disabled={loading || googleLoading}
                        suppressHydrationWarning
                        className="w-full h-12 flex items-center justify-center gap-3 rounded-xl bg-white border-2 border-slate-300 text-slate-700 text-sm font-semibold hover:bg-slate-50 hover:border-slate-400 shadow-md hover:shadow-lg transition-all duration-300 disabled:opacity-50">
                        {googleLoading ? <Loader2 className="h-4 w-4 animate-spin text-slate-500" /> : (
                            <>
                                <svg className="h-5 w-5" viewBox="0 0 48 48">
                                    <path fill="#EA4335" d="M24 9.5c3.3 0 6.2 1.2 8.5 3.1l6.3-6.3C34.8 2.9 29.7.5 24 .5 14.7.5 6.8 6 3 14l7.4 5.7C12.2 13.2 17.6 9.5 24 9.5z" />
                                    <path fill="#4285F4" d="M46.5 24.5c0-1.6-.1-3.1-.4-4.5H24v8.5h12.7c-.5 2.9-2.3 5.4-4.8 7l7.4 5.7c4.3-4 6.9-9.9 7.2-16.7z" />
                                    <path fill="#FBBC05" d="M10.4 28.2A14.6 14.6 0 0 1 9.5 24c0-1.5.3-2.9.7-4.3L2.8 14C1 17.1 0 20.4 0 24s1 6.9 2.8 9.9l7.6-5.7z" />
                                    <path fill="#34A853" d="M24 47.5c5.7 0 10.5-1.9 14-5.1l-7.4-5.7c-1.9 1.3-4.2 2-6.6 2-6.4 0-11.8-3.7-13.7-9.4L3 34.9C6.8 42 14.7 47.5 24 47.5z" />
                                </svg>
                                Continue with Google
                            </>
                        )}
                    </button>

                    {/* Divider */}
                    <div className="relative">
                        <div className="absolute inset-0 flex items-center">
                            <div className="w-full border-t-2 border-slate-200" />
                        </div>
                        <div className="relative flex justify-center">
                            <span className="bg-white px-4 text-xs uppercase tracking-widest font-semibold text-slate-400">or</span>
                        </div>
                    </div>

                    {/* Email/password form */}
                    <form onSubmit={handleLogin} className="space-y-4">
                        <div className="space-y-1.5">
                            <Label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Email</Label>
                            <Input type="email" placeholder="you@university.edu" required value={email} onChange={(e) => setEmail(e.target.value)}
                                suppressHydrationWarning
                                className="h-12 bg-white border-2 border-slate-300 text-slate-900 placeholder:text-slate-300 focus-visible:ring-violet-500 focus-visible:border-violet-400 focus-visible:ring-offset-0 rounded-xl shadow-md" />
                        </div>
                        <div className="space-y-1.5">
                            <Label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Password</Label>
                            <Input type="password" placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" required value={password} onChange={(e) => setPassword(e.target.value)}
                                suppressHydrationWarning
                                className="h-12 bg-white border-2 border-slate-300 text-slate-900 placeholder:text-slate-300 focus-visible:ring-violet-500 focus-visible:border-violet-400 focus-visible:ring-offset-0 rounded-xl shadow-md" />
                        </div>

                        {error && (
                            <div className="flex items-center gap-2.5 p-4 rounded-xl bg-red-50 border-2 border-red-300 text-red-700 text-sm font-medium">
                                <AlertCircle className="h-4 w-4 shrink-0" /> {error}
                            </div>
                        )}

                        <Button type="submit" disabled={loading || googleLoading}
                            suppressHydrationWarning
                            className="w-full h-12 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 text-white font-bold text-sm shadow-lg shadow-violet-200 hover:shadow-violet-300 transition-all duration-300 hover:-translate-y-0.5">
                            {loading ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Signing inΓÇª</> : "Sign In"}
                        </Button>
                    </form>

                    <p className="text-center text-sm text-slate-400">
                        Don&apos;t have an account?{" "}
                        <Link href="/signup" className="font-bold text-violet-600 hover:text-violet-800 transition-colors">Create one free</Link>
                    </p>
                </div>
            </div>
        </div>
    );
}

"use client";

import Link from "next/link";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useAuth } from "@/context/auth-context";
import {
    Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import {
    GraduationCap, BookOpen, User, Mail, Lock, ArrowRight, ArrowLeft, CheckCircle2, Loader2,
} from "lucide-react";
import { toast } from "sonner";
import { IT_DEPARTMENTS, CORE_DEPARTMENTS } from "@/lib/department-core";

const STEPS = ["Role", "Account", "Details"];

export default function SignupPage() {
    const router = useRouter();
    const { signup, googleLogin } = useAuth();
    const [step, setStep] = useState(1);
    const [role, setRole] = useState<"student" | "faculty">("student");
    const [loading, setLoading] = useState(false);
    const [googleLoading, setGoogleLoading] = useState(false);
    const [gender, setGender] = useState<"male" | "female" | "">("");
    const [formData, setFormData] = useState({
        name: "", email: "", password: "", confirmPassword: "",
        cgpa: "", attendance: "", department: "", designation: "",
    });

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { id, value } = e.target;
        setFormData((prev) => ({ ...prev, [id]: value }));
    };

    const handleNext = () => {
        if (step === 2) {
            if (!formData.name || !formData.email || !formData.password || !formData.confirmPassword || !gender) {
                toast.error("Please fill in all fields."); return;
            }
            const email = formData.email.toLowerCase();
            if (role === "student") {
                if (!email.endsWith("@gmail.com") && !email.endsWith("@bitsathy.ac.in")) {
                    toast.error("Students must use @gmail.com or @bitsathy.ac.in"); return;
                }
            } else {
                if (!email.endsWith("@college.edu") && !email.endsWith("@teacher.ac.in")) {
                    toast.error("Faculty must use @college.edu or @teacher.ac.in"); return;
                }
            }
            if (formData.password !== formData.confirmPassword) {
                toast.error("Passwords do not match."); return;
            }
        }
        setStep((prev) => prev + 1);
    };

    const handleBack = () => setStep((prev) => prev - 1);

    const handleSubmit = async () => {
        if (role === "student") {
            if (!formData.cgpa || !formData.attendance || !formData.department) {
                toast.error("Please fill in CGPA, Attendance, and Department"); return;
            }
            const cgpa = parseFloat(formData.cgpa);
            if (cgpa < 0 || cgpa > 10) { toast.error("CGPA must be between 0 and 10"); return; }
            const attendance = parseInt(formData.attendance);
            if (attendance < 0 || attendance > 100) { toast.error("Attendance must be between 0 and 100"); return; }
        } else {
            if (!formData.department || !formData.designation) {
                toast.error("Please fill in Department and Designation"); return;
            }
        }
        if (!formData.email || !formData.password) { toast.error("Email and Password are required"); return; }
        setLoading(true);
        try {
            await signup({ ...formData, role, gender: gender.toUpperCase() });
        } catch (error: any) {
            if (error.code === "auth/email-already-in-use") {
                toast.error("Email already exists. Please sign in.");
            } else {
                toast.error(error.message);
            }
        } finally {
            setLoading(false);
        }
    };

    const handleGoogleLogin = async () => {
        setGoogleLoading(true);
        try {
            await googleLogin(role);
        } catch (error: any) {
            toast.error(error.message);
        } finally {
            setGoogleLoading(false);
        }
    };

    return (
        <div className="min-h-[100dvh] flex bg-white">
            {/* ΓöÇΓöÇ Left Branding Panel ΓöÇΓöÇ */}
            <div className="hidden lg:flex flex-col justify-between w-[40%] xl:w-[36%] relative overflow-hidden p-12 bg-gradient-to-br from-violet-600 via-indigo-600 to-indigo-800">
                <div className="absolute top-0 right-0 w-[60%] h-[50%] rounded-full bg-white/10 blur-[100px] pointer-events-none" />
                <div className="absolute bottom-0 left-0 w-[50%] h-[40%] rounded-full bg-indigo-900/30 blur-[80px] pointer-events-none" />
                <div className="absolute inset-0 pointer-events-none opacity-[0.12]"
                    style={{ backgroundImage: "radial-gradient(circle, white 1px, transparent 1px)", backgroundSize: "32px 32px" }} />

                <div className="relative z-10">
                    <Link href="/" className="inline-flex items-center gap-2 text-white/70 hover:text-white text-sm font-medium transition-colors">
                        <ArrowLeft className="h-4 w-4" />Back to home
                    </Link>
                </div>

                <div className="relative z-10 space-y-6">
                    <div className="p-3 rounded-2xl bg-white/15 backdrop-blur border border-white/20 w-fit">
                        <GraduationCap className="h-10 w-10 text-white" />
                    </div>
                    <div className="space-y-3">
                        <h2 className="text-4xl font-black text-white leading-tight">
                            Join the future <br />of academics.
                        </h2>
                        <p className="text-white/70 text-base max-w-xs leading-relaxed">
                            Create your ALSA account in under 2 minutes and get instant access to AI-driven placement insights.
                        </p>
                    </div>

                    {/* Step tracker */}
                    <div className="space-y-3 pt-2">
                        {STEPS.map((s, i) => (
                            <div key={s} className={`flex items-center gap-3 transition-all duration-300 ${step > i ? "opacity-100" : "opacity-40"}`}>
                                <div className={`h-7 w-7 rounded-full flex items-center justify-center text-xs font-black border transition-all duration-300 ${step > i + 1 ? "bg-emerald-400 border-emerald-400 text-white" : step === i + 1 ? "bg-white border-white text-violet-700" : "border-white/30 text-white/40"}`}>
                                    {step > i + 1 ? <CheckCircle2 className="h-3.5 w-3.5" /> : i + 1}
                                </div>
                                <span className={`text-sm font-semibold ${step === i + 1 ? "text-white" : "text-white/50"}`}>{s}</span>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="relative z-10">
                    <p className="text-xs text-white/40 font-medium">┬⌐ 2026 ALSA ┬╖ Academic Learning &amp; Skills Analyzer</p>
                </div>
            </div>

            {/* ΓöÇΓöÇ Right Form Panel ΓöÇΓöÇ */}
            <div className="flex-1 flex flex-col items-center justify-center px-6 py-12 sm:px-12 bg-white relative">
                {/* Mobile top bar */}
                <div className="lg:hidden absolute top-6 left-6 right-6 flex items-center justify-between">
                    <Link href="/" className="inline-flex items-center gap-2 text-slate-400 hover:text-slate-700 text-sm font-medium transition-colors">
                        <ArrowLeft className="h-4 w-4" />Home
                    </Link>
                    <div className="flex items-center gap-1.5">
                        {STEPS.map((_, i) => (
                            <div key={i} className={`h-1.5 rounded-full transition-all duration-500 ${step > i ? (step === i + 1 ? "w-6 bg-violet-500" : "w-3 bg-emerald-400") : "w-3 bg-slate-200"}`} />
                        ))}
                    </div>
                </div>

                <div className="w-full max-w-sm space-y-6 animate-in fade-in slide-in-from-bottom-6 duration-700">
                    {/* Step header */}
                    <div className="space-y-1">
                        <p className="text-xs font-bold uppercase tracking-[0.25em] text-violet-600">Step {step} of 3</p>
                        <h1 className="text-2xl font-black text-slate-900 tracking-tight">
                            {step === 1 && "Choose your role"}
                            {step === 2 && "Create account"}
                            {step === 3 && (role === "student" ? "Academic details" : "Professional details")}
                        </h1>
                        <p className="text-slate-400 text-sm">
                            {step === 1 && "Select how you'll be using ALSA"}
                            {step === 2 && "Set up your secure credentials"}
                            {step === 3 && "A few more details to personalise your experience"}
                        </p>
                    </div>

                    {/* ΓöÇΓöÇ Step 1: Role ΓöÇΓöÇ */}
                    {step === 1 && (
                        <div className="space-y-6 animate-in fade-in zoom-in-95 duration-300">
                            <div className="grid grid-cols-2 gap-4">
                                {(["student", "faculty"] as const).map((r) => {
                                    const Icon = r === "student" ? GraduationCap : BookOpen;
                                    const isActive = role === r;
                                    return (
                                        <button key={r} onClick={() => setRole(r)}
                                            className={`flex flex-col items-center gap-4 p-6 rounded-2xl border-2 transition-all duration-300 ${isActive
                                                ? "border-violet-400 bg-violet-50 shadow-xl shadow-violet-100"
                                                : "border-slate-300 bg-white hover:bg-slate-50 hover:border-slate-400 shadow-md"}`}>
                                            <div className={`p-4 rounded-2xl transition-all duration-300 ${isActive
                                                ? "bg-gradient-to-br from-violet-600 to-indigo-600 text-white shadow-md"
                                                : "bg-slate-100 text-slate-400"}`}>
                                                <Icon className="h-8 w-8" />
                                            </div>
                                            <div className="text-center">
                                                <p className={`font-bold text-base capitalize ${isActive ? "text-violet-700" : "text-slate-500"}`}>{r}</p>
                                                <p className="text-xs text-slate-400 mt-1">{r === "student" ? "Track & grow" : "Manage & analyse"}</p>
                                            </div>
                                        </button>
                                    );
                                })}
                            </div>

                            <div className="relative">
                                <div className="absolute inset-0 flex items-center">
                                    <div className="w-full border-t border-slate-200"></div>
                                </div>
                                <div className="relative flex justify-center text-xs uppercase">
                                    <span className="bg-white px-2 text-slate-400 font-bold tracking-widest">or</span>
                                </div>
                            </div>

                            <button
                                type="button"
                                onClick={handleGoogleLogin}
                                disabled={googleLoading}
                                className="w-full h-12 flex items-center justify-center gap-3 rounded-xl bg-white border-2 border-slate-300 text-slate-700 text-sm font-semibold hover:bg-slate-50 hover:border-slate-400 shadow-md hover:shadow-lg transition-all duration-300 disabled:opacity-50"
                            >
                                {googleLoading ? (
                                    <Loader2 className="h-4 w-4 animate-spin text-slate-500" />
                                ) : (
                                    <>
                                        <svg className="h-5 w-5" viewBox="0 0 48 48">
                                            <path fill="#EA4335" d="M24 9.5c3.3 0 6.2 1.2 8.5 3.1l6.3-6.3C34.8 2.9 29.7.5 24 .5 14.7.5 6.8 6 3 14l7.4 5.7C12.2 13.2 17.6 9.5 24 9.5z" />
                                            <path fill="#4285F4" d="M46.5 24.5c0-1.6-.1-3.1-.4-4.5H24v8.5h12.7c-.5 2.9-2.3 5.4-4.8 7l7.4 5.7c4.3-4 6.9-9.9 7.2-16.7z" />
                                            <path fill="#FBBC05" d="M10.4 28.2A14.6 14.6 0 0 1 9.5 24c0-1.5.3-2.9.7-4.3L2.8 14C1 17.1 0 20.4 0 24s1 6.9 2.8 9.9l7.6-5.7z" />
                                            <path fill="#34A853" d="M24 47.5c5.7 0 10.5-1.9 14-5.1l-7.4-5.7c-1.9 1.3-4.2 2-6.6 2-6.4 0-11.8-3.7-13.7-9.4L3 34.9C6.8 42 14.7 47.5 24 47.5z" />
                                        </svg>
                                        Sign up with Google
                                    </>
                                )}
                            </button>
                        </div>
                    )}

                    {/* ΓöÇΓöÇ Step 2: Account ΓöÇΓöÇ */}
                    {step === 2 && (
                        <div className="space-y-4 animate-in slide-in-from-right-6 fade-in duration-400">
                            <div className="space-y-1.5">
                                <Label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Full Name</Label>
                                <div className="relative">
