                            <div className="space-y-1.5">
                                <Label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Gender</Label>
                                <div className="grid grid-cols-2 gap-3">
                                    {(["male", "female"] as const).map((g) => (
                                        <button key={g} type="button" onClick={() => setGender(g)}
                                            className={`h-11 rounded-xl border-2 flex items-center justify-center gap-2 text-sm font-semibold transition-all duration-300 shadow-sm ${gender === g
                                                ? g === "male" ? "border-blue-400 bg-blue-50 text-blue-700 shadow-blue-100" : "border-pink-400 bg-pink-50 text-pink-700 shadow-pink-100"
                                                : "border-slate-300 bg-white text-slate-500 hover:bg-slate-50 hover:border-slate-400"}`}>
                                            <span className="text-base">{g === "male" ? "≡ƒæ¿" : "≡ƒæ⌐"}</span>
                                            <span className="capitalize">{g}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <div className="space-y-1.5">
                                    <Label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Password</Label>
                                    <div className="relative">
                                        <Lock className="absolute left-3.5 top-3.5 h-4 w-4 text-slate-300" />
                                        <Input id="password" type="password" placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" value={formData.password} onChange={handleInputChange}
                                            className="pl-10 h-12 bg-white border-2 border-slate-300 text-slate-900 placeholder:text-slate-300 focus-visible:ring-violet-500 focus-visible:border-violet-400 focus-visible:ring-offset-0 rounded-xl shadow-md" />
                                    </div>
                                </div>
                                <div className="space-y-1.5">
                                    <Label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Confirm</Label>
                                    <div className="relative">
                                        <Lock className="absolute left-3.5 top-3.5 h-4 w-4 text-slate-300" />
                                        <Input id="confirmPassword" type="password" placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" value={formData.confirmPassword} onChange={handleInputChange}
                                            className="pl-10 h-12 bg-white border-2 border-slate-300 text-slate-900 placeholder:text-slate-300 focus-visible:ring-violet-500 focus-visible:border-violet-400 focus-visible:ring-offset-0 rounded-xl shadow-md" />
                                    </div>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* ΓöÇΓöÇ Step 3: Details ΓöÇΓöÇ */}
                    {step === 3 && (
                        <div className="space-y-4 animate-in slide-in-from-right-6 fade-in duration-400">
                            <div className="space-y-1.5">
                                <Label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Department</Label>
                                <Select onValueChange={(val) => setFormData((prev) => ({ ...prev, department: val }))}>
                                    <SelectTrigger className="h-12 bg-white border-2 border-slate-300 text-slate-900 focus:ring-violet-500 focus:border-violet-400 focus:ring-offset-0 rounded-xl shadow-md font-medium">
                                        <SelectValue placeholder="Select departmentΓÇª" />
                                    </SelectTrigger>
                                    <SelectContent className="bg-white border-slate-200 text-slate-900 shadow-xl">
                                        {IT_DEPARTMENTS.map((d) => (
                                            <SelectItem key={d} value={d} className="focus:bg-violet-50 focus:text-violet-900 cursor-pointer">{d}</SelectItem>
                                        ))}
                                        <div className="h-px bg-slate-100 my-1" />
                                        {CORE_DEPARTMENTS.map((d) => (
                                            <SelectItem key={d} value={d} className="focus:bg-violet-50 focus:text-violet-900 cursor-pointer">{d}</SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>

                            {role === "student" ? (
                                <div className="grid grid-cols-2 gap-3">
                                    <div className="space-y-1.5">
                                        <Label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">CGPA</Label>
                                        <Input id="cgpa" placeholder="e.g. 8.5" type="number" step="0.01" value={formData.cgpa} onChange={handleInputChange}
                                            className="h-12 bg-white border-2 border-slate-300 text-slate-900 font-bold placeholder:text-slate-300 focus-visible:ring-violet-500 focus-visible:border-violet-400 focus-visible:ring-offset-0 rounded-xl shadow-md" />
                                    </div>
                                    <div className="space-y-1.5">
                                        <Label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Attendance %</Label>
                                        <Input id="attendance" placeholder="e.g. 85" type="number" value={formData.attendance} onChange={handleInputChange}
                                            className="h-12 bg-white border-2 border-slate-300 text-slate-900 font-bold placeholder:text-slate-300 focus-visible:ring-violet-500 focus-visible:border-violet-400 focus-visible:ring-offset-0 rounded-xl shadow-md" />
                                    </div>
                                </div>
                            ) : (
                                <div className="space-y-1.5">
                                    <Label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Designation</Label>
                                    <Select onValueChange={(val) => setFormData((prev) => ({ ...prev, designation: val }))}>
                                        <SelectTrigger className="h-12 bg-white border-2 border-slate-300 text-slate-900 focus:ring-violet-500 focus:border-violet-400 focus:ring-offset-0 rounded-xl shadow-md font-medium">
                                            <SelectValue placeholder="Select titleΓÇª" />
                                        </SelectTrigger>
                                        <SelectContent className="bg-white border-slate-200 text-slate-900 shadow-xl">
                                            {["Professor", "Associate Professor", "Assistant Professor", "Lecturer", "HOD"].map((t) => (
                                                <SelectItem key={t} value={t} className="focus:bg-violet-50 focus:text-violet-900 cursor-pointer">{t === "HOD" ? "Head of Department" : t}</SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                            )}
                        </div>
                    )}

                    {/* ΓöÇΓöÇ Navigation ΓöÇΓöÇ */}
                    <div className="flex gap-3 pt-2">
                        {step > 1 && (
                            <Button type="button" onClick={handleBack} disabled={loading}
                                className="h-12 px-5 rounded-xl bg-white border-2 border-slate-300 text-slate-600 hover:bg-slate-50 hover:border-slate-400 hover:text-slate-900 shadow-md transition-all">
                                <ArrowLeft className="h-4 w-4" />
                            </Button>
                        )}
                        {step < 3 ? (
                            <Button type="button" onClick={handleNext}
                                className="flex-1 h-12 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 text-white font-bold shadow-lg shadow-violet-200 hover:shadow-violet-300 transition-all duration-300 hover:-translate-y-0.5">
                                Continue <ArrowRight className="ml-2 h-4 w-4" />
                            </Button>
                        ) : (
                            <Button type="button" onClick={handleSubmit} disabled={loading}
                                className="flex-1 h-12 rounded-xl bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white font-bold shadow-lg shadow-emerald-100 hover:shadow-emerald-200 transition-all duration-300 hover:-translate-y-0.5">
                                {loading ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" />CreatingΓÇª</> : <><CheckCircle2 className="mr-2 h-4 w-4" />Create Account</>}
                            </Button>
                        )}
                    </div>

                    <p className="text-center text-sm text-slate-400 pt-1">
                        Already have an account?{" "}
                        <Link href="/login" className="font-bold text-violet-600 hover:text-violet-800 transition-colors">Sign in</Link>
                    </p>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import {
    Users,
    TrendingDown,
    Activity,
    Building2,
    BookOpen,
    Clock,
    CheckCircle2,
    Lightbulb,
    ShieldCheck,
    ArrowUpRight,
    TrendingUp,
    Zap
} from "lucide-react";
import {
    BarChart,
    Bar,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    ResponsiveContainer,
    PieChart,
    Pie,
    Cell,
    Legend,
    LineChart,
    Line,
    AreaChart,
    Area
} from "recharts";
import { User } from "@/types";
import { calculatePRI, getPlacementReadiness } from "@/lib/placement-calculations";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { collection, getDocs, query, where } from "firebase/firestore";
import { db } from "@/lib/firebase";

export default function AdminDashboard() {
    const [students, setStudents] = useState<User[]>([]);
    const [faculty, setFaculty] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchData() {
            setLoading(true);
            try {
                const sQuery = query(collection(db, "students"));
                const fQuery = query(collection(db, "faculty"));

                const [sSnap, fSnap] = await Promise.all([getDocs(sQuery), getDocs(fQuery)]);

                setStudents(sSnap.docs.map(d => ({ id: d.id, ...d.data() }) as User));
                setFaculty(fSnap.docs.map(d => ({ id: d.id, ...d.data() }) as User));
            } catch (e) {
                console.error("Failed to load users from Firestore", e);
            } finally {
                setLoading(false);
            }
        }
        fetchData();
    }, []);

    // Analytics Calculation
    const analytics = useMemo(() => {
        if (students.length === 0) return null;

        const departmentCounts: Record<string, { totalPRI: number, count: number }> = {};
        const riskCounts = { Ready: 0, Moderate: 0, High: 0, Critical: 0 };
        const moduleScores = { academic: 0, core: 0, role: 0, aptitude: 0, enrichment: 0 };
        let totalPRI = 0;
        const consistencyTrendData: any[] = [];

        students.forEach((student, index) => {
            const priData = calculatePRI(student);

            totalPRI += priData.pri;

            // Department
            const dept = student.department || "Unknown";
            if (!departmentCounts[dept]) departmentCounts[dept] = { totalPRI: 0, count: 0 };
            departmentCounts[dept].totalPRI += priData.pri;
            departmentCounts[dept].count += 1;

            // Risk
            if (priData.pri >= 75) riskCounts.Ready++;
            else if (priData.pri >= 60 && priData.pri < 75) riskCounts.Moderate++;
            else if (priData.pri >= 40 && priData.pri < 60) riskCounts.High++;
            else riskCounts.Critical++;

            // Module avgs
            moduleScores.academic += priData.breakDown.academic;
            moduleScores.core += priData.breakDown.core;
            moduleScores.role += priData.breakDown.role;
            moduleScores.aptitude += priData.breakDown.aptitude;
            moduleScores.enrichment += priData.breakDown.enrichment;

            if (index < 12) {
                consistencyTrendData.push({
                    name: `P${index + 1}`,
                    score: priData.pri,
                    avg: 65 // Mock baseline
                });
            }
        });

        const count = students.length;
        const totalFaculty = faculty.length;
        const approvedFaculty = faculty.filter(f => f.approved).length;
        const pendingFaculty = totalFaculty - approvedFaculty;

        return {
            avgPRI: Math.round(totalPRI / count),
            totalStudents: count,
            totalFaculty,
            approvedFaculty,
            pendingFaculty,
            highRiskCount: riskCounts.High + riskCounts.Critical,

            departmentData: Object.entries(departmentCounts).map(([name, data]) => ({
                name,
                score: Math.round(data.totalPRI / data.count)
            })),

            riskData: [
                { name: "Ready", value: riskCounts.Ready, color: "#10b981" },
                { name: "Moderate", value: riskCounts.Moderate, color: "#3b82f6" },
                { name: "High", value: riskCounts.High, color: "#f59e0b" },
                { name: "Critical", value: riskCounts.Critical, color: "#ef4444" },
            ],

            modulePerformance: [
                { name: "Academic", score: Math.round(moduleScores.academic / count), fill: "#3b82f6" },
                { name: "Core Skills", score: Math.round(moduleScores.core / count), fill: "#6366f1" },
                { name: "Role Prep", score: Math.round(moduleScores.role / count), fill: "#8b5cf6" },
                { name: "Aptitude", score: Math.round(moduleScores.aptitude / count), fill: "#ec4899" },
                { name: "Enrichment", score: Math.round(moduleScores.enrichment / count), fill: "#f43f5e" },
            ],

            consistencyTrendData,
            insights: [] as string[]
        };
    }, [students, faculty]);

    // Generate AI Insights
    useEffect(() => {
        if (!analytics || analytics.totalStudents === 0) return;

        const generatedInsights: string[] = [];

        const moderateRiskPct = Math.round(((analytics.riskData[1].value + analytics.riskData[2].value) / analytics.totalStudents) * 100);
        if (moderateRiskPct >= 15) {
            generatedInsights.push(`${moderateRiskPct}% of the student body requires targeted placement mentorship.`);
        }

        if (analytics.departmentData.length > 0) {
            const lowestDept = [...analytics.departmentData].sort((a, b) => a.score - b.score)[0];
            if (lowestDept && lowestDept.score < 60) {
                generatedInsights.push(`Academic calibration needed for ${lowestDept.name} department.`);
            }
        }

        const weakModules = analytics.modulePerformance.filter(m => m.score < 50);
        if (weakModules.length > 0) {
            generatedInsights.push(`Intervention suggested for ${weakModules.map(m => m.name).join(", ")} modules.`);
        }

        if (analytics.pendingFaculty > 0) {
            generatedInsights.push(`Attention required: ${analytics.pendingFaculty} faculty credentials awaiting verification.`);
        }

        if (generatedInsights.length === 0) {
            generatedInsights.push("All institutional metrics are currently within optimal operational thresholds.");
        }

        analytics.insights = generatedInsights;
    }, [analytics]);

    if (loading || !analytics) {
        return (
            <div className="flex flex-col items-center justify-center p-20 gap-4 min-h-[60vh]">
                <Activity className="w-12 h-12 animate-pulse text-blue-500" />
                <p className="text-sm font-black uppercase tracking-[0.3em] text-slate-400 animate-pulse">Aggregating Global Intelligence...</p>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-700">
            {/* Premium Institutional Command Center Hero */}
            <div className="relative rounded-[40px] overflow-hidden bg-slate-950 shadow-3xl border border-white/5 group">
                {/* Dynamic Background Elements */}
                <div className="absolute inset-0 bg-gradient-to-br from-indigo-600/20 via-blue-600/10 to-transparent opacity-50 transition-opacity duration-700 group-hover:opacity-70" />
                <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-blue-500/10 rounded-full blur-[120px] -mr-48 -mt-48 animate-pulse" />
                <div className="absolute bottom-0 left-0 w-[400px] h-[400px] bg-indigo-500/10 rounded-full blur-[100px] -ml-24 -mb-24" />

                {/* Technical Grid Overlay */}
                <div className="absolute inset-0 opacity-[0.03] bg-[url('https://grainy-gradients.vercel.app/noise.svg')] pointer-events-none" />
                <div className="absolute inset-0 bg-[radial-gradient(rgba(255,255,255,0.05)_1px,transparent_1px)] [background-size:32px_32px]" />

                <div className="relative z-10 p-10 md:p-14 flex flex-col lg:flex-row lg:items-center justify-between gap-12">
                    <div className="max-w-3xl space-y-6">
                        <div className="flex items-center gap-4">
                            <div className="h-12 w-12 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-2xl flex items-center justify-center shadow-2xl shadow-blue-500/40 ring-4 ring-white/5 transition-transform duration-500 group-hover:rotate-12">
                                <ShieldCheck className="h-7 w-7 text-white" />
                            </div>
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black uppercase tracking-[0.4em] text-blue-400/80 leading-none">ALSA Network</span>
                                <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-500">Security Verified Hub</span>
                            </div>
                        </div>

                        <div>
                            <h1 className="text-5xl md:text-7xl font-black mb-4 tracking-tighter text-white leading-[0.9]">
                                Institutional <br />
                                <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 via-indigo-300 to-slate-400">Command Center</span>
                            </h1>
                            <p className="text-slate-400 font-medium text-lg md:text-xl max-w-xl leading-relaxed">
                                Orchestrating macro-level insights across <span className="text-white font-bold">{analytics.totalStudents} intelligence nodes</span> and <span className="text-white font-bold">{analytics.totalFaculty} verifyable faculty members</span>.
                            </p>
                        </div>

                        <div className="flex flex-wrap gap-4 pt-2">
                            <div className="px-4 py-2 bg-white/5 backdrop-blur-md rounded-xl border border-white/10 flex items-center gap-3">
                                <div className="h-2 w-2 rounded-full bg-emerald-500 animate-ping" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-slate-300">System Live</span>
                            </div>
                            <div className="px-4 py-2 bg-white/5 backdrop-blur-md rounded-xl border border-white/10 flex items-center gap-3">
                                <Activity className="h-3 w-3 text-blue-400" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-slate-300">Macro Sync: 100%</span>
                            </div>
                        </div>
                    </div>

                    <div className="relative group/score">
                        <div className="absolute inset-0 bg-blue-500/20 blur-[60px] rounded-full scale-75 opacity-0 group-hover/score:opacity-100 transition-opacity duration-700" />
                        <div className="relative bg-white/5 backdrop-blur-2xl rounded-[40px] p-10 border border-white/10 shadow-inner min-w-[280px] hover:border-blue-500/30 transition-all duration-500">
                            <p className="text-[11px] font-black text-blue-400 uppercase tracking-[0.25em] mb-4">Global PRI Index</p>
                            <div className="flex items-baseline gap-3">
                                <p className="text-8xl font-black leading-none text-white tracking-tighter">{analytics.avgPRI}</p>
                                <div className="flex flex-col">
                                    <TrendingUp className="h-8 w-8 text-emerald-400" />
                                    <span className="text-[10px] font-black text-emerald-400/80 tracking-widest">+2.4%</span>
                                </div>
                            </div>
                            <div className="mt-8 pt-6 border-t border-white/5 space-y-3">
                                <div className="flex justify-between items-center text-[10px] font-bold uppercase tracking-widest text-slate-500">
                                    <span>Sync Status</span>
                                    <span className="text-blue-400">Verifying...</span>
                                </div>
                                <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                                    <div className="h-full bg-gradient-to-r from-blue-600 to-indigo-500 w-[85%] rounded-full shadow-[0_0_10px_rgba(59,130,246,0.5)]" />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Premium KPI Grid */}
            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 mt-8">
                {[
                    { label: "Institutional Nodes", val: analytics.totalStudents, icon: Users, color: "text-blue-500", bg: "bg-blue-500/10", border: "border-blue-500/20" },
                    { label: "Faculty Directory", val: analytics.totalFaculty, icon: BookOpen, color: "text-indigo-500", bg: "bg-indigo-500/10", border: "border-indigo-500/20" },
                    { label: "Verified Assets", val: analytics.approvedFaculty, icon: CheckCircle2, color: "text-emerald-500", bg: "bg-emerald-500/10", border: "border-emerald-500/20" },
                    { label: "Auth Backlog", val: analytics.pendingFaculty, icon: Clock, color: "text-amber-500", bg: "bg-amber-500/10", border: "border-amber-500/20", alert: analytics.pendingFaculty > 0 },
                    { label: "Critical Risk", val: analytics.highRiskCount, icon: TrendingDown, color: "text-rose-500", bg: "bg-rose-500/10", border: "border-rose-500/20", alert: analytics.highRiskCount > 5 },
                    { label: "Uptime Metric", val: "99.99%", icon: Zap, color: "text-cyan-500", bg: "bg-cyan-500/10", border: "border-cyan-500/20" },
                ].map((kpi, i) => (
                    <Card key={i} className={`relative border-none bg-white dark:bg-slate-900 shadow-xl hover:shadow-2xl transition-all duration-500 group overflow-hidden rounded-[32px] ${kpi.alert ? 'ring-2 ring-rose-500/20' : ''}`}>
                        <div className={`absolute top-0 left-0 w-1.5 h-full ${kpi.color.replace('text', 'bg')}`} />
                        <CardContent className="p-7">
                            <div className="flex items-center justify-between mb-6">
                                <div className={`h-12 w-12 rounded-2xl ${kpi.bg} flex items-center justify-center transition-all duration-500 group-hover:scale-110 group-hover:rotate-6`}>
                                    <kpi.icon className={`h-6 w-6 ${kpi.color}`} />
                                </div>
                                <div className="h-8 w-8 rounded-full border border-slate-100 dark:border-slate-800 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                                    <ArrowUpRight className="h-4 w-4 text-slate-400" />
                                </div>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 group-hover:text-slate-500 transition-colors uppercase">{kpi.label}</p>
                                <div className="text-3xl font-black tracking-tighter text-slate-900 dark:text-white transition-transform duration-500 group-hover:translate-x-1">{kpi.val}</div>
                            </div>
                            {kpi.alert && (
                                <div className="mt-4 flex items-center gap-2">
                                    <div className="h-1.5 w-1.5 rounded-full bg-rose-500 animate-pulse" />
                                    <span className="text-[10px] font-bold text-rose-500 uppercase tracking-widest">Action Required</span>
                                </div>
                            )}
                        </CardContent>
                    </Card>
                ))}
            </div>

            {/* AI Insights Engine - Terminal Aesthetic */}
            {analytics.insights && analytics.insights.length > 0 && (
                <div className="relative group/insights overflow-hidden rounded-[32px] bg-slate-950 border border-white/10 shadow-3xl">
                    <div className="absolute inset-0 bg-gradient-to-br from-blue-600/10 via-indigo-600/5 to-transparent" />
                    <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-blue-500/50 to-transparent" />

                    <CardHeader className="relative z-10 pb-4 border-b border-white/5">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center space-x-3">
                                <div className="h-10 w-10 bg-blue-500/10 rounded-xl flex items-center justify-center border border-blue-500/20 shadow-inner">
                                    <Lightbulb className="h-5 w-5 text-blue-400" />
                                </div>
                                <div>
                                    <CardTitle className="text-sm font-black uppercase tracking-[0.3em] text-white">Neural Insights Engine</CardTitle>
                                    <CardDescription className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Institutional Strategy Recommendations</CardDescription>
                                </div>
                            </div>
                            <div className="hidden md:flex items-center gap-2">
                                <div className="px-3 py-1 bg-emerald-500/10 rounded-full border border-emerald-500/20">
                                    <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">Model Active</span>
                                </div>
                            </div>
                        </div>
                    </CardHeader>
                    <CardContent className="relative z-10 pt-6">
                        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
                            {analytics.insights.map((insight, i) => (
                                <div key={i} className="flex flex-col gap-3 rounded-2xl bg-white/5 p-5 border border-white/5 shadow-inner hover:bg-white/10 hover:border-blue-500/30 transition-all duration-500 group/insight">
                                    <div className="flex items-center justify-between">
                                        <div className="h-6 w-6 rounded-lg bg-blue-500/20 flex items-center justify-center text-[10px] font-black text-blue-400 border border-blue-500/20">
                                            0{i + 1}
                                        </div>
                                        <TrendingUp className="h-3 w-3 text-slate-600 group-hover:insight:text-blue-400 transition-colors" />
                                    </div>
                                    <p className="text-xs font-bold text-slate-300 leading-relaxed tracking-wide">{insight}</p>
                                </div>
                            ))}
                        </div>
                    </CardContent>
                </div>
            )}

            <div className="grid gap-8 lg:grid-cols-12 mt-8">
                {/* Risk Distribution - Interactive Radial */}
                <Card className="lg:col-span-4 border-none bg-white dark:bg-slate-900 shadow-3xl rounded-[40px] overflow-hidden group">
                    <CardHeader className="pb-2">
                        <div className="flex items-center justify-between mb-2">
                            <div className="h-10 w-10 bg-rose-500/10 rounded-xl flex items-center justify-center border border-rose-500/20">
                                <TrendingDown className="h-5 w-5 text-rose-500" />
                            </div>
                            <Badge variant="outline" className="text-[9px] font-black uppercase tracking-widest border-slate-100 dark:border-slate-800">Live Census</Badge>
                        </div>
                        <CardTitle className="text-lg font-black uppercase tracking-widest text-slate-800 dark:text-white">Risk Distribution</CardTitle>
                        <CardDescription className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Institutional Placement Readiness</CardDescription>
                    </CardHeader>
                    <CardContent className="pt-8">
                        <div className="h-[320px] w-full relative">
                            <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie
                                        data={analytics.riskData}
                                        cx="50%"
                                        cy="50%"
                                        innerRadius={85}
                                        outerRadius={115}
                                        paddingAngle={10}
                                        dataKey="value"
                                        stroke="none"
                                        cornerRadius={8}
                                    >
                                        {analytics.riskData.map((entry, index) => (
                                            <Cell
                                                key={`cell-${index}`}
                                                fill={entry.color}
                                                className="hover:opacity-80 transition-opacity duration-300 cursor-pointer shadow-xl"
                                                strokeWidth={2}
                                            />
                                        ))}
                                    </Pie>
                                    <Tooltip
                                        contentStyle={{
                                            backgroundColor: '#0f172a',
                                            borderRadius: '20px',
                                            border: '1px solid rgba(255,255,255,0.1)',
                                            boxShadow: '0 25px 50px -12px rgba(0,0,0,0.5)',
                                            color: '#fff',
                                            padding: '12px 16px',
                                            fontWeight: '900',
                                            textTransform: 'uppercase',
                                            fontSize: '10px',
                                            letterSpacing: '0.1em'
                                        }}
                                        itemStyle={{ color: '#fff' }}
                                    />
                                </PieChart>
                            </ResponsiveContainer>
                            {/* Center PRI Display */}
                            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Avg Index</p>
                                <p className="text-5xl font-black text-slate-800 dark:text-white tracking-tighter">{analytics.avgPRI}</p>
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4 mt-8">
                            {analytics.riskData.map((item, idx) => (
                                <div key={idx} className="flex items-center gap-3 p-3 rounded-2xl bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-800/50">
                                    <div className="h-3 w-3 rounded-full" style={{ backgroundColor: item.color }} />
                                    <div className="flex flex-col">
                                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{item.name}</span>
                                        <span className="text-sm font-black text-slate-700 dark:text-slate-200">{item.value} Users</span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </CardContent>
                </Card>

                {/* Performance Growth - Neon Area Chart */}
                <Card className="lg:col-span-8 border-none bg-white dark:bg-slate-900 shadow-3xl rounded-[40px] overflow-hidden group">
                    <CardHeader className="pb-2">
                        <div className="flex items-center justify-between mb-2">
                            <div className="h-10 w-10 bg-blue-500/10 rounded-xl flex items-center justify-center border border-blue-500/20">
                                <TrendingUp className="h-5 w-5 text-blue-500" />
                            </div>
                            <div className="flex gap-2">
                                <Badge variant="secondary" className="text-[9px] font-black uppercase tracking-widest bg-blue-50 text-blue-600 dark:bg-blue-900/20">2024 Audit</Badge>
                                <Badge variant="outline" className="text-[9px] font-black uppercase tracking-widest">Active Cohort</Badge>
                            </div>
                        </div>
                        <CardTitle className="text-lg font-black uppercase tracking-widest text-slate-800 dark:text-white">Institutional Growth Trend</CardTitle>
                        <CardDescription className="text-[10px] font-bold uppercase tracking-widest text-slate-400">PRI Consistency Metrics Over Strategic Eras</CardDescription>
                    </CardHeader>
                    <CardContent className="pt-10">
                        <div className="h-[380px] w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <AreaChart data={analytics.consistencyTrendData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                                    <defs>
                                        <linearGradient id="colorScore" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2} />
                                            <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                                        </linearGradient>
                                        <linearGradient id="colorAvg" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.1} />
                                            <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0} />
                                        </linearGradient>
                                    </defs>
                                    <XAxis
                                        dataKey="name"
                                        axisLine={false}
                                        tickLine={false}
                                        tick={{ fontSize: 10, fontWeight: 900, fill: '#64748b' }}
                                        dy={10}
                                    />
                                    <YAxis
                                        axisLine={false}
                                        tickLine={false}
                                        tick={{ fontSize: 10, fontWeight: 900, fill: '#64748b' }}
                                    />
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(100,116,139,0.1)" />
                                    <Tooltip
                                        contentStyle={{
                                            backgroundColor: '#0f172a',
                                            borderRadius: '20px',
                                            border: 'none',
                                            boxShadow: '0 25px 50px -12px rgba(0,0,0,0.5)',
                                            padding: '16px',
                                            fontWeight: '900',
                                            textTransform: 'uppercase',
                                            fontSize: '10px',
                                            color: '#fff'
                                        }}
                                        cursor={{ stroke: '#3b82f6', strokeWidth: 2, strokeDasharray: '5 5' }}
                                    />
                                    <Area
                                        type="monotone"
                                        dataKey="score"
                                        stroke="#3b82f6"
                                        strokeWidth={4}
                                        fillOpacity={1}
                                        fill="url(#colorScore)"
                                        animationDuration={2000}
                                    />
                                    <Area
                                        type="monotone"
                                        dataKey="avg"
                                        stroke="#8b5cf6"
                                        strokeWidth={2}
                                        strokeDasharray="10 10"
                                        fillOpacity={1}
                                        fill="url(#colorAvg)"
                                    />
                                </AreaChart>
                            </ResponsiveContainer>
                        </div>
                    </CardContent>
                </Card>

                {/* Module Benchmarking */}
                <Card className="lg:col-span-12 border-slate-200 dark:border-slate-800 shadow-xl overflow-hidden bg-white/50 dark:bg-slate-900/50 backdrop-blur-md">
                    <CardHeader className="border-b border-slate-100 dark:border-slate-800/60 pb-4">
                        <CardTitle className="text-base font-black uppercase tracking-widest">Global Module Benchmarking</CardTitle>
                        <CardDescription className="text-[10px] font-bold uppercase tracking-tight text-slate-400">Average Score Distribution Across Competency Domains</CardDescription>
                    </CardHeader>
                    <CardContent className="pt-8">
                        <div className="h-[350px] w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={analytics.modulePerformance} margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" strokeOpacity={0.5} />
                                    <XAxis dataKey="name" fontSize={10} fontWeight="black" tickLine={false} axisLine={false} tick={{ dy: 10 }} />
                                    <YAxis fontSize={10} fontWeight="bold" tickLine={false} axisLine={false} domain={[0, 100]} />
                                    <Tooltip
                                        cursor={{ fill: '#f1f5f9' }}
                                        contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1)', fontWeight: 'bold' }}
                                    />
                                    <Bar dataKey="score" radius={[8, 8, 0, 0]} barSize={60}>
                                        {analytics.modulePerformance.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={entry.fill} />
                                        ))}
                                    </Bar>
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </CardContent>
                </Card>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { db } from "@/lib/firebase";
import { collection, getDocs, getDoc, doc, deleteDoc, updateDoc, writeBatch, query, where } from "firebase/firestore";
import { calculatePRI } from "@/lib/placement-calculations";
import { User as AppUser } from "@/types";
import {
    Loader2,
    RefreshCw,
    Trash2,
    Download,
    AlertTriangle,
    ShieldAlert,
    Database,
    Eraser,
    UserX,
    Shield,
    HardDrive,
    CloudDownload,
    Terminal,
    Zap,
    History,
    Fingerprint,
    Globe,
    Briefcase,
    Users
} from "lucide-react";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
    DialogFooter
} from "@/components/ui/dialog";

export default function AdminDataControl() {
    const [isRecalculating, setIsRecalculating] = useState(false);
    const [isDeletingStudents, setIsDeletingStudents] = useState(false);
    const [isExporting, setIsExporting] = useState(false);
    const [isCleaning, setIsCleaning] = useState(false);
    const [isNormalizing, setIsNormalizing] = useState(false);
    const [isDeletingTest, setIsDeletingTest] = useState(false);
    const [isBackingUp, setIsBackingUp] = useState(false);
    const [isSyncing, setIsSyncing] = useState(false);

    // 1. Recalculate All PRI Scores
    const handleRecalculatePRI = async () => {
        setIsRecalculating(true);
        try {
            const studentsRef = collection(db, "users");
            const q = query(studentsRef, where("role", "==", "student"));
            const querySnapshot = await getDocs(q);

            const batch = writeBatch(db);
            let updateCount = 0;

            querySnapshot.forEach((docSnap) => {
                const studentData = { id: docSnap.id, ...docSnap.data() } as AppUser;
                const priData = calculatePRI(studentData);
                const docRef = doc(db, "users", docSnap.id);
                batch.update(docRef, { cachedPRI: priData.pri, lastCalculated: new Date() });
                updateCount++;
            });

            if (updateCount > 0) {
                await batch.commit();
                toast.success(`Metrics recalculated for ${updateCount} identity nodes.`);
            } else {
                toast.info("No identity records found in targeting vector.");
            }
        } catch (error: any) {
            console.error(error);
            toast.error("Recalculation fault intercepted.");
        } finally {
            setIsRecalculating(false);
        }
    };

    // 2. Export Data (CSV)
    const handleExport = async (type: "students" | "faculty") => {
        setIsExporting(true);
        try {
            const colRef = collection(db, "users");
            const q = query(colRef, where("role", "==", type));
            const querySnapshot = await getDocs(q);

            if (querySnapshot.empty) {
                toast.info(`No segments found for ${type} export.`);
                setIsExporting(false);
                return;
            }

            const headers = ["ID", "Name", "Email", "Department", "Role", "Approved", "Registered At"];
            const rows = [headers.join(",")];

            querySnapshot.forEach(docSnap => {
                const data = docSnap.data();
                const row = [
                    docSnap.id,
                    `"${data.name || ''}"`,
                    `"${data.email || ''}"`,
                    `"${data.department || ''}"`,
                    `"${data.role || ''}"`,
                    data.approved ? "Yes" : "No",
                    data.createdAt ? new Date(data.createdAt.seconds * 1000).toLocaleDateString() : "Unknown"
                ];
                rows.push(row.join(","));
            });

            const csvContent = rows.join("\n");
            const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
            const url = URL.createObjectURL(blob);

            const link = document.createElement("a");
            link.href = url;
            link.setAttribute("download", `alsa_${type}_export_${new Date().toISOString().split('T')[0]}.csv`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

            toast.success(`${type} segment exported to CSV.`);
        } catch (error: any) {
            toast.error("Export integrity fault.");
        } finally {
            setIsExporting(false);
        }
    };

    // 3. Bulk Delete Engine
    const handleBulkDelete = async (type: "students" | "faculty") => {
        const setLoadState = type === "students" ? setIsDeletingStudents : () => { };
        setLoadState(true);
        try {
            const colRef = collection(db, "users");
            const q = query(colRef, where("role", "==", type));
            const querySnapshot = await getDocs(q);

            const deletePromises = querySnapshot.docs.map(d => deleteDoc(doc(db, "users", d.id)));
            await Promise.all(deletePromises);

            toast.success(`Structural purge complete: ${deletePromises.length} nodes deleted.`);
        } catch (error: any) {
            toast.error("Purge operation intercepted logic error.");
        } finally {
            setLoadState(false);
        }
    };

    // 4. Clean Orphan Records
    const handleCleanOrphans = async () => {
        setIsCleaning(true);
        try {
            const usersRef = collection(db, "users");
            const snap = await getDocs(usersRef);
            let deletedCount = 0;
            const batch = writeBatch(db);

            snap.forEach(docSnap => {
                const data = docSnap.data();
                if (!data.role || !data.email) {
                    batch.delete(doc(db, "users", docSnap.id));
                    deletedCount++;
                }
            });
            if (deletedCount > 0) await batch.commit();

            toast.success(`Orphan cleanup successfully processed ${deletedCount} nodes.`);
        } catch (e: any) {
            toast.error("Cleanup fault intercepted.");
        } finally {
            setIsCleaning(false);
        }
    };

    const handleNormalizeDepartments = async () => {
        setIsNormalizing(true);
        try {
            const usersRef = collection(db, "users");
            const snap = await getDocs(usersRef);
            let updateCount = 0;
            const batch = writeBatch(db);
            const { normalizeDepartment } = await import("@/lib/department-core");

            snap.forEach(docSnap => {
                const data = docSnap.data();
                if (data.department) {
                    const normalized = normalizeDepartment(data.department);
                    if (normalized !== data.department) {
                        batch.update(doc(db, "users", docSnap.id), { department: normalized });
                        updateCount++;
                    }
                }
            });

            if (updateCount > 0) {
                await batch.commit();
                toast.success(`Department normalization complete for ${updateCount} nodes.`);
            } else {
                toast.info("Institutional headers are already normalized.");
            }
        } catch (e: any) {
            toast.error("Normalization fault.");
        } finally {
            setIsNormalizing(false);
        }
    };

    const handleDeleteTestUsers = async () => {
        setIsDeletingTest(true);
        try {
            const usersRef = collection(db, "users");
            const snap = await getDocs(usersRef);
            let deletedCount = 0;
            const batch = writeBatch(db);

            snap.forEach(docSnap => {
                const data = docSnap.data();
                const email = data.email?.toLowerCase() || "";
                const name = data.name?.toLowerCase() || "";
                if (email.includes("test") || name.includes("test")) {
                    batch.delete(doc(db, "users", docSnap.id));
                    deletedCount++;
                }
            });
            if (deletedCount > 0) await batch.commit();

            toast.success(`Test account purge verified for ${deletedCount} nodes.`);
        } catch (e: any) {
            toast.error("Atomic test purge failed.");
        } finally {
            setIsDeletingTest(false);
        }
    };

    const handleBackupDB = async () => {
        setIsBackingUp(true);
        try {
            const usersRef = collection(db, "users");
            const issuesRef = collection(db, "system_issues");
            const [uSnap, iSnap] = await Promise.all([getDocs(usersRef), getDocs(issuesRef)]);

            const backup = {
                users: uSnap.docs.map(d => ({ id: d.id, ...d.data() })),
                system_issues: iSnap.docs.map(d => ({ id: d.id, ...d.data() })),
                timestamp: new Date().toISOString()
            };

            const blob = new Blob([JSON.stringify(backup, null, 2)], { type: "application/json" });
            const url = URL.createObjectURL(blob);
            const link = document.createElement("a");
            link.href = url;
            link.setAttribute("download", `alsa_snapshot_${new Date().toISOString().split('T')[0]}.json`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

            toast.success("Institutional snapshot downloaded safely.");
        } catch (e: any) {
            toast.error("Back-up integrity fault.");
        } finally {
            setIsBackingUp(false);
        }
    };

    return (
        <div className="space-y-10 animate-in fade-in duration-700 pb-12">
            {/* Premium Data Engine Hero */}
            <div className="relative rounded-[48px] overflow-hidden bg-slate-950 border border-white/5 shadow-3xl group">
                {/* Visual Background Elements */}
                <div className="absolute inset-0 bg-[radial-gradient(circle_at_20%_-30%,rgba(59,130,246,0.15),transparent_70%)]" />
                <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-[0.02] mix-blend-overlay" />

                <div className="relative z-10 p-12 md:p-16 flex flex-col lg:flex-row justify-between items-center gap-12">
                    <div className="max-w-3xl space-y-8">
                        <div className="inline-flex items-center gap-3 px-4 py-2 bg-blue-500/10 rounded-full border border-blue-500/20 backdrop-blur-md">
                            <Database className="h-3.5 w-3.5 text-blue-400" />
                            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-300">Core Engine Control</span>
                        </div>

                        <div className="space-y-4">
                            <h1 className="text-6xl md:text-8xl font-black text-white tracking-tighter leading-[0.85]">
                                Data <br />
                                <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 via-indigo-400 to-purple-400">Control</span>
                            </h1>
                            <p className="text-slate-400 font-medium text-lg md:text-xl max-w-xl leading-relaxed">
                                Managing institutional data structures with <span className="text-white font-bold">atomic precision</span>. Perform bulk operations, exports, and structural purges.
                            </p>
                        </div>

                        <div className="flex flex-wrap gap-8 pt-4">
                            <div className="flex flex-col gap-1">
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Active Storage</span>
                                <div className="flex items-center gap-3">
                                    <span className="text-3xl font-black text-white">Firestore</span>
                                    <div className="h-2 w-2 rounded-full bg-blue-500 animate-pulse shadow-[0_0_10px_rgba(59,130,246,0.5)]" />
                                </div>
                            </div>
                            <div className="w-px h-12 bg-white/5" />
                            <div className="flex flex-col gap-1">
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Latency Node</span>
                                <div className="flex items-center gap-2">
                                    <Zap className="h-5 w-5 text-blue-400" />
                                    <span className="text-sm font-bold text-slate-200">24ms (Nominal)</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="lg:w-[320px]">
                        <div className="relative group/core">
                            <div className="absolute inset-0 bg-blue-500/20 blur-[100px] rounded-full group-hover/core:bg-blue-500/30 transition-colors duration-1000" />
                            <div className="relative bg-white/5 backdrop-blur-3xl rounded-[40px] p-10 border border-white/10 shadow-2xl flex flex-col items-center justify-center text-center">
                                <Terminal className="h-16 w-16 text-blue-400/20 mb-6 group-hover/core:text-blue-400 transition-colors duration-700" />
                                <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">System Core</p>
                                <p className="text-5xl font-black text-white tracking-tighter">DBX</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="grid gap-8 lg:grid-cols-2">
                {/* Maintenance Cluster */}
                <Card className="border-slate-200 dark:border-slate-800 shadow-xl bg-white/50 dark:bg-slate-900/50 backdrop-blur-md overflow-hidden">
                    <CardHeader className="border-b border-slate-100 dark:border-slate-800/60 p-6 flex flex-row items-center gap-4">
                        <div className="h-10 w-10 rounded-xl bg-indigo-50 dark:bg-indigo-950/40 flex items-center justify-center border border-indigo-100 dark:border-indigo-900/60">
                            <RefreshCw className="h-5 w-5 text-indigo-600" />
                        </div>
                        <div>
                            <CardTitle className="text-sm font-black uppercase tracking-widest">Structural Maintenance</CardTitle>
                            <CardDescription className="text-[10px] font-bold uppercase tracking-tight text-slate-400">Optimization & Normalization Ops</CardDescription>
                        </div>
                    </CardHeader>
                    <CardContent className="p-8 space-y-6">
                        {[
                            {
                                title: "Recalculate PRI Vectors",
                                desc: "Re-triggers weighted calculations across the student spectrum to refresh cached placement indices.",
                                icon: Zap,
                                action: handleRecalculatePRI,
                                loading: isRecalculating,
                                btnText: "Execute Calculation Cycle"
                            },
                            {
                                title: "Institutional Normalization",
                                desc: "Standardizes departmental nomenclature using canonical mapping to ensure analytics consistency.",
                                icon: Globe,
                                action: handleNormalizeDepartments,
                                loading: isNormalizing,
                                btnText: "Normalize Headers"
                            },
                            {
                                title: "Orphaned Node Cleanup",
                                desc: "Scans for and purges user objects with fragmented fields or partial initialization states.",
                                icon: Eraser,
                                action: handleCleanOrphans,
