                                        <DialogHeader>
                                            <div className="h-16 w-16 rounded-[24px] bg-rose-50 flex items-center justify-center mb-6">
                                                <AlertTriangle className="h-10 w-10 text-rose-500" />
                                            </div>
                                            <DialogTitle className="text-2xl font-black tracking-tight text-slate-900 uppercase">Confirm Structural Purge</DialogTitle>
                                            <DialogDescription className="text-slate-500 text-base leading-relaxed pt-2">
                                                You are about to execute a destructive operation. This will permanently erase targeted identity nodes from the institutional database. This action is <b>restricted and irreversible</b> without a JSON snapshot.
                                            </DialogDescription>
                                        </DialogHeader>
                                        <DialogFooter className="mt-8 flex items-center justify-between gap-4">
                                            <Button variant="ghost" className="rounded-xl font-black uppercase tracking-widest text-[10px]">Abandon Protocol</Button>
                                            <Button
                                                variant="destructive"
                                                onClick={sanction.action}
                                                disabled={sanction.loading}
                                                className="rounded-2xl h-14 px-8 font-black uppercase tracking-[0.1em] text-[11px] bg-rose-600 shadow-xl shadow-rose-600/20"
                                            >
                                                {sanction.loading ? (
                                                    <>
                                                        <Loader2 className="w-4 h-4 animate-spin mr-2" />
                                                        Executing...
                                                    </>
                                                ) : (
                                                    "Acknowledge & Execute"
                                                )}
                                            </Button>
                                        </DialogFooter>
                                    </DialogContent>
                                </Dialog>
                            </div>
                        ))}
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { collection, getDocs, updateDoc, doc, deleteDoc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { toast } from "sonner";
import { ServerCrash, Eraser, AlertTriangle, Loader2 } from "lucide-react";
import { User as AppUser } from "@/types";

export default function DataControlPage() {
    const [processingD, setProcessingD] = useState(false);
    const [processingE, setProcessingE] = useState(false);
    const [processingS, setProcessingS] = useState(false);

    const syncStudentsCollection = async () => {
        setProcessingS(true);
        try {
            const snap = await getDocs(collection(db, "users"));
            const users = snap.docs.map(d => ({ id: d.id, ...d.data() }) as AppUser);
            const students = users.filter(u => u.role === "student");

            const batchPromises = students.map(s => {
                const studentId = s.id || s.registerNumber || s.registerNo;
                if (!studentId) return Promise.resolve();
                return updateDoc(doc(db, "students", studentId), s as any).catch(() =>
                    // Fallback to setDoc if it doesn't exist
                    import("firebase/firestore").then(mod => mod.setDoc(doc(db, "students", studentId), s, { merge: true }))
                );
            });

            await Promise.all(batchPromises);
            toast.success(`Successfully synced ${students.length} students to the dedicated collection.`);
        } catch (e) {
            toast.error("Failed to sync students: " + (e as Error).message);
        } finally {
            setProcessingS(false);
        }
    };

    const wipeAllEnrichments = async () => {
        const confirm1 = window.confirm("WARNING: Are you sure you want to delete ALL enrichment records for ALL users?");
        if (!confirm1) return;

        const confirm2 = window.prompt("Type 'CONFIRM' to wipe all enrichment data.");
        if (confirm2 !== "CONFIRM") {
            toast.error("Wipe cancelled.");
            return;
        }

        setProcessingE(true);
        try {
            const snap = await getDocs(collection(db, "users"));
            const batchPromises = snap.docs.map(d => updateDoc(doc(db, "users", d.id), {
                academicEnrichment: [],
                appliedKnowledge: [],
                academicEngagement: [],
                certifications: [],
                competitions: [],
                extraCurricular: []
            }));
            await Promise.all(batchPromises);
            toast.success("Successfully wiped all enrichment records globally.");
        } catch (e) {
            toast.error("Failed to wipe enrichment data: " + (e as Error).message);
        } finally {
            setProcessingE(false);
        }
    };

    const wipeAllSystemData = async () => {
        const confirm1 = window.confirm("CRITICAL DANGER: Are you sure you want to DELETE ALL STUDENTS AND FACULTY from the database?");
        if (!confirm1) return;

        const confirm2 = window.prompt("Type 'NUKE SYSTEM' to permanently delete all non-admin user data.");
        if (confirm2 !== "NUKE SYSTEM") {
            toast.error("System wipe cancelled.");
            return;
        }

        setProcessingD(true);
        try {
            const snap = await getDocs(collection(db, "users"));
            const users = snap.docs.map(d => ({ id: d.id, ...d.data() }) as AppUser);

            // Filter out Admins to prevent locking ourselves out
            const toDelete = users.filter(u => u.role !== "admin");

            const batchPromises = toDelete.map(u => deleteDoc(doc(db, "users", u.id)));
            await Promise.all(batchPromises);

            toast.success(`Successfully deleted ${toDelete.length} user records.`);
        } catch (e) {
            toast.error("Failed to wipe system data: " + (e as Error).message);
        } finally {
            setProcessingD(false);
        }
    };

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-3xl font-bold tracking-tight text-red-600">Data Control Center</h1>
                <p className="text-muted-foreground">Perform mass data wiping and global system resets. Use with extreme caution.</p>
            </div>

            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                <Card className="border-blue-200 shadow-md">
                    <CardHeader className="bg-blue-50 rounded-t-lg">
                        <CardTitle className="flex items-center gap-2 text-blue-800">
                            <ServerCrash className="w-5 h-5 rotate-180" /> Sync Collections
                        </CardTitle>
                        <CardDescription className="text-blue-700/80">
                            Port pre-registered users to the student database.
                        </CardDescription>
                    </CardHeader>
                    <CardContent className="pt-6">
                        <p className="text-sm text-muted-foreground mb-4">
                            If Faculty member dashboards show 0 students instead of the true count, use this to clone missing student records from the master 'users' collection into the 'students' sub-system.
                        </p>
                    </CardContent>
                    <CardFooter>
                        <Button
                            variant="outline"
                            className="w-full border-blue-500 text-blue-600 hover:bg-blue-100"
                            onClick={syncStudentsCollection}
                            disabled={processingS || processingD || processingE}
                        >
                            {processingS ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Syncing...</> : "Sync Students Database"}
                        </Button>
                    </CardFooter>
                </Card>
                <Card className="border-amber-200 shadow-md">
                    <CardHeader className="bg-amber-50 rounded-t-lg">
                        <CardTitle className="flex items-center gap-2 text-amber-800">
                            <Eraser className="w-5 h-5" /> Wipe Enrichments
                        </CardTitle>
                        <CardDescription className="text-amber-700/80">
                            Removes all enrichment, certification, and extracurricular records from every user.
                        </CardDescription>
                    </CardHeader>
                    <CardContent className="pt-6">
                        <p className="text-sm text-muted-foreground mb-4">
                            This action iterates through all registered users (Faculty and Students) and resets their portfolio activity arrays to empty. Base profiles and academic records will remain untouched.
                        </p>
                    </CardContent>
                    <CardFooter>
                        <Button
                            variant="outline"
                            className="w-full border-amber-500 text-amber-600 hover:bg-amber-100"
                            onClick={wipeAllEnrichments}
                            disabled={processingE || processingD}
                        >
                            {processingE ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Processing...</> : "Wipe All Enrichment Data"}
                        </Button>
                    </CardFooter>
                </Card>

                <Card className="border-red-200 shadow-md">
                    <CardHeader className="bg-red-50 rounded-t-lg">
                        <CardTitle className="flex items-center gap-2 text-red-800">
                            <ServerCrash className="w-5 h-5" /> Global System Wipe
                        </CardTitle>
                        <CardDescription className="text-red-700/80">
                            Permanently deletes ALL students and faculty members.
                        </CardDescription>
                    </CardHeader>
                    <CardContent className="pt-6">
                        <div className="flex items-start gap-3 bg-red-100/50 p-4 rounded-md border border-red-200">
                            <AlertTriangle className="w-5 h-5 text-red-600 shrink-0 mt-0.5" />
                            <div className="text-sm text-red-900 leading-relaxed">
                                <strong>Warning:</strong> This will destroy the entire user database including portfolios, placements, and risk logs. Admin accounts will be preserved to maintain dashboard access.
                            </div>
                        </div>
                    </CardContent>
                    <CardFooter>
                        <Button
                            variant="destructive"
                            className="w-full"
                            onClick={wipeAllSystemData}
                            disabled={processingE || processingD}
                        >
                            {processingD ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Nuking Database...</> : "Delete All System Data"}
                        </Button>
                    </CardFooter>
                </Card>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { User as AppUser } from "@/types";
import { collection, query, where, getDocs, updateDoc, doc, serverTimestamp } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { toast } from "sonner";
import { Check, X, Loader2, ShieldCheck, UserPlus, Building2, Mail, Briefcase } from "lucide-react";
import { useAuth } from "@/context/auth-context";
import { deleteUserCompletely } from "@/lib/firestore";

export default function FacultyApprovalsPage() {
    const [faculty, setFaculty] = useState<AppUser[]>([]);
    const [loading, setLoading] = useState(true);
    const [processingId, setProcessingId] = useState<string | null>(null);

    const fetchFaculty = async () => {
        setLoading(true);
        try {
            const q = query(collection(db, "users"), where("role", "==", "faculty"));
            const snap = await getDocs(q);
            const data = snap.docs.map(d => ({ id: d.id, ...d.data() }) as AppUser);
            // Sort to put pending first
            data.sort((a, b) => {
                if (a.approved === b.approved) return 0;
                return a.approved ? 1 : -1;
            });
            setFaculty(data);
        } catch (e) {
            console.error(e);
            toast.error("Failed to fetch faculty list");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchFaculty();
    }, []);

    const { user: adminUser } = useAuth();

    const handleApprove = async (id: string, name: string) => {
        setProcessingId(id);
        try {
            await updateDoc(doc(db, "users", id), {
                approved: true,
                approvedBy: adminUser?.id || "admin_system",
                approvedAt: serverTimestamp()
            });
            await updateDoc(doc(db, "faculty", id), {
                approved: true
            });
            toast.success(`Approved faculty member: ${name}`);
            setFaculty(prev => prev.map(f => f.id === id ? { ...f, approved: true } : f));
        } catch (e) {
            toast.error("Failed to approve faculty");
        } finally {
            setProcessingId(null);
        }
    };

    const handleReject = async (id: string, name: string) => {
        if (!confirm(`Are you sure you want to reject and delete the application for ${name}?`)) return;

        setProcessingId(id);
        try {
            await deleteUserCompletely(id);
            toast.success(`Rejected and removed faculty: ${name}`);
            setFaculty(prev => prev.filter(f => f.id !== id));
        } catch (e) {
            console.error(e);
            toast.error("Failed to reject faculty");
        } finally {
            setProcessingId(null);
        }
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-700">
            {/* Hero Header */}
            <div className="relative rounded-3xl overflow-hidden bg-gradient-to-br from-slate-900 via-slate-800 to-indigo-950 shadow-2xl p-8 text-white">
                <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top_right,rgba(255,255,255,0.1),transparent_50%)]" />
                <div className="absolute -bottom-8 -right-8 h-48 w-48 rounded-full bg-white/5 blur-3xl" />
                <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div>
                        <div className="flex items-center gap-3 mb-3">
                            <div className="h-10 w-10 bg-blue-500 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/20">
                                <ShieldCheck className="h-6 w-6 text-white" />
                            </div>
                            <p className="text-xs font-black uppercase tracking-[0.3em] text-blue-400">Security Clearance</p>
                        </div>
                        <h1 className="text-4xl font-black mb-2 tracking-tight">Faculty Approvals</h1>
                        <p className="text-slate-400 font-medium max-w-xl">Review credentials and authorize access for newly registered academic staff members.</p>
                    </div>
                    <div className="bg-white/10 backdrop-blur-md rounded-2xl p-6 border border-white/10">
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Pending Requests</p>
                        <p className="text-4xl font-black text-white">{faculty.filter(f => !f.approved).length}</p>
                    </div>
                </div>
            </div>

            <Card className="border-slate-200 dark:border-slate-800 shadow-xl overflow-hidden group">
                <CardHeader className="bg-slate-50/50 dark:bg-slate-900/50 border-b border-slate-100 dark:border-slate-800/60 pb-6 px-8 flex flex-row items-center justify-between">
                    <div>
                        <CardTitle className="text-xl font-black text-slate-800 dark:text-white uppercase tracking-tight">Approval Queue</CardTitle>
                        <CardDescription className="font-medium text-slate-500">Real-time listing of faculty account requests.</CardDescription>
                    </div>
                    <Button variant="outline" size="sm" onClick={fetchFaculty} disabled={loading} className="rounded-lg border-slate-300 dark:border-slate-700 font-bold uppercase tracking-widest text-[10px] h-8">
                        {loading ? <Loader2 className="h-3 w-3 animate-spin mr-2" /> : null}
                        Refresh Data
                    </Button>
                </CardHeader>
                <CardContent className="p-0">
                    {loading ? (
                        <div className="flex flex-col items-center justify-center p-20 gap-4">
                            <Loader2 className="w-12 h-12 animate-spin text-blue-500" />
                            <p className="text-sm font-black uppercase tracking-widest text-slate-400 animate-pulse">Syncing encrypted data...</p>
                        </div>
                    ) : faculty.length === 0 ? (
                        <div className="text-center p-20 flex flex-col items-center gap-4">
                            <div className="h-16 w-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center">
                                <UserPlus className="h-8 w-8 text-slate-400" />
                            </div>
                            <p className="font-bold text-slate-500">No faculty members found in the system.</p>
                        </div>
                    ) : (
                        <Table>
                            <TableHeader>
                                <TableRow className="bg-slate-50/50 dark:bg-slate-900/50 hover:bg-slate-50/50 dark:hover:bg-slate-900/50 border-b border-slate-100 dark:border-slate-800">
                                    <TableHead className="font-black text-[10px] uppercase tracking-widest text-slate-500 px-8 h-12">Name & Email</TableHead>
                                    <TableHead className="font-black text-[10px] uppercase tracking-widest text-slate-500 h-12">Role Details</TableHead>
                                    <TableHead className="font-black text-[10px] uppercase tracking-widest text-slate-500 h-12">Status</TableHead>
                                    <TableHead className="text-right font-black text-[10px] uppercase tracking-widest text-slate-500 px-8 h-12">Actions</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {faculty.map((member) => (
                                    <TableRow key={member.id} className="hover:bg-slate-50/30 dark:hover:bg-slate-800/30 transition-colors border-b border-slate-100 dark:border-slate-800">
                                        <TableCell className="px-8 py-5">
                                            <div className="flex flex-col">
                                                <span className="font-black text-slate-800 dark:text-white text-base tracking-tight">{member.name}</span>
                                                <span className="text-xs font-semibold text-slate-400 flex items-center gap-1.5 mt-0.5">
                                                    <Mail className="h-3 w-3" /> {member.email}
                                                </span>
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="flex flex-col gap-1.5">
                                                <div className="flex items-center gap-2">
                                                    <Building2 className="h-3.5 w-3.5 text-blue-500" />
                                                    <span className="text-xs font-bold text-slate-700 dark:text-slate-300">{member.department || "General"}</span>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <Briefcase className="h-3.5 w-3.5 text-indigo-500" />
                                                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">{member.designation || "Faculty Member"}</span>
                                                </div>
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            {member.approved ? (
                                                <Badge className="bg-emerald-500 hover:bg-emerald-600 text-[10px] font-black uppercase tracking-widest border-none px-3 py-1 shadow-lg shadow-emerald-500/20">
                                                    <Check className="h-3 w-3 mr-1" /> Approved
                                                </Badge>
                                            ) : (
                                                <Badge variant="outline" className="text-amber-500 border-amber-500/50 bg-amber-500/5 text-[10px] font-black uppercase tracking-widest px-3 py-1">
                                                    <Loader2 className="h-3 w-3 mr-1 animate-spin" /> Pending
                                                </Badge>
                                            )}
                                        </TableCell>
                                        <TableCell className="text-right px-8 py-5">
                                            {!member.approved && (
                                                <div className="flex items-center justify-end gap-3 animate-in fade-in slide-in-from-right-2">
                                                    <Button
                                                        variant="outline"
                                                        size="sm"
                                                        className="h-9 px-4 rounded-xl border-emerald-500/30 text-emerald-600 dark:text-emerald-400 hover:bg-emerald-50 dark:hover:bg-emerald-950/30 hover:border-emerald-500 font-bold uppercase tracking-widest text-[10px] transition-all"
                                                        onClick={() => handleApprove(member.id, member.name)}
                                                        disabled={processingId === member.id}
                                                    >
                                                        {processingId === member.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Check className="w-3.5 h-3.5 mr-2" />}
                                                        Approve
                                                    </Button>
                                                    <Button
                                                        variant="outline"
                                                        size="sm"
                                                        className="h-9 px-4 rounded-xl border-rose-500/30 text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-950/30 hover:border-rose-500 font-bold uppercase tracking-widest text-[10px] transition-all"
                                                        onClick={() => handleReject(member.id, member.name)}
                                                        disabled={processingId === member.id}
                                                    >
                                                        {processingId === member.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <X className="w-3.5 h-3.5 mr-2" />}
                                                        Reject
                                                    </Button>
                                                </div>
                                            )}
                                        </TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState, useEffect, useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { collection, query, onSnapshot, updateDoc, doc, deleteDoc, orderBy } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { toast } from "sonner";
import {
    AlertCircle,
    CheckCircle2,
    Search,
    Trash2,
    Eye,
    ShieldAlert,
    AlertTriangle,
    ShieldCheck,
    Terminal,
    Activity,
    Zap,
    History,
    MoreVertical,
    Loader2,
    Globe,
    UserCircle
} from "lucide-react";
import { format } from "date-fns";

export default function AdminIssueMonitor() {
    const [issues, setIssues] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    // Filters
    const [statusFilter, setStatusFilter] = useState<string>("all");
    const [priorityFilter, setPriorityFilter] = useState<string>("all");
    const [searchQuery, setSearchQuery] = useState("");

    // Details/Action Dialog
    const [selectedIssue, setSelectedIssue] = useState<any>(null);
    const [resolutionNote, setResolutionNote] = useState("");
    const [isResolving, setIsResolving] = useState(false);

    useEffect(() => {
        const q = query(collection(db, "system_issues"), orderBy("timestamp", "desc"));
        const unsubscribe = onSnapshot(q, (snapshot) => {
            const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setIssues(data);
            setLoading(false);
        }, (error) => {
            console.error(error);
            toast.error("Failed to sync diagnostics.");
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    const kpis = useMemo(() => {
        const totalOpen = issues.filter(i => i.status === "open").length;
        const totalResolved = issues.filter(i => i.status === "resolved").length;
        const criticalCount = issues.filter(i => i.status === "open" && i.priority === "critical").length;

        return { totalOpen, totalResolved, criticalCount };
    }, [issues]);

    const filteredIssues = useMemo(() => {
        return issues.filter(i => {
            if (statusFilter !== "all" && i.status !== statusFilter) return false;
            if (priorityFilter !== "all" && i.priority !== priorityFilter) return false;
            if (searchQuery) {
                const s = searchQuery.toLowerCase();
                return (
                    i.userName?.toLowerCase().includes(s) ||
                    i.department?.toLowerCase().includes(s) ||
                    i.errorType?.toLowerCase().includes(s) ||
                    i.id?.toLowerCase().includes(s)
                );
            }
            return true;
        });
    }, [issues, statusFilter, priorityFilter, searchQuery]);

    const handleResolve = async () => {
        if (!selectedIssue) return;
        setIsResolving(true);
        try {
            await updateDoc(doc(db, "system_issues", selectedIssue.id), {
                status: "resolved",
                resolutionNote: resolutionNote,
                resolvedAt: new Date()
            });
            toast.success("Issue safely mitigated.");
            setSelectedIssue(null);
            setResolutionNote("");
        } catch (e) {
            toast.error("Resolution failed.");
        } finally {
            setIsResolving(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm("Permanently purge this diagnostic trace?")) return;
        try {
            await deleteDoc(doc(db, "system_issues", id));
            toast.success("Trace purged.");
        } catch (e) {
            toast.error("Purge failed.");
        }
    };

    const getPriorityColor = (priority: string) => {
        switch (priority) {
            case "critical": return "bg-rose-500/10 text-rose-600 border-rose-200 shadow-sm shadow-rose-500/10";
            case "high": return "bg-orange-500/10 text-orange-600 border-orange-200";
            case "medium": return "bg-amber-500/10 text-amber-600 border-amber-200";
            case "low": return "bg-blue-500/10 text-blue-600 border-blue-200";
            default: return "bg-slate-500/10 text-slate-600 border-slate-200";
        }
    };

    const formatDate = (timestamp: any) => {
        if (!timestamp) return "Unknown";
        try {
            if (timestamp.toDate) return format(timestamp.toDate(), "MMM d, h:mm a");
            return format(new Date(timestamp), "MMM d, h:mm a");
        } catch (e) {
            return "Invalid Date";
        }
    };

    return (
        <div className="space-y-10 animate-in fade-in duration-700 pb-12">
            {/* Premium Cognitive Sentinel Hero */}
            <div className="relative rounded-[48px] overflow-hidden bg-slate-950 border border-white/5 shadow-3xl group">
                {/* Visual Background Elements */}
                <div className="absolute inset-0 bg-[radial-gradient(circle_at_80%_-20%,rgba(244,63,94,0.15),transparent_70%)]" />
                <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-[0.02] mix-blend-overlay" />

                <div className="relative z-10 p-12 md:p-16 flex flex-col lg:flex-row justify-between items-center gap-12">
                    <div className="max-w-3xl space-y-8">
                        <div className="inline-flex items-center gap-3 px-4 py-2 bg-rose-500/10 rounded-full border border-rose-500/20 backdrop-blur-md">
                            <Activity className="h-3.5 w-3.5 text-rose-400" />
                            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-rose-300">Cognitive Sentinel Protocol</span>
                        </div>

                        <div className="space-y-4">
                            <h1 className="text-6xl md:text-8xl font-black text-white tracking-tighter leading-[0.85]">
                                Issue <br />
                                <span className="text-transparent bg-clip-text bg-gradient-to-r from-rose-400 via-orange-400 to-amber-400">Monitor</span>
                            </h1>
                            <p className="text-slate-400 font-medium text-lg md:text-xl max-w-xl leading-relaxed">
                                Real-time telemetry stream intercepts <span className="text-white font-bold">system exceptions</span> and anomalous behavioral vectors for immediate triage.
                            </p>
                        </div>

                        <div className="flex flex-wrap gap-8 pt-4">
                            <div className="flex flex-col gap-1">
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Active Flaws</span>
                                <div className="flex items-center gap-3">
                                    <span className="text-3xl font-black text-white">{kpis.totalOpen}</span>
                                    {kpis.totalOpen > 0 && <div className="h-2 w-2 rounded-full bg-rose-500 animate-pulse shadow-[0_0_10px_rgba(244,63,94,0.5)]" />}
                                </div>
                            </div>
                            <div className="w-px h-12 bg-white/5" />
                            <div className="flex flex-col gap-1">
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Critical Triage</span>
                                <div className="flex items-center gap-2">
                                    <ShieldAlert className="h-5 w-5 text-rose-400" />
                                    <span className="text-sm font-bold text-slate-200">{kpis.criticalCount} Required</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="lg:w-[320px]">
                        <div className="relative group/radar">
                            <div className="absolute inset-0 bg-rose-500/20 blur-[100px] rounded-full group-hover/radar:bg-rose-500/30 transition-colors duration-1000" />
                            <div className="relative bg-white/5 backdrop-blur-3xl rounded-[40px] p-10 border border-white/10 shadow-2xl flex flex-col items-center justify-center text-center">
                                <Terminal className="h-16 w-16 text-rose-400/20 mb-6 group-hover/radar:text-rose-400 transition-colors duration-700" />
                                <p className="text-[10px] font-black text-rose-400 uppercase tracking-widest mb-1">Telemetry Uplink</p>
                                <p className="text-5xl font-black text-white tracking-tighter italic font-serif">TRCE</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Diagnostic Stream */}
            <Card className="border-slate-200 dark:border-slate-800 shadow-xl bg-white/50 dark:bg-slate-900/50 backdrop-blur-md overflow-hidden">
                <CardHeader className="border-b border-slate-100 dark:border-slate-800/60 pb-6 pt-8">
                    <div className="flex flex-col md:flex-row gap-6 items-end md:items-center justify-between">
                        <div className="relative flex-1 w-full max-w-md group">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400 group-focus-within:text-rose-500 transition-colors" />
                            <Input
                                placeholder="Search by trace ID, user or error vector..."
                                className="pl-12 h-12 bg-white/50 dark:bg-slate-950/50 border-slate-200 dark:border-slate-800 rounded-2xl focus-visible:ring-rose-500/50 transition-all font-medium"
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                            />
                        </div>
                        <div className="flex items-center gap-4 w-full md:w-auto">
                            <Select value={statusFilter} onValueChange={setStatusFilter}>
                                <SelectTrigger className="w-[140px] h-12 rounded-2xl border-slate-200 dark:border-slate-800 bg-white/50 dark:bg-slate-950/50 font-bold uppercase tracking-widest text-[10px]">
                                    <SelectValue placeholder="All Status" />
                                </SelectTrigger>
                                <SelectContent className="rounded-2xl border-slate-200 dark:border-slate-800 backdrop-blur-xl">
                                    <SelectItem value="all" className="font-bold uppercase tracking-widest text-[10px]">All Status</SelectItem>
                                    <SelectItem value="open" className="font-bold uppercase tracking-widest text-[10px]">Active</SelectItem>
                                    <SelectItem value="resolved" className="font-bold uppercase tracking-widest text-[10px]">Mitigated</SelectItem>
                                </SelectContent>
                            </Select>

                            <Select value={priorityFilter} onValueChange={setPriorityFilter}>
                                <SelectTrigger className="w-[140px] h-12 rounded-2xl border-slate-200 dark:border-slate-800 bg-white/50 dark:bg-slate-950/50 font-bold uppercase tracking-widest text-[10px]">
                                    <SelectValue placeholder="All Priority" />
                                </SelectTrigger>
                                <SelectContent className="rounded-2xl border-slate-200 dark:border-slate-800 backdrop-blur-xl">
                                    <SelectItem value="all" className="font-bold uppercase tracking-widest text-[10px]">All Priority</SelectItem>
                                    <SelectItem value="critical" className="font-bold uppercase tracking-widest text-[10px]">Critical</SelectItem>
                                    <SelectItem value="high" className="font-bold uppercase tracking-widest text-[10px]">High</SelectItem>
                                    <SelectItem value="medium" className="font-bold uppercase tracking-widest text-[10px]">Medium</SelectItem>
                                    <SelectItem value="low" className="font-bold uppercase tracking-widest text-[10px]">Low</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </div>
                </CardHeader>
                <CardContent className="p-0">
                    <div className="overflow-x-auto">
                        <Table>
                            <TableHeader className="bg-slate-50/50 dark:bg-slate-900/50 backdrop-blur-md">
                                <TableRow className="border-slate-100 dark:border-slate-800 hover:bg-transparent">
                                    <TableHead className="w-[180px] h-14 pl-8 text-[10px] font-black uppercase tracking-widest text-slate-500">Trace Timestamp</TableHead>
                                    <TableHead className="h-14 text-[10px] font-black uppercase tracking-widest text-slate-500">Origin Node</TableHead>
                                    <TableHead className="h-14 text-[10px] font-black uppercase tracking-widest text-slate-500">Diagnostic Vector</TableHead>
                                    <TableHead className="h-14 text-[10px] font-black uppercase tracking-widest text-slate-500 text-center">Severity</TableHead>
                                    <TableHead className="h-14 text-[10px] font-black uppercase tracking-widest text-slate-500 text-center">Status</TableHead>
                                    <TableHead className="h-14 text-right pr-8 text-[10px] font-black uppercase tracking-widest text-slate-500">Operations</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {loading ? (
                                    <TableRow>
                                        <TableCell colSpan={6} className="h-64 text-center">
                                            <div className="flex flex-col items-center justify-center gap-4">
                                                <Loader2 className="w-8 h-8 animate-spin text-rose-500" />
                                                <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Syncing Diagnostic Monitors...</p>
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                ) : filteredIssues.length === 0 ? (
                                    <TableRow>
                                        <TableCell colSpan={6} className="h-64 text-center">
                                            <div className="flex flex-col items-center justify-center gap-2">
                                                <History className="w-12 h-12 text-slate-200" />
                                                <p className="text-sm font-bold text-slate-400">Diagnostic stream is currently clear.</p>
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    filteredIssues.map((issue) => (
                                        <TableRow key={issue.id} className={`group border-slate-50 dark:border-slate-800/40 hover:bg-rose-50/10 dark:hover:bg-rose-900/5 transition-colors ${issue.status === 'resolved' ? 'opacity-60' : ''}`}>
                                            <TableCell className="py-5 pl-8">
                                                <div className="flex items-center gap-3">
                                                    <Activity className={`w-3 h-3 ${issue.status === 'open' ? 'text-rose-500 animate-pulse' : 'text-slate-400'}`} />
                                                    <p className="text-[11px] font-bold text-slate-500 uppercase tracking-tighter tabular-nums">{formatDate(issue.timestamp)}</p>
                                                </div>
                                            </TableCell>
                                            <TableCell>
                                                <div className="flex flex-col gap-0.5">
                                                    <p className="font-black text-slate-900 dark:text-white text-[12px] tracking-tight truncate max-w-[150px]">{issue.userName || "ANONYMOUS"}</p>
                                                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{issue.department || "No Dept"}</p>
                                                </div>
                                            </TableCell>
                                            <TableCell>
                                                <div className="flex flex-col gap-1">
                                                    <code className="text-[10px] font-black bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-lg text-rose-600 truncate max-w-[200px] border border-slate-200 dark:border-slate-700">
                                                        {issue.errorType}
                                                    </code>
                                                    <p className="text-[9px] font-medium text-slate-400 truncate max-w-[200px]">{issue.page || "/untracked"}</p>
                                                </div>
                                            </TableCell>
                                            <TableCell className="text-center">
                                                <Badge variant="outline" className={`text-[9px] h-5 font-black uppercase tracking-widest rounded-full px-2.5 ${getPriorityColor(issue.priority)}`}>
                                                    {issue.priority}
                                                </Badge>
                                            </TableCell>
                                            <TableCell className="text-center">
                                                {issue.status === "open" ? (
                                                    <div className="flex items-center justify-center gap-2 text-amber-500">
                                                        <AlertCircle className="w-3.5 h-3.5" />
                                                        <span className="text-[10px] font-black uppercase tracking-widest">Active</span>
                                                    </div>
                                                ) : (
                                                    <div className="flex items-center justify-center gap-2 text-emerald-600">
                                                        <CheckCircle2 className="w-3.5 h-3.5" />
                                                        <span className="text-[10px] font-black uppercase tracking-widest">Mitigated</span>
                                                    </div>
                                                )}
                                            </TableCell>
                                            <TableCell className="pr-8 text-right">
                                                <div className="flex items-center justify-end gap-1">
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        className="h-9 w-9 rounded-xl hover:bg-rose-50 dark:hover:bg-rose-950/30"
                                                        onClick={() => setSelectedIssue(issue)}
                                                    >
                                                        <Eye className="h-4 w-4 text-slate-400 group-hover:text-rose-500 transition-colors" />
                                                    </Button>
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        className="h-9 w-9 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800"
                                                        onClick={() => handleDelete(issue.id)}
                                                    >
                                                        <Trash2 className="h-4 w-4 text-slate-400 hover:text-rose-600" />
                                                    </Button>
                                                </div>
                                            </TableCell>
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </Table>
                    </div>
                </CardContent>
            </Card>

            {/* Premium Details & Triage Interface */}
            <Dialog open={!!selectedIssue} onOpenChange={(open) => !open && setSelectedIssue(null)}>
                <DialogContent className="sm:max-w-[700px] max-h-[90vh] overflow-hidden p-0 rounded-[32px] border-slate-200 dark:border-slate-800 shadow-3xl flex flex-col bg-white/95 dark:bg-slate-900/95 backdrop-blur-3xl">
                    <div className="relative h-24 bg-gradient-to-r from-slate-900 to-rose-900 flex items-center px-8 text-white">
                        <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10" />
                        <div className="relative z-10 flex items-center gap-4">
                            <div className="h-12 w-12 bg-white/10 backdrop-blur-xl rounded-2xl flex items-center justify-center border border-white/20">
                                <ShieldAlert className="h-6 w-6 text-rose-300" />
                            </div>
                            <div>
                                <DialogTitle className="text-lg font-black tracking-tight uppercase">Diagnostic Trace</DialogTitle>
                                <DialogDescription className="text-[10px] font-bold text-rose-200 uppercase tracking-widest opacity-80">Reference Node: {selectedIssue?.id}</DialogDescription>
                            </div>
                        </div>
                    </div>

                    <div className="flex-1 overflow-y-auto p-8 space-y-8">
                        <div className="grid grid-cols-2 gap-8">
                            {[
                                { label: "Origin Object", val: selectedIssue?.userName || "Anonymous", icon: UserCircle },
                                { label: "System Vector", val: selectedIssue?.page || "/root", icon: Globe },
                            ].map((item, i) => (
                                <div key={i} className="space-y-2">
                                    <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-slate-400">
                                        <item.icon className="w-3 h-3" />
                                        {item.label}
                                    </div>
                                    <p className="text-sm font-bold text-slate-900 dark:text-white uppercase tracking-tight">{item.val}</p>
                                </div>
                            ))}
                        </div>

                        <div className="space-y-4">
                            <div className="flex items-center justify-between">
                                <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Exception Payload</h4>
                                <Badge variant="outline" className={`text-[9px] h-5 font-black uppercase tracking-widest rounded-full px-2.5 ${getPriorityColor(selectedIssue?.priority)}`}>
                                    {selectedIssue?.priority} Severity
                                </Badge>
                            </div>
                            <div className="bg-slate-900 dark:bg-black rounded-3xl p-6 font-mono text-[11px] leading-relaxed border border-slate-800 shadow-inner group relative">
                                <div className="absolute top-4 right-4 h-2 w-2 rounded-full bg-rose-500 animate-pulse" />
                                <pre className="text-rose-400/90 whitespace-pre-wrap max-h-96 overflow-y-auto custom-scrollbar">
                                    {selectedIssue?.errorMessage}
                                </pre>
                            </div>
                        </div>

                        {selectedIssue?.status === "open" ? (
                            <div className="space-y-4 pt-6 border-t border-slate-100 dark:border-slate-800">
                                <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Mitigation Strategy</h4>
                                <Textarea
                                    placeholder="Record standard operating procedures used for mitigation..."
                                    value={resolutionNote}
                                    onChange={(e) => setResolutionNote(e.target.value)}
                                    className="min-h-[120px] rounded-2xl bg-slate-50 dark:bg-slate-950 border-slate-200 dark:border-slate-800 focus-visible:ring-rose-500/50 p-4 font-medium"
                                />
                            </div>
                        ) : (
                            <div className="space-y-4 pt-6 border-t border-slate-100 dark:border-slate-800">
                                <h4 className="text-[10px] font-black uppercase tracking-widest text-emerald-500">Resolution Log</h4>
                                <div className="p-5 rounded-2xl bg-emerald-500/5 border border-emerald-500/10 italic text-sm text-slate-600 dark:text-slate-400 font-medium">
                                    {selectedIssue?.resolutionNote || "No mitigation notes recorded."}
                                    <p className="mt-3 text-[10px] not-italic font-black uppercase tracking-widest text-emerald-600 opacity-60">
                                        Mitigated on: {formatDate(selectedIssue?.resolvedAt)}
                                    </p>
                                </div>
                            </div>
                        )}
                    </div>

                    <DialogFooter className="p-6 bg-slate-50/50 dark:bg-slate-900/50 backdrop-blur-md border-t border-slate-100 dark:border-slate-800 flex items-center justify-between sm:justify-between px-8">
                        <Button variant="ghost" onClick={() => setSelectedIssue(null)} className="rounded-xl font-black uppercase tracking-widest text-[10px]">Close Trace</Button>
                        {selectedIssue?.status === "open" && (
                            <Button
                                onClick={handleResolve}
                                disabled={isResolving}
                                className="bg-rose-600 hover:bg-rose-700 text-white rounded-xl shadow-lg shadow-rose-600/20 font-black uppercase tracking-widest text-[10px] h-11 px-6"
                            >
                                {isResolving ? (
                                    <>
                                        <Loader2 className="w-4 h-4 animate-spin mr-2" />
                                        Commiting Mitigation...
                                    </>
                                ) : (
                                    <>
                                        <CheckCircle2 className="w-4 h-4 mr-2" />
                                        Mark Mitigated
                                    </>
                                )}
                            </Button>
                        )}
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar {
                    width: 6px;
                }
                .custom-scrollbar::-webkit-scrollbar-track {
                    background: transparent;
                }
                .custom-scrollbar::-webkit-scrollbar-thumb {
                    background: #334155;
                    border-radius: 10px;
                }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover {
                    background: #475569;
                }
            `}</style>
        </div>
    );
}

