                                    {(() => {
                                        const avg = radarData.length > 0 ? Math.round(radarData.reduce((s, d) => s + d.A, 0) / radarData.length) : 0;
                                        const enrichVal = radarData.find(d => d.subject === "Enrichment")?.A || 0;
