                                                        <span className="text-amber-400 dark:text-amber-300 uppercase tracking-widest mr-2 text-[10px]">Missing:</span>
                                                        {readiness.enrichmentBreakdown.missing.join(", ")}
                                                    </p>
                                                </div>
                                            )}
                                        </CardContent>
                                    </Card>
