import { Separator } from "@/components/ui/separator";
import { doc, setDoc, serverTimestamp } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { OutcomeAlignment, CoreAcademicProfile, RoleTrackProfile, CoreTopicSelection } from "@/types";
import { calculateOutcomeAlignmentScore } from "@/lib/academic-calculations";
import { PLACEMENT_ROLES, ROLE_SKILL_MATRIX, PlacementRole, getRolesForDepartment } from "@/lib/role-skills";
import { CORE_ACADEMIC_TOPICS } from "@/lib/core-topics";
import { getCoreSubjects } from "@/lib/department-core";
import { Loader2, Save, BrainCircuit, GraduationCap, Target, Sparkles } from "lucide-react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { ScrollArea } from "@/components/ui/scroll-area";

const CORE_SUBJECT_LABELS: Record<string, string> = {
    // Labels are now mostly identity or slightly cleaned
};

export default function OutcomeAlignmentPage() {
    const { user, updateUserProfile } = useAuth();
    const router = useRouter();
    const [loading, setLoading] = useState(false);

    // STATE - Core Topics
    const [selectedCoreTopics, setSelectedCoreTopics] = useState<CoreTopicSelection>({
        "Aptitude": [],
        "Communication": [],
        "Data Structures": [],
        "Algorithms": [],
        "DBMS": [],
        "Operating Systems": [],
        "Computer Networks": [],
        "OOPS": [],
        "Problem Solving": []
    });

    // STATE - Role Track
    const [selectedTrack, setSelectedTrack] = useState<string>("");
    const [conceptState, setConceptState] = useState<{
        core: string[];
        intermediate: string[];
        advanced: string[];
    }>({ core: [], intermediate: [], advanced: [] });

    // Load existing data
    useEffect(() => {
        if (user && user.outcomeAlignment) {
            const oa = user.outcomeAlignment;

            // Load Core Topics if available
            if (oa.coreTopics) {
                setSelectedCoreTopics(prev => ({
                    ...prev,
                    ...oa.coreTopics
                }));
            }

            // Role
            if (oa.role) {
                setSelectedTrack(oa.role.trackSelected || "");
                setConceptState({
                    core: oa.role?.concepts?.core || [],
                    intermediate: oa.role?.concepts?.intermediate || [],
                    advanced: oa.role?.concepts?.advanced || []
                });
            } else if (oa.track) {
                // Legacy support
                setSelectedTrack(oa.track);
            }
        } else if (user?.placementMetrics?.preferredRole) {
            // Very old legacy
            setSelectedTrack(user.placementMetrics.preferredRole);
        }
    }, [user]);

    // HANDLERS
    const handleTrackChange = (track: string) => {
        // Reset concepts if changing track manually
        if (track !== selectedTrack) {
            setConceptState({ core: [], intermediate: [], advanced: [] });
        }
        setSelectedTrack(track);
    };

    const toggleConcept = (category: keyof typeof conceptState, concept: string) => {
        setConceptState(prev => {
            const current = prev[category];
            const updated = current.includes(concept)
                ? current.filter(s => s !== concept)
                : [...current, concept];
            return { ...prev, [category]: updated };
        });
    };

    const handleSelectAllConcept = (category: keyof typeof conceptState, select: boolean) => {
        if (!currentTrackMatrix) return;
        setConceptState(prev => ({
            ...prev,
            [category]: select ? [...currentTrackMatrix[category]] : []
        }));
    };

    // Calculate Core Profile Dynamically
    const calculatedCoreProfile = useMemo(() => {
        const dept = user?.department || "CSE";
        const mandatorySubjects = getCoreSubjects(dept);
        const profile: Record<string, number> = {};
        let totalScore = 0;

        mandatorySubjects.forEach(subject => {
            const allTopics = (CORE_ACADEMIC_TOPICS as any)[subject] || [];
            const selected = (selectedCoreTopics as any)[subject] || [];
            const score = allTopics.length > 0
                ? Math.round((selected.length / allTopics.length) * 100)
                : 0;

            profile[subject] = score;
            totalScore += score;
        });

        const coreCoverage = mandatorySubjects.length > 0 ? Math.round(totalScore / mandatorySubjects.length) : 0;
        return {
            ...profile,
            coreCoverage
        };
    }, [selectedCoreTopics, user?.department]);


    const handleSave = async () => {
        setLoading(true);

        try {
            // 1. Prepare Data
            const updatedCoreProfile = calculatedCoreProfile;

            const updatedRoleProfile: RoleTrackProfile = {
                trackSelected: selectedTrack,
                concepts: {
                    core: conceptState.core,
                    intermediate: conceptState.intermediate,
                    advanced: conceptState.advanced
                },
                roleTrackCoverage: 0
            };

            // 2. Calculate Role Coverage locally for storage
            let roleCov = 0;
            if (selectedTrack) {
                const matrix = ROLE_SKILL_MATRIX[selectedTrack as PlacementRole];
                if (matrix) {
                    const corePct = matrix.core.length > 0 ? (conceptState.core.length / matrix.core.length) * 100 : 0;
                    const interPct = matrix.intermediate.length > 0 ? (conceptState.intermediate.length / matrix.intermediate.length) * 100 : 0;
                    const advPct = matrix.advanced.length > 0 ? (conceptState.advanced.length / matrix.advanced.length) * 100 : 0;
                    roleCov = (0.5 * corePct) + (0.3 * interPct) + (0.2 * advPct);
                }
            }
            updatedRoleProfile.roleTrackCoverage = Math.round(Number.isNaN(roleCov) ? 0 : roleCov);

            // 3. Construct OutcomeAlignment
            const alignmentData: OutcomeAlignment = {
                core: updatedCoreProfile,
                role: updatedRoleProfile,
                coreTopics: selectedCoreTopics, // Save topics!
                score: 0,
                lastUpdated: new Date().toISOString()
            };

            // 4. Calculate Final Score
            const finalScore = calculateOutcomeAlignmentScore(alignmentData);
            alignmentData.score = finalScore;

            // 5. Save to Firestore
            await updateUserProfile({
                coreAcademicProfile: updatedCoreProfile,
                roleTrackProfile: updatedRoleProfile,
                coreAcademicTopics: selectedCoreTopics, // Explicit top-level save
                outcomeAlignment: alignmentData,
                // Explicitly sync scores for Faculty Portal visibility
                priScore: finalScore,
                riskLevel: finalScore >= 75 ? "Ready" : finalScore >= 60 ? "Moderate" : "High"
            });

            // Analytics History
            if (user?.id) {
                const alignRef = doc(db, "users", user.id, "academicOutcomes", "alignment");
                await setDoc(alignRef, { ...alignmentData, updatedAt: serverTimestamp() });
            }

            toast.success("Outcome Alignment updated successfully!");
        } catch (error) {
            console.error("Error saving alignment:", error);
            toast.error("Failed to save alignment data.");
        } finally {
            setLoading(false);
        }
    };

    // Current calculations for UI feedback
    const currentTrackMatrix = selectedTrack ? ROLE_SKILL_MATRIX[selectedTrack as PlacementRole] : null;

    // Department-filtered roles
    const departmentRoles = useMemo(() => {
        return getRolesForDepartment(user?.department || "CSE");
    }, [user?.department]);

    // Quick role calc for display
    let currentRoleScore = 0;
    if (currentTrackMatrix) {
        const corePct = currentTrackMatrix.core.length > 0 ? (conceptState.core.length / currentTrackMatrix.core.length) * 100 : 0;
        const interPct = currentTrackMatrix.intermediate.length > 0 ? (conceptState.intermediate.length / currentTrackMatrix.intermediate.length) * 100 : 0;
        const advPct = currentTrackMatrix.advanced.length > 0 ? (conceptState.advanced.length / currentTrackMatrix.advanced.length) * 100 : 0;
        currentRoleScore = (0.5 * corePct) + (0.3 * interPct) + (0.2 * advPct);
    }

    const currentFinalScore = selectedTrack
        ? Math.round((0.5 * calculatedCoreProfile.coreCoverage!) + (0.5 * currentRoleScore))
        : calculatedCoreProfile.coreCoverage!;

    const displayScore = Math.round(Number.isNaN(currentFinalScore) ? 0 : currentFinalScore);


    return (
        <div className="space-y-8 max-w-5xl mx-auto pb-10 animate-in fade-in duration-500">
            {/* ΓöÇΓöÇ Hero Header ΓöÇΓöÇ */}
            <div className="relative rounded-3xl overflow-hidden bg-gradient-to-br from-indigo-900 via-purple-900 to-indigo-950 shadow-[0_10px_40px_-10px_rgba(79,70,229,0.5)] dark:shadow-[0_10px_40px_-10px_rgba(30,27,75,0.8)] p-8 md:p-10 text-white group">
                <div className="absolute inset-0 bg-[url('/noise.png')] opacity-10 mix-blend-overlay pointer-events-none"></div>
                <div className="absolute right-0 top-0 h-full w-1/2 bg-gradient-to-l from-white/10 to-transparent blur-3xl group-hover:from-white/20 transition-all duration-1000" />
                <div className="absolute -bottom-20 -right-20 h-64 w-64 rounded-full bg-blue-500/20 blur-3xl animate-pulse" />
                <div className="absolute -top-20 -left-20 h-64 w-64 rounded-full bg-purple-500/20 blur-3xl animate-pulse" style={{ animationDelay: '1s' }} />

                <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-8">
                    <div className="space-y-4 max-w-2xl">
                        <div className="inline-flex items-center gap-2 rounded-full bg-white/10 dark:bg-slate-900/40 px-3 py-1 text-[10px] font-black uppercase tracking-[0.2em] backdrop-blur-md border border-white/20 text-white shadow-inner">
                            <Sparkles className="h-3 w-3 text-amber-300" />
                            <span>Student Intelligence Portal</span>
                        </div>
                        <h1 className="text-4xl md:text-5xl font-black tracking-tight text-transparent bg-clip-text bg-gradient-to-r from-white to-indigo-100 drop-shadow-sm">Development Alignment</h1>
                        <p className="text-white/80 font-medium text-base md:text-lg leading-relaxed">
                            Define your career trajectory and map your skills to industry standards. This drives your Professional Readiness Index (PRI).
                        </p>
                    </div>
                    <div className="relative group/circle shrink-0 mt-4 md:mt-0">
                        <div className="absolute -inset-2 bg-gradient-to-tr from-emerald-400 via-teal-500 to-emerald-300 rounded-full blur-xl opacity-40 group-hover/circle:opacity-70 group-hover/circle:blur-2xl transition duration-700 animate-spin-slow" />
                        <div className="relative flex flex-col h-32 w-32 md:h-40 md:w-40 items-center justify-center rounded-full bg-white/10 dark:bg-slate-900/30 border-4 border-white/20 shadow-2xl group-hover/circle:border-emerald-400 group-hover/circle:scale-105 transition-all duration-500 backdrop-blur-xl">
                            <span className="text-4xl md:text-5xl font-black text-white drop-shadow-md">{displayScore}</span>
                            <span className="block text-[10px] uppercase tracking-[0.15em] text-emerald-300 mt-1 font-black">Alignment</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* 1. CORE ACADEMIC FOUNDATIONS */}
            <Card className="border-none shadow-xl hover:shadow-2xl transition-all duration-500 bg-white dark:bg-slate-900 group relative overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-br from-indigo-50/50 to-transparent dark:from-indigo-900/10 opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none" />
                <CardHeader className="relative z-10 border-b border-slate-100 dark:border-slate-800 pb-5">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-indigo-100 dark:bg-indigo-900/50 rounded-xl shadow-inner border border-indigo-200 dark:border-indigo-800 group-hover:scale-110 transition-transform duration-300">
                            <BrainCircuit className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />
                        </div>
                        <div>
                            <CardTitle className="text-xl font-black tracking-tight text-slate-800 dark:text-white uppercase">Core Academic Foundations</CardTitle>
                            <CardDescription className="text-sm font-medium text-slate-500 dark:text-slate-400 mt-1">Select the topics you have mastered in each mandatory core domain.</CardDescription>
                        </div>
                    </div>
                </CardHeader>
                <CardContent>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">
                        {getCoreSubjects(user?.department || "CSE").map((subject) => {
                            const topics = (CORE_ACADEMIC_TOPICS as any)[subject] || [];
                            const score = (calculatedCoreProfile as any)[subject] || 0;
                            const selectedCount = (selectedCoreTopics as any)[subject]?.length || 0;
                            const allSelected = selectedCount === topics.length && topics.length > 0;

                            return (
                                <div key={subject} className="space-y-4 p-5 border-2 rounded-2xl bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800 hover:border-indigo-300 dark:hover:border-indigo-700/50 transition-colors shadow-sm relative overflow-hidden group/subject">
                                    <div className="absolute inset-0 bg-gradient-to-br from-indigo-50/50 to-transparent dark:from-indigo-900/10 opacity-0 group-hover/subject:opacity-100 transition-opacity duration-300 pointer-events-none" />
                                    <div className="relative z-10 flex justify-between items-center mb-1">
                                        <div className="flex items-center gap-2">
                                            <Label className="font-black text-slate-800 dark:text-slate-200 text-lg cursor-pointer tracking-tight" htmlFor={`all-${subject}`}>{subject}</Label>
                                        </div>
                                        <Badge className={cn("px-2.5 py-1 text-[10px] font-black uppercase tracking-widest shadow-sm", score >= 80 ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/50 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800' : score >= 50 ? 'bg-amber-100 text-amber-700 dark:bg-amber-900/50 dark:text-amber-300 border border-amber-200 dark:border-amber-800' : 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300 border border-slate-200 dark:border-slate-700')}>
                                            {score}% ({selectedCount}/{topics.length})
                                        </Badge>
                                    </div>

                                    <div className="relative z-10 flex items-center space-x-2 py-2 border-b-2 border-slate-100 dark:border-slate-800 mb-2 pb-3">
                                        <Checkbox
                                            id={`all-${subject}`}
                                            checked={allSelected}
                                            onCheckedChange={(checked) => {
                                                setSelectedCoreTopics(prev => ({
                                                    ...prev,
                                                    [subject]: checked ? [...topics] : []
                                                }));
                                            }}
                                            className="data-[state=checked]:bg-indigo-600 data-[state=checked]:border-indigo-600 border-slate-300 dark:border-slate-600"
                                        />
                                        <Label htmlFor={`all-${subject}`} className="text-[11px] font-black text-slate-500 dark:text-slate-400 cursor-pointer uppercase tracking-widest hover:text-indigo-600 dark:hover:text-indigo-400 transition-colors">
                                            Select All
                                        </Label>
                                    </div>

                                    <ScrollArea className="h-48 w-full pr-4 relative z-10">
                                        <div className="space-y-2.5">
                                            {topics.map((topic: string) => (
                                                <div key={topic} className="flex items-start space-x-3 p-2 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                                    <Checkbox
                                                        id={`${subject}-${topic}`}
                                                        checked={(selectedCoreTopics as any)[subject]?.includes(topic)}
                                                        onCheckedChange={() => {
                                                            setSelectedCoreTopics(prev => {
                                                                const currentList = (prev as any)[subject] || [];
                                                                const updatedList = currentList.includes(topic)
                                                                    ? currentList.filter((t: string) => t !== topic)
                                                                    : [...currentList, topic];
                                                                return { ...prev, [subject]: updatedList };
                                                            });
                                                        }}
                                                        className="mt-0.5 data-[state=checked]:bg-indigo-600 data-[state=checked]:border-indigo-600 border-slate-300 dark:border-slate-600"
                                                    />
                                                    <Label
                                                        htmlFor={`${subject}-${topic}`}
                                                        className="text-sm font-semibold text-slate-700 dark:text-slate-300 leading-tight cursor-pointer flex-1"
                                                    >
                                                        {topic}
                                                    </Label>
                                                </div>
                                            ))}
                                        </div>
                                    </ScrollArea>
                                </div>
                            );
                        })}
                    </div>
                    <div className="mt-8 flex justify-between items-center bg-gradient-to-r from-indigo-50 to-purple-50 dark:from-indigo-950/30 dark:to-purple-950/30 p-5 rounded-xl border border-indigo-100 dark:border-indigo-900/50 shadow-sm relative z-10">
                        <span className="font-black text-indigo-900 dark:text-indigo-200 uppercase tracking-widest text-sm">Total Core Coverage</span>
                        <div className="flex items-baseline gap-1">
                            <span className="text-3xl font-black text-indigo-600 dark:text-indigo-400 drop-shadow-sm">{calculatedCoreProfile.coreCoverage}</span>
                            <span className="text-lg font-bold text-indigo-400 dark:text-indigo-600">%</span>
                        </div>
                    </div>
                </CardContent>
            </Card>


            {/* 2. TRACK SELECTION */}
            <Card className="border-none shadow-xl hover:shadow-2xl transition-all duration-500 bg-white dark:bg-slate-900 group relative overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-br from-violet-50/50 to-transparent dark:from-violet-900/10 opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none" />
                <CardHeader className="relative z-10 border-b border-slate-100 dark:border-slate-800 pb-5">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-violet-100 dark:bg-violet-900/50 rounded-xl shadow-inner border border-violet-200 dark:border-violet-800 group-hover:scale-110 transition-transform duration-300">
                            <GraduationCap className="h-6 w-6 text-violet-600 dark:text-violet-400" />
                        </div>
                        <div>
                            <CardTitle className="text-xl font-black tracking-tight text-slate-800 dark:text-white uppercase">Outcome Alignment</CardTitle>
                            <CardDescription className="text-sm font-medium text-slate-500 dark:text-slate-400 mt-1">Select the specialized track that aligns with your professional goals.</CardDescription>
                        </div>
                    </div>
                </CardHeader>
                <CardContent className="relative z-10 pt-6">
                    <div className="flex flex-col space-y-4 max-w-xl">
                        <Label className="font-black text-slate-700 dark:text-slate-300 text-xs uppercase tracking-widest">Target Track</Label>
                        <Select
                            value={selectedTrack}
                            onValueChange={handleTrackChange}
                        >
                            <SelectTrigger className="w-full text-lg h-14 bg-slate-50 dark:bg-slate-950 border-2 border-slate-200 dark:border-slate-800 focus:ring-violet-500 focus:border-violet-500 rounded-xl shadow-sm transition-all focus:-translate-y-0.5 font-bold text-slate-800 dark:text-slate-200">
                                <SelectValue placeholder="Choose an Academic Track" />
                            </SelectTrigger>
                            <SelectContent className="rounded-xl border-2 border-slate-200 dark:border-slate-800 shadow-xl">
                                {departmentRoles.map(role => (
                                    <SelectItem key={role} value={role} className="cursor-pointer font-bold py-3 hover:bg-violet-50 dark:hover:bg-violet-900/30 focus:bg-violet-50 dark:focus:bg-violet-900/30 transition-colors">{role}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>
                </CardContent>
            </Card>

            {/* 3. CONCEPTS MATRIX */}
            {selectedTrack && currentTrackMatrix ? (
                <Card className="border-none shadow-xl transition-all duration-500 bg-white dark:bg-slate-900 animate-in fade-in slide-in-from-top-4 relative overflow-hidden group/matrix">
                    <div className="absolute inset-0 bg-gradient-to-br from-blue-50/50 to-transparent dark:from-blue-900/10 opacity-0 group-hover/matrix:opacity-100 transition-opacity duration-500 pointer-events-none" />
                    <CardHeader className="relative z-10 border-b border-slate-100 dark:border-slate-800 pb-5">
                        <div className="flex items-center gap-4">
                            <div className="p-3 bg-blue-100 dark:bg-blue-900/50 rounded-xl shadow-inner border border-blue-200 dark:border-blue-800">
                                <Target className="h-6 w-6 text-blue-600 dark:text-blue-400" />
                            </div>
                            <div>
                                <CardTitle className="text-xl font-black tracking-tight text-slate-800 dark:text-white uppercase">{selectedTrack} Competency Matrix</CardTitle>
                                <CardDescription className="text-sm font-medium text-slate-500 dark:text-slate-400 mt-1">Validate your mastery of role-specific concepts. This builds your Role Skill Score.</CardDescription>
                            </div>
                        </div>
                    </CardHeader>
                    <CardContent className="relative z-10 pt-8 space-y-10">
                        {/* CORE */}
                        <div className="space-y-5">
                            <div className="flex flex-col md:flex-row md:items-center justify-between border-l-4 border-emerald-500 pl-4 py-2 bg-gradient-to-r from-emerald-50 to-transparent dark:from-emerald-950/30 rounded-r-xl gap-4">
                                <div>
                                    <Label className="text-xl font-black text-emerald-800 dark:text-emerald-400 uppercase tracking-wide">Core Concepts</Label>
                                    <p className="text-xs font-bold text-emerald-600/70 dark:text-emerald-500/70 uppercase tracking-widest mt-1">Foundation (50% Weightage)</p>
                                </div>
                                <div className="flex items-center gap-5 mr-4">
                                    <div className="flex items-center space-x-2 bg-white dark:bg-slate-900 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 shadow-sm">
                                        <Checkbox
                                            id="all-core-concepts"
                                            checked={conceptState.core.length === currentTrackMatrix.core.length && currentTrackMatrix.core.length > 0}
                                            onCheckedChange={(checked) => handleSelectAllConcept("core", checked as boolean)}
                                            className="data-[state=checked]:bg-emerald-600 data-[state=checked]:border-emerald-600"
                                        />
                                        <Label htmlFor="all-core-concepts" className="text-[10px] font-black uppercase tracking-widest cursor-pointer text-slate-600 dark:text-slate-400">Select All</Label>
                                    </div>
                                    <Badge className="bg-emerald-100 text-emerald-800 dark:bg-emerald-900/50 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800 font-black text-sm px-3 py-1 shadow-sm">
                                        {conceptState.core.length} / {currentTrackMatrix.core.length}
                                    </Badge>
                                </div>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                                {currentTrackMatrix.core.map(concept => (
                                    <div key={concept} className={cn("flex items-center space-x-3 p-3.5 rounded-xl border-2 transition-all shadow-sm group/box", conceptState.core.includes(concept) ? "bg-emerald-50 border-emerald-200 dark:bg-emerald-900/20 dark:border-emerald-800" : "bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800 hover:border-emerald-300 dark:hover:border-emerald-700/50")}>
                                        <Checkbox
                                            id={`core-${concept}`}
                                            checked={conceptState.core.includes(concept)}
                                            onCheckedChange={() => toggleConcept("core", concept)}
                                            className="data-[state=checked]:bg-emerald-600 data-[state=checked]:border-emerald-600 border-slate-300 dark:border-slate-600 drop-shadow-sm"
                                        />
                                        <Label htmlFor={`core-${concept}`} className={cn("cursor-pointer flex-1 font-bold text-sm leading-tight transition-colors", conceptState.core.includes(concept) ? "text-emerald-900 dark:text-emerald-100" : "text-slate-700 dark:text-slate-300 group-hover/box:text-slate-900 dark:group-hover/box:text-white")}>{concept}</Label>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* INTERMEDIATE */}
                        <div className="space-y-5">
                            <div className="flex flex-col md:flex-row md:items-center justify-between border-l-4 border-blue-500 pl-4 py-2 bg-gradient-to-r from-blue-50 to-transparent dark:from-blue-950/30 rounded-r-xl gap-4">
                                <div>
                                    <Label className="text-xl font-black text-blue-800 dark:text-blue-400 uppercase tracking-wide">Intermediate Application</Label>
                                    <p className="text-xs font-bold text-blue-600/70 dark:text-blue-500/70 uppercase tracking-widest mt-1">Application (30% Weightage)</p>
                                </div>
                                <div className="flex items-center gap-5 mr-4">
                                    <div className="flex items-center space-x-2 bg-white dark:bg-slate-900 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 shadow-sm">
                                        <Checkbox
                                            id="all-inter-concepts"
                                            checked={conceptState.intermediate.length === currentTrackMatrix.intermediate.length && currentTrackMatrix.intermediate.length > 0}
                                            onCheckedChange={(checked) => handleSelectAllConcept("intermediate", checked as boolean)}
                                            className="data-[state=checked]:bg-blue-600 data-[state=checked]:border-blue-600"
                                        />
                                        <Label htmlFor="all-inter-concepts" className="text-[10px] font-black uppercase tracking-widest cursor-pointer text-slate-600 dark:text-slate-400">Select All</Label>
                                    </div>
                                    <Badge className="bg-blue-100 text-blue-800 dark:bg-blue-900/50 dark:text-blue-300 border border-blue-200 dark:border-blue-800 font-black text-sm px-3 py-1 shadow-sm">
                                        {conceptState.intermediate.length} / {currentTrackMatrix.intermediate.length}
                                    </Badge>
                                </div>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                                {currentTrackMatrix.intermediate.map(concept => (
                                    <div key={concept} className={cn("flex items-center space-x-3 p-3.5 rounded-xl border-2 transition-all shadow-sm group/box", conceptState.intermediate.includes(concept) ? "bg-blue-50 border-blue-200 dark:bg-blue-900/20 dark:border-blue-800" : "bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800 hover:border-blue-300 dark:hover:border-blue-700/50")}>
                                        <Checkbox
                                            id={`inter-${concept}`}
                                            checked={conceptState.intermediate.includes(concept)}
                                            onCheckedChange={() => toggleConcept("intermediate", concept)}
                                            className="data-[state=checked]:bg-blue-600 data-[state=checked]:border-blue-600 border-slate-300 dark:border-slate-600 drop-shadow-sm"
                                        />
                                        <Label htmlFor={`inter-${concept}`} className={cn("cursor-pointer flex-1 font-bold text-sm leading-tight transition-colors", conceptState.intermediate.includes(concept) ? "text-blue-900 dark:text-blue-100" : "text-slate-700 dark:text-slate-300 group-hover/box:text-slate-900 dark:group-hover/box:text-white")}>{concept}</Label>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* ADVANCED */}
                        <div className="space-y-5">
                            <div className="flex flex-col md:flex-row md:items-center justify-between border-l-4 border-purple-500 pl-4 py-2 bg-gradient-to-r from-purple-50 to-transparent dark:from-purple-950/30 rounded-r-xl gap-4">
                                <div>
                                    <Label className="text-xl font-black text-purple-800 dark:text-purple-400 uppercase tracking-wide">Advanced Mastery</Label>
                                    <p className="text-xs font-bold text-purple-600/70 dark:text-purple-500/70 uppercase tracking-widest mt-1">Mastery (20% Weightage)</p>
                                </div>
                                <div className="flex items-center gap-5 mr-4">
                                    <div className="flex items-center space-x-2 bg-white dark:bg-slate-900 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 shadow-sm">
                                        <Checkbox
                                            id="all-adv-concepts"
                                            checked={conceptState.advanced.length === currentTrackMatrix.advanced.length && currentTrackMatrix.advanced.length > 0}
                                            onCheckedChange={(checked) => handleSelectAllConcept("advanced", checked as boolean)}
                                            className="data-[state=checked]:bg-purple-600 data-[state=checked]:border-purple-600"
                                        />
                                        <Label htmlFor="all-adv-concepts" className="text-[10px] font-black uppercase tracking-widest cursor-pointer text-slate-600 dark:text-slate-400">Select All</Label>
                                    </div>
                                    <Badge className="bg-purple-100 text-purple-800 dark:bg-purple-900/50 dark:text-purple-300 border border-purple-200 dark:border-purple-800 font-black text-sm px-3 py-1 shadow-sm">
                                        {conceptState.advanced.length} / {currentTrackMatrix.advanced.length}
                                    </Badge>
                                </div>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                                {currentTrackMatrix.advanced.map(concept => (
                                    <div key={concept} className={cn("flex items-center space-x-3 p-3.5 rounded-xl border-2 transition-all shadow-sm group/box", conceptState.advanced.includes(concept) ? "bg-purple-50 border-purple-200 dark:bg-purple-900/20 dark:border-purple-800" : "bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800 hover:border-purple-300 dark:hover:border-purple-700/50")}>
                                        <Checkbox
                                            id={`adv-${concept}`}
                                            checked={conceptState.advanced.includes(concept)}
                                            onCheckedChange={() => toggleConcept("advanced", concept)}
                                            className="data-[state=checked]:bg-purple-600 data-[state=checked]:border-purple-600 border-slate-300 dark:border-slate-600 drop-shadow-sm"
                                        />
                                        <Label htmlFor={`adv-${concept}`} className={cn("cursor-pointer flex-1 font-bold text-sm leading-tight transition-colors", conceptState.advanced.includes(concept) ? "text-purple-900 dark:text-purple-100" : "text-slate-700 dark:text-slate-300 group-hover/box:text-slate-900 dark:group-hover/box:text-white")}>{concept}</Label>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </CardContent>
                </Card>
            ) : (
                <div className="relative overflow-hidden rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-950 py-16 text-center animate-in fade-in zoom-in-95 duration-500 group hover:border-indigo-300 dark:hover:border-indigo-800 transition-colors">
                    <div className="absolute inset-0 bg-gradient-to-br from-indigo-50/30 to-transparent dark:from-indigo-900/10 opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none" />
                    <div className="relative z-10">
                        <div className="mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-2xl bg-slate-100 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-sm">
                            <Target className="h-8 w-8 text-slate-400 dark:text-slate-500" />
                        </div>
                        <h3 className="text-xl font-black tracking-tight text-slate-800 dark:text-white">Select a Track to Begin</h3>
                        <p className="text-slate-500 dark:text-slate-400 max-w-sm mx-auto mt-2 font-medium text-sm leading-relaxed">
                            Choose an academic track above to view the full competency matrix and map your skills to industry standards.
                        </p>
                    </div>
                </div>
            )}

            {/* 4. SAVE BUTTON */}
            <div className="flex justify-end pt-8 relative z-10">
                <Button
                    onClick={handleSave}
                    disabled={loading || !selectedTrack}
                    className="relative overflow-hidden bg-indigo-600 hover:bg-indigo-700 text-white h-14 px-10 text-lg font-black tracking-wide rounded-xl shadow-xl hover:shadow-indigo-500/25 transition-all duration-300 disabled:opacity-50 group hover:-translate-y-1"
                >
                    <div className="absolute inset-0 bg-gradient-to-r from-white/0 via-white/20 to-white/0 -translate-x-full group-hover:animate-shimmer" />
                    {loading ? (
                        <div className="flex items-center gap-3">
                            <Loader2 className="h-6 w-6 animate-spin text-indigo-200" />
                            <span>Updating Alignment Protocol...</span>
                        </div>
                    ) : (
                        <div className="flex items-center gap-3">
                            <Save className="h-5 w-5" />
                            <span>Commit Developmental Path</span>
                        </div>
                    )}
                </Button>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { useAuth } from "@/context/auth-context";
import { AddEnrichmentDialog } from "@/components/dashboard/add-data-dialogs";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Medal, Trash2, Calendar, Award, BookOpen, Briefcase, FileText, Users, Code, Microscope } from "lucide-react";
import { AcademicEnrichment } from "@/types";
import {
    Dialog,
    DialogClose,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import { calculateEnrichmentScore } from "@/lib/academic-calculations";
import { toast } from "sonner";

const Trophy = Medal;

const TYPE_ICONS: Record<string, any> = {
    "Certification": Award,
    "Competition": Trophy,
    "Workshop": BookOpen,
    "Internship": Briefcase,
    "Publication": FileText,
    "Research": Microscope,
    "Technical Club": Users,
    "Project": Code
};

export default function EnrichmentPage() {
    const { user, updateUserProfile } = useAuth();
    const [isLoading, setIsLoading] = useState(false);
    const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
    const [itemToDelete, setItemToDelete] = useState<string | null>(null);

    const handleSave = async (item: AcademicEnrichment) => {
        setIsLoading(true);
        console.log("Saving Enrichment Record:", item);

        try {
            const currentItems = user?.academicEnrichment || [];
            const updatedItems = [...currentItems, item];

            await updateUserProfile({
                academicEnrichment: updatedItems,
                enrichmentCount: updatedItems.length,
                lastUpdated: new Date().toISOString()
            });
            toast.success("Enrichment record verified and saved!");
        } catch (error) {
            console.error("Save Error:", error);
            toast.error("Failed to sync enrichment record.");
        } finally {
            setIsLoading(false);
        }
    };

    const confirmDelete = () => {
        if (itemToDelete) {
            const currentItems = user?.academicEnrichment || [];
            const updated = currentItems.filter(c => c.id !== itemToDelete);
            updateUserProfile({ academicEnrichment: updated });
            setItemToDelete(null);
            setIsDeleteDialogOpen(false);
            toast.info("Entry removed.");
        }
    };

    const enrichItems = user?.academicEnrichment || [];
    const totalScore = calculateEnrichmentScore(enrichItems);

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-10">
            {/* ΓöÇΓöÇ Hero Header ΓöÇΓöÇ */}
            <div className="relative rounded-3xl overflow-hidden bg-gradient-to-br from-amber-500 via-orange-600 to-rose-700 shadow-xl p-7 text-white">
                <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top_right,rgba(255,255,255,0.15),transparent_60%)]" />
                <div className="absolute -bottom-8 -right-8 h-40 w-40 rounded-full bg-white/5 blur-2xl" />
                <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div>
                        <p className="text-xs font-extrabold uppercase tracking-[0.2em] text-white/50 mb-1">Student Intelligence Portal</p>
                        <h1 className="text-3xl font-black mb-2 tracking-tight">Academic Enrichment Index ≡ƒÅå</h1>
                        <p className="text-white/60 font-medium text-sm">Unified professional readiness portfolio & achievements.</p>
                    </div>
                    <div className="flex flex-col md:flex-row items-center gap-4">
                        <div className="bg-white/10 backdrop-blur-md rounded-2xl p-4 border border-white/20 text-center min-w-[140px]">
                            <p className="text-[10px] uppercase tracking-widest text-white/60 font-black">Enrichment Score</p>
                            <div className="flex items-baseline justify-center gap-1">
                                <span className="text-4xl font-black">{totalScore}</span>
                                <span className="text-sm opacity-60 font-bold">/ 100</span>
                            </div>
                        </div>
                        <AddEnrichmentDialog onSave={handleSave} />
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {enrichItems.map((item) => {
                    const Icon = TYPE_ICONS[item.type] || BookOpen;
                    return (
                        <Card key={item.id} className="relative group hover:shadow-2xl transition-all duration-500 border-none bg-white dark:bg-slate-900 overflow-hidden shadow-lg">
                            <div className={`absolute top-0 left-0 w-1.5 h-full ${item.status === 'Winner' ? 'bg-amber-500' : 'bg-indigo-500'}`} />
                            <CardHeader className="pb-3">
                                <div className="flex justify-between items-start">
                                    <div className="p-2.5 bg-slate-50 dark:bg-slate-800/50 rounded-xl">
                                        <Icon className={`h-6 w-6 ${item.status === 'Winner' ? 'text-amber-500' : 'text-indigo-500'}`} />
                                    </div>
                                    <div className="flex flex-col items-end gap-1.5">
                                        <Badge variant="outline" className="text-[10px] h-5 uppercase tracking-tighter font-extrabold border-slate-200 dark:border-slate-700">
                                            {item.level}
                                        </Badge>
                                        {item.isElite && (
                                            <Badge variant="secondary" className="text-[10px] h-5 bg-amber-50 text-amber-700 dark:bg-amber-900/20 dark:text-amber-400 border-amber-100 dark:border-amber-800/50 font-black">
                                                ELITE / GOLD
                                            </Badge>
                                        )}
                                    </div>
                                </div>
                                <div className="mt-4">
                                    <p className="px-1 text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">
                                        {item.type}
                                    </p>
                                    <CardTitle className="text-lg font-black leading-tight line-clamp-2 text-slate-800 dark:text-white tracking-tight">
                                        {item.title}
                                    </CardTitle>
                                    <CardDescription className="line-clamp-1 mt-1 font-bold italic text-slate-500 dark:text-slate-400/80">
                                        {item.organization}
                                    </CardDescription>
                                </div>
                            </CardHeader>
                            <CardContent>
                                <div className="flex flex-col gap-4">
                                    <div className="flex items-center justify-between text-sm">
                                        <span className="text-slate-500 dark:text-slate-400 font-extrabold uppercase text-[10px] tracking-widest">Outcome</span>
                                        <Badge className={`font-black uppercase text-[10px] border-none ${item.status === 'Winner' ? 'bg-amber-500 text-white' : 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-200'}`}>
                                            {item.status}
                                        </Badge>
                                    </div>

                                    <div className="grid grid-cols-2 gap-2 mt-2">
                                        <div className="bg-slate-50 dark:bg-slate-800/50 p-2 rounded-xl text-center border border-slate-100 dark:border-slate-700/50">
                                            <p className="text-[9px] text-slate-400 dark:text-slate-500 uppercase font-black tracking-tighter">Category</p>
                                            <p className="text-xs font-black text-slate-700 dark:text-slate-300 truncate">{item.category}</p>
                                        </div>
                                        <div className="bg-slate-50 dark:bg-slate-800/50 p-2 rounded-xl text-center border border-slate-100 dark:border-slate-700/50">
                                            <p className="text-[9px] text-slate-400 dark:text-slate-500 uppercase font-black tracking-tighter">Date</p>
                                            <p className="text-xs font-black text-slate-700 dark:text-slate-300">{new Date(item.date).toLocaleDateString('en-GB', { month: 'short', year: 'numeric' })}</p>
                                        </div>
                                    </div>

                                    <div className="pt-2 flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-all duration-300 translate-y-2 group-hover:translate-y-0">
                                        <Button
                                            variant="ghost"
                                            size="sm"
                                            className="h-8 w-8 p-0 text-rose-500 hover:text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-950/30 rounded-full"
                                            onClick={() => {
                                                setItemToDelete(item.id);
                                                setIsDeleteDialogOpen(true);
                                            }}
                                        >
                                            <Trash2 className="h-4 w-4" />
                                        </Button>
                                    </div>
                                </div>
                            </CardContent>
                        </Card>
                    );
                })}

                {enrichItems.length === 0 && (
                    <div className="col-span-full py-20 text-center border-2 border-dashed rounded-3xl bg-muted/10">
                        <Award className="h-16 w-16 mx-auto text-muted-foreground opacity-20 mb-4" />
                        <h3 className="text-xl font-bold">Build Your Professional Portfolio</h3>
                        <p className="text-muted-foreground mb-8 max-w-sm mx-auto">Add certifications, projects, and research to improve your Professional Readiness Index (PRI).</p>
                        <AddEnrichmentDialog onSave={handleSave} />
                    </div>
                )}
            </div>

            {/* Global Delete Confirmation */}
            <Dialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>Delete Entry?</DialogTitle>
                        <DialogDescription>
                            This will remove this enrichment record and impact your overall PRI score. This action cannot be undone.
                        </DialogDescription>
                    </DialogHeader>
                    <DialogFooter className="gap-2 sm:gap-0">
                        <Button variant="outline" onClick={() => setIsDeleteDialogOpen(false)}>Cancel</Button>
                        <Button onClick={confirmDelete} variant="destructive">Delete Permanently</Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useAuth } from "@/context/auth-context";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Clock, LogOut, GraduationCap, ChevronRight } from "lucide-react";
import { toast } from "sonner";
import { updateUserDocument } from "@/lib/firestore";
import { useRouter } from "next/navigation";
import { useEffect } from "react";
import { doc, onSnapshot } from "firebase/firestore";
import { db } from "@/lib/firebase";

export default function PendingApprovalPage() {
    const { user, logout, isLoading } = useAuth();
    const router = useRouter();

    const handleSwitchToStudent = async () => {
        if (!user) return;
        try {
            await updateUserDocument(user.id, {
                role: "student",
                approved: true
            });
            toast.success("Identity updated to Student");
            // The useEffect listener in AuthContext or this page will handle redirection
            router.push("/dashboard/student");
        } catch (error: any) {
            toast.error("Failed to update role: " + error.message);
        }
    };

    useEffect(() => {
        if (!isLoading) {
            if (!user) {
                router.push("/login");
            } else if (!user.role) {
                router.push("/select-role");
            } else if (user.role === "faculty" && user.approved) {
                router.push("/dashboard/faculty");
            } else if (user.role === "student") {
                router.push("/dashboard/student");
            } else if (user.role === "admin") {
                router.push("/admin/dashboard");
            }
        }
    }, [user, isLoading, router]);

    // Real-time listener for admin approval
    useEffect(() => {
        if (!user?.id || user.approved) return;

        const unsubscribe = onSnapshot(doc(db, "users", user.id), (docSnap) => {
            if (docSnap.exists()) {
                const data = docSnap.data();
                if (data.approved) {
                    toast.success("Account approved! Redirecting to dashboard...");
                    // Hardware refresh to fully update auth context state
                    setTimeout(() => {
                        window.location.href = "/dashboard/faculty";
                    }, 1500);
                }
            }
        });

        return () => unsubscribe();
    }, [user?.id, user?.approved]);

    if (isLoading || !user) {
        return <div className="flex items-center justify-center min-h-screen">Loading...</div>;
    }

    return (
        <div className="flex flex-col items-center justify-center min-h-screen bg-muted/40 p-4">
            <Card className="w-full max-w-md shadow-lg border-t-4 border-t-amber-500">
                <CardHeader className="text-center pb-2">
                    <div className="mx-auto mb-4 bg-amber-100 p-3 rounded-full w-16 h-16 flex items-center justify-center text-amber-600">
                        <Clock className="w-8 h-8" />
                    </div>
                    <CardTitle className="text-2xl font-bold">Account Pending</CardTitle>
                    <CardDescription className="text-base mt-2">
                        Your account is under admin review.
                    </CardDescription>
                </CardHeader>
                <CardContent className="text-center space-y-6 pt-4">
                    <div className="space-y-4 text-slate-600 text-sm leading-relaxed">
                        <p>
                            Thank you for registering as faculty. You will be able to access your dashboard and manage students once an administrator approves your account.
                        </p>

                        <div className="bg-amber-50 border border-amber-200 rounded-lg p-4 mt-4">
                            <p className="font-bold text-amber-800 mb-1 flex items-center gap-2">
                                <GraduationCap className="h-4 w-4" /> Are you a Student?
                            </p>
                            <p className="text-amber-700 text-xs">
                                If you are a student and see this page, something went wrong. Please <b>Log Out</b> and sign in again using your official university email.
                            </p>
                        </div>
                    </div>
                    <Button onClick={logout} variant="outline" className="w-full">
                        <LogOut className="w-4 h-4 mr-2" />
                        Log Out
                    </Button>

                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/context/auth-context";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { GraduationCap, Users, ArrowRight, Loader2, BookOpen, Briefcase, Sparkles } from "lucide-react";
import { createUserDocument } from "@/lib/firestore";
import { auth, db } from "@/lib/firebase";
import { doc, setDoc } from "firebase/firestore";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { IT_DEPARTMENTS, CORE_DEPARTMENTS } from "@/lib/department-core";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";

const ALL_DEPARTMENTS = [...IT_DEPARTMENTS, ...CORE_DEPARTMENTS].sort();
const DESIGNATIONS = ["Professor", "Associate Professor", "Assistant Professor", "HOD", "Dean", "Other"];

export default function SelectRolePage() {
    const { user } = useAuth();
    const router = useRouter();
    const [isLoading, setIsLoading] = useState(false);
    const [department, setDepartment] = useState("");
    const [selectedRole, setSelectedRole] = useState<"student" | "faculty" | null>(null);
    const [designation, setDesignation] = useState("");

    // Initialize from user state if available
    useEffect(() => {
        if (user?.role) {
            setSelectedRole(user.role as any);
        }
    }, [user]);

    const handleRegistration = async () => {
        if (!auth.currentUser) return;
        if (!department) {
            toast.error("Please select your department.");
            return;
        }
        if (!selectedRole) {
            toast.error("Please select your role.");
            return;
        }
        if (selectedRole === "faculty" && !designation) {
            toast.error("Please select your designation.");
            return;
        }

        setIsLoading(true);

        try {
            const userData = {
                uid: auth.currentUser.uid,
                name: auth.currentUser.displayName || "Google User",
                email: auth.currentUser.email,
                role: selectedRole,
                department: department,
                approved: selectedRole === "student" ? true : false,
                // Critical: Students must complete their profile details (Reg No, Sem, Year)
                // Faculty must be approved by admin.
                isProfileComplete: false,
                profileCompleted: false,
                areGradesComplete: false,
                gradesCompleted: false,
                ...(selectedRole === "faculty" ? { designation } : {})
            };

            await createUserDocument(auth.currentUser.uid, userData);

            if (selectedRole === "student") {
                await setDoc(doc(db, "students", auth.currentUser.uid), {
                    uid: auth.currentUser.uid,
                    name: auth.currentUser.displayName || "Google User",
                    email: auth.currentUser.email || "",
                    department: department,
                    cgpa: 0,
                    pri: 0,
                    riskLevel: "High",
                    arrears: 0,
                    weakestModule: "None",
                    updatedAt: new Date(),
                }, { merge: true });
            } else if (selectedRole === "faculty") {
                await setDoc(doc(db, "faculty", auth.currentUser.uid), {
                    uid: auth.currentUser.uid,
                    name: auth.currentUser.displayName || "Google User",
                    email: auth.currentUser.email || "",
                    department: department,
                    approved: false,
                    designation: designation,
                }, { merge: true });
            }

            toast.success(`Registered as ${selectedRole.toUpperCase()}`);

            if (selectedRole === "student") {
                // Force to complete profile for Reg No, Year, Semester
                router.push("/complete-profile");
            } else {
                router.push("/faculty/pending-approval");
            }
        } catch (error: any) {
            console.error("Role selection error:", error);
            toast.error("Failed to save role: " + error.message);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950 p-4 font-sans selection:bg-blue-100 dark:selection:bg-blue-900">
            {/* Background elements */}
            <div className="absolute inset-0 bg-[url('/noise.png')] opacity-5 mix-blend-overlay pointer-events-none"></div>
            <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-blue-500/10 dark:bg-blue-500/5 rounded-full blur-[120px] pointer-events-none"></div>
            <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-indigo-500/10 dark:bg-indigo-500/5 rounded-full blur-[120px] pointer-events-none"></div>

            <Card className="w-full max-w-4xl shadow-2xl border-slate-300 dark:border-slate-800 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl overflow-hidden animate-in fade-in zoom-in duration-500">
                <div className="grid md:grid-cols-5 h-full">
                    {/* Left Panel - Branding */}
                    <div className="md:col-span-2 bg-gradient-to-br from-slate-900 via-slate-800 to-indigo-950 p-8 text-white relative overflow-hidden flex flex-col justify-between">
                        <div className="absolute inset-0 bg-[radial-gradient(circle_at_top_right,rgba(255,255,255,0.1),transparent_70%)] opacity-50"></div>
                        <div className="relative z-10">
                            <div className="h-12 w-12 bg-white/10 rounded-xl backdrop-blur-md border border-white/20 flex items-center justify-center mb-6">
                                <Sparkles className="h-6 w-6 text-blue-400" />
                            </div>
                            <h2 className="text-3xl font-black tracking-tighter mb-4 italic uppercase">Identity Setup</h2>
                            <p className="text-slate-400 font-medium leading-relaxed">
                                Join the next generation of professional readiness tracking. Select your role to unlock personalized analytics and growth roadmaps.
                            </p>
                        </div>

                        <div className="space-y-6 relative z-10">
                            <div className="flex items-center gap-4 group">
                                <div className="h-10 w-10 rounded-full bg-blue-500/20 flex items-center justify-center border border-blue-500/30 group-hover:bg-blue-500/40 transition-all">
                                    <BookOpen className="h-5 w-5 text-blue-400" />
                                </div>
                                <div className="text-xs">
                                    <span className="block font-black uppercase text-slate-300 tracking-widest">Academic Hub</span>
                                    <span className="text-slate-500 font-bold">Comprehensive data sync</span>
                                </div>
                            </div>
                            <div className="flex items-center gap-4 group">
                                <div className="h-10 w-10 rounded-full bg-emerald-500/20 flex items-center justify-center border border-emerald-500/30 group-hover:bg-emerald-500/40 transition-all">
                                    <Briefcase className="h-5 w-5 text-emerald-400" />
                                </div>
                                <div className="text-xs">
                                    <span className="block font-black uppercase text-slate-300 tracking-widest">Career Strategy</span>
                                    <span className="text-slate-500 font-bold">AI-driven placement insights</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Right Panel - Form */}
                    <div className="md:col-span-3 p-8 md:p-10 flex flex-col justify-center">
                        <div className="max-w-md mx-auto w-full space-y-8">
                            <div className="space-y-2">
                                <h1 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Final Step, {auth.currentUser?.displayName?.split(" ")[0] || "User"}</h1>
                                <p className="text-sm font-medium text-slate-500 dark:text-slate-400">Complete your profile to access the platform.</p>
                            </div>

                            <div className="space-y-6">
                                {/* Department Selection */}
                                <div className="space-y-3 group/input">
                                    <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500 group-focus-within/input:text-blue-500 transition-colors">
                                        Academic Department
                                    </Label>
                                    <Select value={department} onValueChange={setDepartment}>
                                        <SelectTrigger className="h-12 bg-white dark:bg-slate-950/50 border-slate-300 dark:border-slate-800 shadow-md hover:border-blue-300 dark:hover:border-blue-700 transition-all">
                                            <SelectValue placeholder="Pick your department..." />
                                        </SelectTrigger>
                                        <SelectContent className="max-h-[300px]">
                                            {ALL_DEPARTMENTS.map((dept) => (
                                                <SelectItem key={dept} value={dept} className="font-medium">{dept}</SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>

                                {/* Role Selection Cards (Only show if role not pre-selected) */}
                                {!user?.role && (
                                    <div className="space-y-3">
                                        <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500">
                                            Primary Role
                                        </Label>
                                        <div className="grid grid-cols-2 gap-4">
                                            <button
                                                type="button"
                                                onClick={() => setSelectedRole("student")}
                                                className={cn(
                                                    "p-4 rounded-2xl border-2 transition-all duration-300 text-left relative overflow-hidden group",
                                                    selectedRole === "student"
                                                        ? "bg-blue-50 dark:bg-blue-900/20 border-blue-500 shadow-lg shadow-blue-500/10"
                                                        : "bg-white dark:bg-slate-900/50 border-slate-300 dark:border-slate-800 hover:border-slate-400 dark:hover:border-slate-700"
                                                )}
                                            >
                                                <div className={cn(
                                                    "h-10 w-10 rounded-xl flex items-center justify-center mb-3 transition-colors",
                                                    selectedRole === "student" ? "bg-blue-500 text-white" : "bg-slate-100 dark:bg-slate-800 text-slate-500"
                                                )}>
                                                    <GraduationCap className="h-5 w-5" />
                                                </div>
                                                <span className={cn("block font-black text-sm uppercase", selectedRole === "student" ? "text-blue-600 dark:text-blue-400" : "text-slate-700 dark:text-slate-300")}>Student</span>
                                                <span className="text-[10px] font-medium text-slate-500 dark:text-slate-400 mt-1 block">Full academic & placement hub</span>
                                                {selectedRole === "student" && <div className="absolute top-2 right-2 h-2 w-2 rounded-full bg-blue-500 animate-pulse"></div>}
                                            </button>

                                            <button
                                                type="button"
                                                onClick={() => setSelectedRole("faculty")}
                                                className={cn(
                                                    "p-4 rounded-2xl border-2 transition-all duration-300 text-left relative overflow-hidden group",
                                                    selectedRole === "faculty"
                                                        ? "bg-indigo-50 dark:bg-indigo-900/20 border-indigo-500 shadow-lg shadow-indigo-500/10"
                                                        : "bg-white dark:bg-slate-900/50 border-slate-300 dark:border-slate-800 hover:border-slate-400 dark:hover:border-slate-700"
                                                )}
                                            >
                                                <div className={cn(
                                                    "h-10 w-10 rounded-xl flex items-center justify-center mb-3 transition-colors",
                                                    selectedRole === "faculty" ? "bg-indigo-500 text-white" : "bg-slate-100 dark:bg-slate-800 text-slate-500"
                                                )}>
                                                    <Users className="h-5 w-5" />
                                                </div>
                                                <span className={cn("block font-black text-sm uppercase", selectedRole === "faculty" ? "text-indigo-600 dark:text-indigo-400" : "text-slate-700 dark:text-slate-300")}>Faculty</span>
                                                <span className="text-[10px] font-medium text-slate-500 dark:text-slate-400 mt-1 block">Administration & monitoring</span>
                                                {selectedRole === "faculty" && <div className="absolute top-2 right-2 h-2 w-2 rounded-full bg-indigo-500 animate-pulse"></div>}
                                            </button>
                                        </div>
                                    </div>
                                )}

                                {/* Designation Selection (Faculty Only) */}
                                {selectedRole === "faculty" && (
                                    <div className="space-y-3 group/input animate-in slide-in-from-top-2 duration-300">
                                        <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500 group-focus-within/input:text-indigo-500 transition-colors">
                                            Academic Designation
                                        </Label>
                                        <Select value={designation} onValueChange={setDesignation}>
                                            <SelectTrigger className="h-12 bg-white dark:bg-slate-950/50 border-slate-300 dark:border-slate-800 shadow-md hover:border-indigo-300 dark:hover:border-indigo-700 transition-all">
                                                <SelectValue placeholder="Select your designation..." />
                                            </SelectTrigger>
                                            <SelectContent>
                                                {DESIGNATIONS.map((des) => (
                                                    <SelectItem key={des} value={des} className="font-medium">{des}</SelectItem>
                                                ))}
                                            </SelectContent>
                                        </Select>
                                    </div>
                                )}

                                <Button
                                    onClick={handleRegistration}
                                    disabled={isLoading}
                                    className="w-full h-12 bg-slate-900 dark:bg-white text-white dark:text-slate-900 font-black uppercase tracking-widest shadow-xl hover:shadow-2xl hover:-translate-y-1 transition-all rounded-xl disabled:opacity-50"
                                >
                                    {isLoading ? (
                                        <>
                                            <Loader2 className="h-5 w-5 mr-3 animate-spin" />
                                            Finalizing Account...
                                        </>
                                    ) : (
                                        <>
                                            Complete Registration <ArrowRight className="h-5 w-5 ml-3" />
                                        </>
                                    )}
                                </Button>
                            </div>
                        </div>
                    </div>
                </div>
            </Card>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { getPlacementReadiness, APTITUDE_TOPICS } from "@/lib/placement-calculations";
import { User, PlacementMetrics } from "@/types";

export default function TestAptitudePage() {
    const [results, setResults] = useState<any[]>([]);

    useEffect(() => {
        const runTests = () => {
            const testResults = [];

            // Mock User Factory
            const createMockUser = (aptitude: any): User => {
                return {
                    id: 'test-user',
                    name: 'Test Student',
                    email: 'test@example.com',
                    role: 'student',
                    gender: 'MALE',
                    cgpa: 8.5,
                    standingArrears: 0,
                    placementMetrics: {
                        aptitude: {
                            completionPercentage: 0,
                            topics: [],
                            quantitative: [],
                            logical: [],
                            dataInterpretation: [],
                            verbal: [],
                            confidence: {},
                            ...aptitude
                        },
                        technical: {
                            languages: [{ name: 'Java', level: 'Advanced' }],
                            dsaTopics: ['Arrays', 'Trees', 'Graph', 'DP', 'Stack'], // 5 topics
                            dbTopics: ['SQL Basics']
                        },
                        communication: {
                            fluency: 80,
                            checklists: ['Self Introduction', 'Project Explanation']
                        },
                        aptitudeScore: 0,
                        codingScore: 0,
                        communicationScore: 0,
                        mockInterviewScore: 0,
                        internshipCompleted: false
                    }
                } as User;
            };

            // Test 1: Full Coverage, High Confidence
            const user1 = createMockUser({
                quantitative: APTITUDE_TOPICS.QUANTITATIVE,
                logical: APTITUDE_TOPICS.LOGICAL,
                dataInterpretation: APTITUDE_TOPICS.DATA_INTERPRETATION,
                verbal: APTITUDE_TOPICS.VERBAL,
                confidence: APTITUDE_TOPICS.QUANTITATIVE.reduce((acc: any, t: string) => ({ ...acc, [t]: 'High' }), {})
            });
            const analysis1 = getPlacementReadiness(user1);
            testResults.push({
                name: "Test 1: Full Coverage, High Confidence",
                pri: analysis1.pri,
                tier: analysis1.tier,
                risk: analysis1.finalRisk?.label,
                passed: analysis1.tier === "Ready"
            });

            // Test 2: Partial Coverage
            const user2 = createMockUser({
                quantitative: APTITUDE_TOPICS.QUANTITATIVE.filter((t: string) => t !== "Probability" && t !== "Permutation & Combination"),
                logical: APTITUDE_TOPICS.LOGICAL.filter((t: string) => t !== "Seating Arrangement"),
                dataInterpretation: APTITUDE_TOPICS.DATA_INTERPRETATION,
                verbal: APTITUDE_TOPICS.VERBAL,
                confidence: {}
            });
            const analysis2 = getPlacementReadiness(user2);
            testResults.push({
                name: "Test 2: Missing Probability, P&C, Seating",
                pri: analysis2.pri,
                tier: analysis2.tier,
                risk: analysis2.finalRisk?.label,
                passed: analysis2.pri < 100
            });

            // Test 3: Low Quant Coverage (High Risk Trigger)
            const lowQuantTopics = APTITUDE_TOPICS.QUANTITATIVE.slice(0, 5);
            const user3 = createMockUser({
                quantitative: lowQuantTopics,
                logical: APTITUDE_TOPICS.LOGICAL,
                dataInterpretation: APTITUDE_TOPICS.DATA_INTERPRETATION,
                verbal: APTITUDE_TOPICS.VERBAL,
                confidence: {}
            });
            const analysis3 = getPlacementReadiness(user3);
            testResults.push({
                name: "Test 3: Low Quant Coverage",
                pri: analysis3.pri,
                tier: analysis3.tier,
                risk: analysis3.finalRisk!.label,
                passed: analysis3.tier === "High" || analysis3.tier === "Moderate"
            });

            setResults(testResults);
        };

        runTests();
    }, []);

    return (
        <div className="p-10 font-mono">
            <h1 className="text-2xl font-bold mb-4">Aptitude Module Logic Verification</h1>
            <div className="space-y-4">
                {results.map((res, i) => (
                    <div key={i} className={`p-4 border rounded ${res.passed ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'}`}>
                        <h2 className="font-bold">{res.name}</h2>
                        <pre className="text-xs mt-2 whitespace-pre-wrap">
                            {JSON.stringify(res, null, 2)}
                        </pre>
                        <div className="mt-2 text-sm font-bold">
                            Result: {res.passed ? "PASSED Γ£à" : "FAILED Γ¥î"}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription, SheetFooter } from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { User, Mail, GraduationCap, Phone } from "lucide-react";
import { toast } from "sonner";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { addStudent, checkStudentExists } from "@/lib/firestore";
import { IT_DEPARTMENTS, CORE_DEPARTMENTS } from "@/lib/department-core";

const ALL_DEPARTMENTS = [...IT_DEPARTMENTS, ...CORE_DEPARTMENTS].sort();

interface AddStudentSheetProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onAddStudent?: (student: any) => void;
}

export function AddStudentSheet({ open, onOpenChange, onAddStudent }: AddStudentSheetProps) {
    const [loading, setLoading] = useState(false);
    const [gender, setGender] = useState<"male" | "female" | "">("");

    const [formData, setFormData] = useState({
        registerNumber: "",
        name: "",
        email: "",
        phone: "",
        department: "",
        year: "1",
        section: "A",
    });

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { id, value } = e.target;
        setFormData((prev) => ({ ...prev, [id]: value }));
    };

    const handleSelectChange = (id: string, value: string) => {
        setFormData((prev) => ({ ...prev, [id]: value }));
    };

    const handleSubmit = async () => {
        const { registerNumber, name, email, department } = formData;

        if (!registerNumber || !name || !email || !gender || !department) {
            toast.error("Please fill in all mandatory details (Reg No, Name, Email, Gender, Dept)");
            return;
        }

        setLoading(true);
        try {
            // 1. Check if student already exists
            const exists = await checkStudentExists(registerNumber);
            if (exists) {
                toast.error(`Student with Register No ${registerNumber} already exists!`);
                setLoading(false);
                return;
            }

            // 2. Prepare standardized data as per requirements
            const studentData = {
                ...formData,
                department: department.toUpperCase(),
                gender: gender === "male" ? "MALE" : "FEMALE",
                role: "student",
                certifications: [],
                enrichment: [],
                profileComplete: false,
                riskLevel: "High",
                readinessScore: 0,
            };

            // 3. Save to Firestore
            await addStudent(registerNumber, studentData);

            toast.success("Student added successfully");
            if (onAddStudent) onAddStudent({ id: registerNumber, ...studentData });

            // 4. Reset & Close
            setFormData({
                registerNumber: "",
                name: "",
                email: "",
                phone: "",
                department: "",
                year: "1",
                section: "A",
            });
            setGender("");
            onOpenChange(false);
        } catch (err: any) {
            console.error("Failed to add student:", err);
            toast.error("Failed to add student: " + err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Sheet open={open} onOpenChange={onOpenChange}>
            <SheetContent className="sm:max-w-md w-full flex flex-col h-full p-0">
                <SheetHeader className="px-6 py-4 border-b">
                    <SheetTitle>Add New Student</SheetTitle>
                    <SheetDescription>
                        Register a new student in the system with default "High Risk" status.
                    </SheetDescription>
                </SheetHeader>

                <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
                    <div className="space-y-2">
                        <Label htmlFor="registerNumber">Register Number *</Label>
                        <div className="relative">
                            <GraduationCap className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                            <Input id="registerNumber" placeholder="71762104xxx" className="pl-9" value={formData.registerNumber} onChange={handleInputChange} />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <Label htmlFor="name">Full Name *</Label>
                        <div className="relative">
                            <User className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                            <Input id="name" placeholder="John Doe" className="pl-9" value={formData.name} onChange={handleInputChange} />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 gap-4">
                        <div className="space-y-2">
                            <Label htmlFor="email">Email *</Label>
                            <div className="relative">
                                <Mail className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                                <Input id="email" type="email" placeholder="student@university.edu" className="pl-9" value={formData.email} onChange={handleInputChange} />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="phone">Phone Number</Label>
                            <div className="relative">
                                <Phone className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                                <Input id="phone" placeholder="+91..." className="pl-9" value={formData.phone} onChange={handleInputChange} />
                            </div>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <Label htmlFor="department">Department *</Label>
                        <Select value={formData.department} onValueChange={(val) => handleSelectChange("department", val)}>
                            <SelectTrigger id="department">
                                <SelectValue placeholder="Select Department" />
                            </SelectTrigger>
                            <SelectContent>
                                {ALL_DEPARTMENTS.map(dept => (
                                    <SelectItem key={dept} value={dept}>{dept}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label>Year *</Label>
                            <Select value={formData.year} onValueChange={(val) => handleSelectChange("year", val)}>
                                <SelectTrigger><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="1">1st Year</SelectItem>
                                    <SelectItem value="2">2nd Year</SelectItem>
                                    <SelectItem value="3">3rd Year</SelectItem>
                                    <SelectItem value="4">4th Year</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                        <div className="space-y-2">
                            <Label>Section *</Label>
                            <Select value={formData.section} onValueChange={(val) => handleSelectChange("section", val)}>
                                <SelectTrigger><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="A">Section A</SelectItem>
                                    <SelectItem value="B">Section B</SelectItem>
                                    <SelectItem value="C">Section C</SelectItem>
                                    <SelectItem value="D">Section D</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <Label>Gender *</Label>
                        <div className="grid grid-cols-2 gap-4">
                            <div
                                onClick={() => setGender("male")}
                                className={`cursor-pointer flex items-center justify-center gap-2 p-2 rounded-lg border transition-all ${gender === "male" ? "border-blue-500 bg-blue-50 text-blue-700 font-bold" : "border-input"}`}
                            >
                                <span>≡ƒæ¿</span> Male
                            </div>
                            <div
                                onClick={() => setGender("female")}
                                className={`cursor-pointer flex items-center justify-center gap-2 p-2 rounded-lg border transition-all ${gender === "female" ? "border-pink-500 bg-pink-50 text-pink-700 font-bold" : "border-input"}`}
                            >
                                <span>≡ƒæ⌐</span> Female
                            </div>
                        </div>
                    </div>
                </div>

                <SheetFooter className="px-6 py-4 border-t">
                    <Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button>
                    <Button onClick={handleSubmit} disabled={loading}>
                        {loading ? "Adding..." : "Register Student"}
                    </Button>
                </SheetFooter>
            </SheetContent>
        </Sheet>
    );
}

"use client";

import React, { useEffect } from "react";
import { logSystemIssue } from "@/lib/issue-logger";
import { toast } from "sonner";
import { UserRole } from "@/lib/issue-logger";
import { GlobalErrorBoundary } from "./global-error-boundary";

interface AutoErrorWrapperProps {
    children: React.ReactNode;
    user?: any;
}

export function AutoErrorWrapper({ children, user }: AutoErrorWrapperProps) {
    useEffect(() => {
        // Catch uncaught runtime/async errors (e.g. event handlers)
        const handleWindowError = (event: ErrorEvent) => {
            logSystemIssue({
                role: (user?.role as UserRole) || "SYSTEM",
                userId: user?.id,
                userName: user?.name,
                department: user?.department,
                page: window.location.pathname,
                errorType: "UNKNOWN",
                errorMessage: `Window Error: ${event.message} \n\n Stack: ${event.error?.stack?.substring(0, 500) || "No Stack"}`
            });

            // Prevent default console explosion and stop crash loops
            toast.error("An issue has been reported to Admin.", {
                description: "Our remote monitors captured an application fault.",
                duration: 5000
            });
        };

        // Catch unhandled Promise rejections (e.g. Firebase API failures or calculations failing silently)
        const handleUnhandledRejection = (event: PromiseRejectionEvent) => {
            const reason = event.reason;
            let errorMessage = "Unknown Promise Rejection";

            if (reason instanceof Error) {
                errorMessage = `${reason.name}: ${reason.message} \n\n Stack: ${reason.stack?.substring(0, 500)}`;
            } else if (typeof reason === "string") {
                errorMessage = reason;
            } else {
                errorMessage = JSON.stringify(reason);
            }

            const errorType = errorMessage.toLowerCase().includes("auth") || errorMessage.toLowerCase().includes("permission")
                ? "AUTH_ERROR"
                : "API_ERROR";

            logSystemIssue({
                role: (user?.role as UserRole) || "SYSTEM",
                userId: user?.id,
                userName: user?.name,
                department: user?.department,
                page: window.location.pathname,
                errorType,
                errorMessage: `Promise Rejection: ${errorMessage}`
            });

            toast.error("An issue has been reported to Admin.", {
                description: "Our remote monitors captured a network or sync failure.",
                duration: 5000
            });
        };

        window.addEventListener("error", handleWindowError);
        window.addEventListener("unhandledrejection", handleUnhandledRejection);

        return () => {
            window.removeEventListener("error", handleWindowError);
            window.removeEventListener("unhandledrejection", handleUnhandledRejection);
        };
    }, [user]);

    return (
        <GlobalErrorBoundary user={user}>
            {children}
        </GlobalErrorBoundary>
    );
}

