"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { cn } from "@/lib/utils";
import { useAuth } from "@/context/auth-context";
import { collection, query, where, onSnapshot } from "firebase/firestore";
import { db } from "@/lib/firebase";
import {
    LayoutDashboard,
    Users,
    BookOpen,
    Settings,
    LogOut,
    GraduationCap,
    Medal,
    Activity,
    Briefcase,
    TrendingUp,
    Target,
    Trophy,
    AlertCircle,
} from "lucide-react";
import { Role } from "@/types";

interface SidebarProps extends React.HTMLAttributes<HTMLDivElement> {
    role?: Role;
}

export function Sidebar({ className, role: propRole }: SidebarProps) {
    const pathname = usePathname();
    const { user, logout } = useAuth();

    // Use propRole if provided (e.g. for mobile menu), otherwise use context user role
    const currentRole = (propRole || user?.role || "").toLowerCase();

    const [openIssuesCount, setOpenIssuesCount] = useState(0);
    const [healthStatus, setHealthStatus] = useState<"Healthy" | "Warning" | "Critical">("Healthy");

    useEffect(() => {
        if (currentRole !== "admin") return;

        const q = query(collection(db, "system_issues"), where("status", "==", "open"));
        const unsubscribe = onSnapshot(q, (snapshot) => {
            setOpenIssuesCount(snapshot.size);

            let hasCritical = false;
            let hasMedium = false;

            snapshot.forEach(doc => {
                const priority = doc.data().priority;
                if (priority === "critical" || priority === "high") hasCritical = true;
                if (priority === "medium") hasMedium = true;
            });

            if (hasCritical) setHealthStatus("Critical");
            else if (hasMedium) setHealthStatus("Warning");
            else setHealthStatus("Healthy");
        }, (error) => {
            console.error("Sidebar Issue Sync Error:", error.message);
        });

        return () => unsubscribe();
    }, [currentRole]);

    const facultyRoutes = [
        {
            title: "Professional Readiness",
            href: "/dashboard/faculty",
            icon: LayoutDashboard,
        },
        {
            title: "Risk Monitoring Center",
            href: "/dashboard/faculty/risk-monitor",
            icon: TrendingUp,
        },
        {
            title: "Academic Reports",
            href: "/dashboard/faculty/reports",
            icon: BookOpen,
        },
        {
            title: "My Profile",
            href: "/dashboard/faculty/profile",
            icon: Settings,
        },
    ];

    const studentRoutes = [
        {
            title: "Dashboard",
            href: "/dashboard/student",
            icon: LayoutDashboard,
        },
        {
            title: "Academic Records",
            href: "/dashboard/student/academic-records",
            icon: BookOpen,
        },
        // Development Analytics Group
        {
            title: "Development Analytics",
            href: "#",
            icon: TrendingUp,
            isHeader: true
        },
        {
            title: "Outcome Alignment",
            href: "/dashboard/student/placement/update",
            icon: Target,
        },
        {
            title: "Readiness & Risk Analysis",
            href: "/dashboard/student/placement-insights",
            icon: Activity,
        },
        {
            title: "Academic Enrichment",
            href: "/dashboard/student/portfolio/enrichment",
            icon: Trophy,
        },
        {
            title: "Settings",
            href: "/dashboard/settings",
            icon: Settings,
        },
    ];

    const adminRoutes = [
        {
            title: "Dashboard",
            href: "/admin/dashboard",
            icon: LayoutDashboard,
        },
        {
            title: "System Analytics",
            href: "/admin/system-analytics",
            icon: Activity,
        },
        {
            title: "Issue Monitor",
            href: "/admin/issue-monitor",
            icon: AlertCircle,
            badge: openIssuesCount > 0 ? openIssuesCount : undefined
        },
        {
            title: "Faculty Approvals",
            href: "/admin/faculty-approvals",
            icon: Users,
        },
        {
            title: "User Management",
            href: "/admin/users",
            icon: Briefcase,
        },
        {
            title: "Data Control",
            href: "/admin/data-control",
            icon: Settings,
        },
        {
            title: "Settings",
            href: "/admin/settings",
            icon: Settings,
        },
    ];

    let routes = studentRoutes;
    if (currentRole === "faculty") routes = facultyRoutes;
    else if (currentRole === "admin") routes = adminRoutes;

    // Role-specific accent colours
    const accentActive = currentRole === "faculty"
        ? "bg-gradient-to-r from-indigo-600 to-violet-600 text-white shadow-lg shadow-indigo-200"
        : currentRole === "admin"
            ? "bg-gradient-to-r from-rose-600 to-pink-600 text-white shadow-lg shadow-rose-200"
            : "bg-gradient-to-r from-blue-600 to-cyan-600 text-white shadow-lg shadow-blue-200";

    const accentHover = currentRole === "faculty"
        ? "hover:bg-indigo-50 dark:hover:bg-indigo-950/40 hover:text-indigo-700 dark:hover:text-indigo-300"
        : currentRole === "admin"
            ? "hover:bg-rose-50 dark:hover:bg-rose-950/40 hover:text-rose-700 dark:hover:text-rose-300"
            : "hover:bg-blue-50 dark:hover:bg-blue-950/40 hover:text-blue-700 dark:hover:text-blue-300";

    return (
        <div className={cn("pb-12 h-screen flex flex-col justify-between bg-white dark:bg-slate-950 border-r border-slate-100 dark:border-slate-800", className)}>
            <div className="space-y-4 py-4">
                <div className="px-4 py-2">
                    {/* Premium Brand Header */}
                    <div className="flex items-center gap-3 px-2 mb-8">
                        <div className={cn(
                            "p-2 rounded-xl shadow-md",
                            currentRole === "faculty" ? "bg-gradient-to-br from-indigo-500 to-violet-600"
                                : currentRole === "admin" ? "bg-gradient-to-br from-rose-500 to-pink-600"
                                    : "bg-gradient-to-br from-blue-500 to-cyan-600"
                        )}>
                            <GraduationCap className="h-5 w-5 text-white" />
                        </div>
                        <div>
                            <h2 className="text-lg font-black tracking-tight text-slate-800 dark:text-white">ALSA</h2>
                            <p className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">
                                {currentRole === "faculty" ? "Faculty Portal"
                                    : currentRole === "admin" ? "Admin Control"
                                        : "Student Portal"}
                            </p>
                        </div>
                    </div>

                    <div className="space-y-1">
                        {routes.map((route: any) => {
                            const isActive = pathname === route.href;
                            if (route.isHeader) {
                                return (
                                    <div key={route.title} className="px-3 py-2 mt-4 mb-1 text-[10px] font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-[0.15em] flex items-center gap-2">
                                        <div className="h-px flex-1 bg-slate-100 dark:bg-slate-800" />
                                        {route.title}
                                        <div className="h-px flex-1 bg-slate-100 dark:bg-slate-800" />
                                    </div>
                                );
                            }
                            return (
                                <Link
                                    key={route.href}
                                    href={route.href}
                                    className={cn(
                                        "group flex items-center justify-between w-full px-3 py-2.5 rounded-xl text-sm font-bold transition-all duration-200",
                                        isActive
                                            ? accentActive
                                            : cn("text-slate-600 dark:text-slate-300", accentHover)
                                    )}
                                >
                                    <div className="flex items-center gap-2.5">
                                        <route.icon className={cn(
                                            "h-4 w-4 transition-transform duration-200 group-hover:scale-110",
                                            isActive ? "text-white" : ""
                                        )} />
                                        <span>{route.title}</span>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        {route.badge !== undefined && (
                                            <span className="bg-red-500 text-white text-[10px] font-black px-1.5 py-0.5 rounded-full animate-pulse">
                                                {route.badge}
                                            </span>
                                        )}
                                        {isActive && (
                                            <div className="h-1.5 w-1.5 rounded-full bg-white/70" />
                                        )}
                                    </div>
                                </Link>
                            );
                        })}
                    </div>
                </div>
            </div>

            <div className="mt-auto">
                {currentRole === "admin" && (
                    <div className="px-4 py-3 mb-2 mx-4 rounded-xl border border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900 shadow-sm flex items-center justify-between">
                        <span className="text-[10px] font-extrabold uppercase tracking-widest text-slate-400 dark:text-slate-500">System Health</span>
                        <div className="flex items-center gap-1.5">
                            <div className={cn(
                                "w-2 h-2 rounded-full animate-pulse",
                                healthStatus === "Healthy" ? "bg-emerald-500" :
                                    healthStatus === "Warning" ? "bg-amber-500" : "bg-red-500"
                            )} />
                            <span className={cn(
                                "text-xs font-black",
                                healthStatus === "Healthy" ? "text-emerald-600" :
                                    healthStatus === "Warning" ? "text-amber-600" : "text-red-600"
                            )}>{healthStatus}</span>
                        </div>
                    </div>
                )}
                <div className="p-4 border-t border-slate-100 dark:border-slate-700/60">
                    <button
                        onClick={logout}
                        className="group w-full flex items-center gap-2.5 px-3 py-2.5 rounded-xl text-sm font-bold text-rose-500 hover:bg-rose-50 hover:text-rose-700 dark:text-rose-400 transition-all duration-200"
                    >
                        <LogOut className="h-4 w-4 transition-transform duration-200 group-hover:scale-110" />
                        Logout
                    </button>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { useAuth } from "@/context/auth-context";
import { User, Mail, Shield, GraduationCap, Building2, Pencil, Save, X, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { IT_DEPARTMENTS, CORE_DEPARTMENTS } from "@/lib/department-core";

const ALL_DEPARTMENTS = [...IT_DEPARTMENTS, ...CORE_DEPARTMENTS].sort();

export function ProfileDialog({ open, onOpenChange }: { open: boolean; onOpenChange: (open: boolean) => void }) {
    const { user, updateUserProfile } = useAuth();
    const [editing, setEditing] = useState(false);
    const [saving, setSaving] = useState(false);

    // Editable fields
    const [name, setName] = useState("");
    const [gender, setGender] = useState<"MALE" | "FEMALE" | "OTHER">("OTHER");
    const [department, setDepartment] = useState("");
    const [designation, setDesignation] = useState("");
    const [cgpa, setCgpa] = useState("");
    const [attendance, setAttendance] = useState("");

    // Sync local state when dialog opens or user changes
    useEffect(() => {
        if (user) {
            setName(user.name || "");
            setGender((user.gender as any) || "OTHER");
            setDepartment(user.department || "");
            setDesignation(user.designation || "");
            setCgpa(user.cgpa != null ? String(user.cgpa) : "");
            setAttendance(user.attendance != null ? String(user.attendance) : "");
        }
    }, [user, open]);

    if (!user) return null;

    const getAvatar = () => {
        if (user.gender === "MALE") return "https://avatar.iran.liara.run/public/boy";
        if (user.gender === "FEMALE") return "https://avatar.iran.liara.run/public/girl";
        return "";
    };

    const handleCancel = () => {
        // Reset to original values
        setName(user.name || "");
        setGender((user.gender as any) || "OTHER");
        setDepartment(user.department || "");
        setDesignation(user.designation || "");
        setCgpa(user.cgpa != null ? String(user.cgpa) : "");
        setAttendance(user.attendance != null ? String(user.attendance) : "");
        setEditing(false);
    };

    const handleSave = () => {
        if (!name.trim()) {
            toast.error("Name cannot be empty");
            return;
        }

        setSaving(true);
        try {
            const updates: Record<string, any> = {
                name: name.trim(),
                gender,
            };

            if (user.role === "student") {
                if (cgpa) updates.cgpa = parseFloat(cgpa);
                if (attendance) updates.attendance = parseFloat(attendance);
            } else {
                if (designation) updates.designation = designation;
            }

            if (department) updates.department = department;

            updateUserProfile(updates);
            toast.success("Profile updated successfully!");
            setEditing(false);
        } catch (error: any) {
            toast.error("Failed to update: " + error.message);
        } finally {
            setSaving(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={(v) => { if (!v) setEditing(false); onOpenChange(v); }}>
            <DialogContent className="sm:max-w-[480px] bg-white/95 dark:bg-slate-950/95 backdrop-blur-xl border border-slate-200/60 dark:border-indigo-500/20 shadow-2xl overflow-hidden p-0">
                <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/5 via-transparent to-purple-500/5 pointer-events-none" />
                <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-purple-500" />

                <div className="relative z-10 p-6 space-y-4 max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                        <div className="flex items-center justify-between">
                            <div>
                                <DialogTitle className="text-slate-900 dark:text-white font-bold">User Profile</DialogTitle>
                                <DialogDescription className="text-slate-500 dark:text-slate-400">
                                    {editing ? "Edit your profile information below." : "View and manage your profile details."}
                                </DialogDescription>
                            </div>
                            {!editing && (
                                <Button variant="outline" size="sm" onClick={() => setEditing(true)} className="gap-1.5">
                                    <Pencil className="h-3.5 w-3.5" />
                                    Edit
                                </Button>
                            )}
                        </div>
                    </DialogHeader>

                    <div className="grid gap-4 py-4">
                        {/* Avatar & Name Header */}
                        <div className="flex flex-col items-center gap-4 mb-2 relative">
                            <div className="relative group">
                                <div className="absolute -inset-1 bg-gradient-to-r from-blue-500 to-purple-600 rounded-full blur opacity-30 group-hover:opacity-60 transition duration-500"></div>
                                <Avatar className="h-24 w-24 border-[3px] border-white dark:border-slate-900 shadow-md relative">
                                    <AvatarImage src={getAvatar()} alt={user.name} />
                                    <AvatarFallback className="bg-slate-100 dark:bg-slate-800 text-2xl font-black text-slate-700 dark:text-slate-300">{user.name.slice(0, 2).toUpperCase()}</AvatarFallback>
                                </Avatar>
                            </div>
                            {!editing && (
                                <div className="text-center space-y-1.5">
                                    <h3 className="text-2xl font-black tracking-tight text-slate-900 dark:text-white">{user.name}</h3>
                                    <Badge variant="secondary" className="bg-indigo-50 dark:bg-indigo-500/10 text-indigo-700 dark:text-indigo-300 border border-indigo-200 dark:border-indigo-500/20 px-3 py-0.5 shadow-sm">
                                        <span className="uppercase font-extrabold tracking-widest text-[10px]">{user.role}</span>
                                    </Badge>
                                </div>
                            )}
                        </div>

                        {/* Fields */}
                        <div className="space-y-4 bg-slate-50/50 dark:bg-slate-900/20 p-4 rounded-xl border border-slate-100 dark:border-slate-800/50 relative">
                            <div className="absolute -left-px top-4 bottom-4 w-0.5 bg-gradient-to-b from-blue-500/50 to-purple-500/50 rounded-r-full" />
                            {/* Name */}
                            <div className="grid grid-cols-4 items-center gap-4">
                                <Label htmlFor="profile-name" className="text-right text-slate-500 dark:text-slate-400">
                                    <User className="h-4 w-4 ml-auto" />
                                </Label>
                                {editing ? (
                                    <Input
                                        id="profile-name"
                                        value={name}
                                        onChange={(e) => setName(e.target.value)}
                                        className="col-span-3 bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800 focus-visible:ring-indigo-500 font-medium"
                                        placeholder="Your full name"
                                    />
                                ) : (
                                    <Input id="profile-name" value={user.name} className="col-span-3 bg-white/50 dark:bg-slate-900/40 border-slate-200/60 dark:border-slate-800/60 text-slate-800 dark:text-slate-200 shadow-sm font-semibold tracking-tight" readOnly />
                                )}
                            </div>

                            {/* Email (always read-only) */}
                            <div className="grid grid-cols-4 items-center gap-4">
                                <Label htmlFor="profile-email" className="text-right text-slate-500 dark:text-slate-400">
                                    <Mail className="h-4 w-4 ml-auto" />
                                </Label>
                                <Input id="profile-email" value={user.email} className="col-span-3 bg-slate-100/50 dark:bg-slate-900/60 border-slate-200/50 dark:border-slate-800/40 text-slate-500 dark:text-slate-400 shadow-inner text-sm font-medium" readOnly />
                            </div>

                            {/* Gender */}
                            <div className="grid grid-cols-4 items-center gap-4">
                                <Label className="text-right text-slate-500 dark:text-slate-400 text-[10px] font-bold uppercase tracking-wider">Gender</Label>
                                {editing ? (
                                    <div className="col-span-3">
                                        <Select value={gender} onValueChange={(v) => setGender(v as any)}>
                                            <SelectTrigger className="bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800 focus:ring-indigo-500 font-medium">
                                                <SelectValue />
                                            </SelectTrigger>
                                            <SelectContent>
                                                <SelectItem value="MALE">Male</SelectItem>
                                                <SelectItem value="FEMALE">Female</SelectItem>
                                                <SelectItem value="OTHER">Other</SelectItem>
                                            </SelectContent>
                                        </Select>
                                    </div>
                                ) : (
                                    <Input value={user.gender || "Not set"} className="col-span-3 bg-white/50 dark:bg-slate-900/40 border-slate-200/60 dark:border-slate-800/60 text-slate-800 dark:text-slate-200 shadow-sm font-medium" readOnly />
                                )}
                            </div>

                            {/* Department */}
                            <div className="grid grid-cols-4 items-center gap-4">
                                <Label className="text-right text-slate-500 dark:text-slate-400">
                                    <Building2 className="h-4 w-4 ml-auto" />
                                </Label>
                                {editing ? (
                                    <div className="col-span-3">
                                        <Select value={department} onValueChange={setDepartment}>
                                            <SelectTrigger className="bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800 focus:ring-indigo-500 text-sm font-medium">
                                                <SelectValue placeholder="Select Department" />
                                            </SelectTrigger>
                                            <SelectContent>
                                                {ALL_DEPARTMENTS.map((dept) => (
                                                    <SelectItem key={dept} value={dept}>
                                                        {dept}
                                                    </SelectItem>
                                                ))}
                                            </SelectContent>
                                        </Select>
                                    </div>
                                ) : (
                                    <div className="col-span-3">
                                        <Input value={user.department || "Not set"} className="w-full bg-white/50 dark:bg-slate-900/40 border-slate-200/60 dark:border-slate-800/60 text-slate-800 dark:text-slate-200 shadow-sm font-medium overflow-hidden text-ellipsis" readOnly />
                                    </div>
                                )}
                            </div>

                            {/* Role-specific fields */}
                            {user.role === "student" ? (
                                <>
                                    {/* CGPA */}
                                    <div className="grid grid-cols-4 items-center gap-4">
                                        <Label className="text-right text-slate-500 dark:text-slate-400 text-[10px] font-bold uppercase tracking-wider">CGPA</Label>
                                        {editing ? (
                                            <Input
                                                type="number"
                                                step="0.1"
                                                min="0"
                                                max="10"
                                                value={cgpa}
                                                onChange={(e) => setCgpa(e.target.value)}
                                                className="col-span-3 bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800 focus-visible:ring-indigo-500 font-medium font-mono"
                                                placeholder="e.g. 8.5"
                                            />
                                        ) : (
                                            <Input value={user.cgpa != null ? String(user.cgpa) : "--"} className="col-span-3 bg-white/50 dark:bg-slate-900/40 border-slate-200/60 dark:border-slate-800/60 text-slate-800 dark:text-slate-200 shadow-sm font-semibold font-mono" readOnly />
                                        )}
                                    </div>

                                    {/* Attendance */}
                                    <div className="grid grid-cols-4 items-center gap-4">
                                        <Label className="text-right text-slate-500 dark:text-slate-400 text-[10px] font-bold uppercase tracking-wider">Attend.</Label>
                                        {editing ? (
                                            <Input
                                                type="number"
                                                min="0"
                                                max="100"
                                                value={attendance}
                                                onChange={(e) => setAttendance(e.target.value)}
                                                className="col-span-3 bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800 focus-visible:ring-indigo-500 font-medium font-mono"
                                                placeholder="e.g. 85"
                                            />
                                        ) : (
                                            <Input value={user.attendance != null ? `${user.attendance}%` : "--"} className="col-span-3 bg-white/50 dark:bg-slate-900/40 border-slate-200/60 dark:border-slate-800/60 text-slate-800 dark:text-slate-200 shadow-sm font-semibold font-mono" readOnly />
                                        )}
                                    </div>
                                </>
                            ) : user.role === "faculty" ? (
                                <>

                                    {/* Designation */}
                                    <div className="grid grid-cols-4 items-center gap-4">
                                        <Label className="text-right text-slate-500 dark:text-slate-400">
                                            <GraduationCap className="h-4 w-4 ml-auto" />
                                        </Label>
                                        {editing ? (
                                            <div className="col-span-3">
                                                <Select value={designation} onValueChange={setDesignation}>
                                                    <SelectTrigger className="bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800 focus:ring-indigo-500 font-medium text-sm">
                                                        <SelectValue placeholder="Select Designation" />
                                                    </SelectTrigger>
                                                    <SelectContent>
                                                        <SelectItem value="prof">Professor</SelectItem>
                                                        <SelectItem value="assoc">Associate Professor</SelectItem>
                                                        <SelectItem value="asst">Assistant Professor</SelectItem>
                                                        <SelectItem value="lect">Lecturer</SelectItem>
                                                    </SelectContent>
                                                </Select>
                                            </div>
                                        ) : (
                                            <Input value={user.designation || "Not set"} className="col-span-3 bg-white/50 dark:bg-slate-900/40 border-slate-200/60 dark:border-slate-800/60 text-slate-800 dark:text-slate-200 shadow-sm font-medium" readOnly />
                                        )}
                                    </div>
                                </>
                            ) : null}

                            {/* ID (always read-only) */}
                            <div className="grid grid-cols-4 items-center gap-4 mt-2 pt-4 border-t border-slate-200/50 dark:border-slate-800/50">
                                <Label htmlFor="profile-id" className="text-right text-slate-500 dark:text-slate-400">
                                    <Shield className="h-4 w-4 ml-auto" />
                                </Label>
                                <div className="col-span-3">
                                    <Badge variant="outline" className="font-mono text-[9px] bg-slate-100/30 dark:bg-slate-900/30 border-slate-200 dark:border-slate-800/80 text-slate-500 dark:text-slate-400 tracking-wider w-full justify-center py-1">
                                        {user.id}
                                    </Badge>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Footer with Save/Cancel when editing */}
                    {editing && (
                        <DialogFooter className="gap-2 sm:gap-0 pt-2 pb-2">
                            <Button variant="outline" onClick={handleCancel} disabled={saving} className="bg-white/50 border-slate-200 dark:bg-slate-900/50 dark:border-slate-800 font-semibold shadow-sm hover:bg-slate-100 dark:hover:bg-slate-800">
                                <X className="h-4 w-4 mr-1.5" />
                                Cancel
                            </Button>
                            <Button onClick={handleSave} disabled={saving} className="bg-indigo-600 hover:bg-indigo-700 text-white shadow-md font-semibold">
                                {saving ? (
                                    <><Loader2 className="h-4 w-4 mr-1.5 animate-spin" /> Saving...</>
                                ) : (
                                    <><Save className="h-4 w-4 mr-1.5" /> Save Changes</>
                                )}
                            </Button>
                        </DialogFooter>
                    )}

                    {!editing && (
                        <DialogFooter className="sm:justify-between items-center bg-slate-50 dark:bg-slate-900/50 -mx-6 -mb-6 mt-4 p-4 border-t border-slate-100 dark:border-slate-800/50">
                            <div className="text-[10px] text-slate-400 dark:text-slate-500 font-medium shrink-0 h-8 flex items-center justify-center sm:justify-start uppercase tracking-widest pl-2 w-full text-center">
                                System Access Valid
                            </div>
                        </DialogFooter>
                    )}
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from "@/components/ui/sheet";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
    Mail,
    Phone,
    Calendar,
    Award,
    Trophy,
    Briefcase,
    Activity,
    GraduationCap,
    TrendingUp,
    AlertTriangle,
    CheckCircle2,
    ShieldAlert,
    BookOpen,
    Code,
    Database,
    Target,
    BrainCircuit,
    Loader2
} from "lucide-react";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";
import { calculateReadinessScore, getRiskLevel } from "@/lib/faculty-logic";
import { useEffect, useState } from "react";
import { doc, deleteDoc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";

interface StudentDetailsSheetProps {
    student: any | null;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onDeleteSuccess?: (studentId: string) => void;
}

export function StudentDetailsSheet({ student, open, onOpenChange, onDeleteSuccess }: StudentDetailsSheetProps) {
    if (!student) return null;

    // Aggregate Data for Display
    const legacyCerts = student.certifications || [];
    const aoiEnrichment = student.academicEnrichment || [];
    const legacyEnrichment = student.enrichment || [];
    const aoiApplied = student.appliedKnowledge || [];

    // Merge for portfolio display
    const allCerts = [...legacyCerts, ...aoiEnrichment.filter((i: any) => i.type === "Certification").map((i: any) => ({
        name: i.title || i.name,
        issuer: i.organization || i.issuer,
        date: i.date,
        verified: true
    }))];

    const allEnrichment = [...legacyEnrichment, ...aoiApplied, ...aoiEnrichment.filter((i: any) => i.type !== "Certification")];

    const readinessScore = calculateReadinessScore(student);
    const riskLevel = getRiskLevel(readinessScore);

    const [drawbacks, setDrawbacks] = useState<any[]>([]);
    const [roadmap, setRoadmap] = useState<any[]>([]);
    const [isAiLoading, setIsAiLoading] = useState(false);

    useEffect(() => {
        const fetchAiRecommendations = async () => {
            if (!student || !open) return;

            setIsAiLoading(true);
            try {
                const res = await fetch('/api/ai-recommendations', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ student })
                });

                if (res.ok) {
                    const data = await res.json();
                    setDrawbacks(data.drawbacks || []);
                    setRoadmap(data.roadmap || []);
                }
            } catch (error) {
                console.error("Failed to fetch AI recommendations", error);
            } finally {
                setIsAiLoading(false);
            }
        };

        fetchAiRecommendations();
    }, [student, open]);

    const getRiskColor = (risk: string) => {
        switch (risk.toLowerCase()) {
            case "low": return "text-green-600 bg-green-100 dark:bg-green-900/50 border-green-200";
            case "moderate": return "text-yellow-600 bg-yellow-100 border-yellow-200";
            case "high": return "text-red-600 bg-red-100 dark:bg-red-900/50 border-red-200";
            default: return "text-gray-600 bg-gray-100";
        }
    };

    const handleStudentDelete = async () => {
        if (!student?.id) return;
        const confirmDelete = window.confirm(`CRITICAL WARNING: Are you sure you want to permanently delete student ${student.name}? This action cannot be undone.`);
        if (!confirmDelete) return;

        try {
            await deleteDoc(doc(db, "users", student.id));
            toast.success(`Successfully deleted student: ${student.name}`);
            onOpenChange(false);
            if (onDeleteSuccess) onDeleteSuccess(student.id);
        } catch (error) {
            console.error("Error deleting student:", error);
            toast.error("Failed to delete student. Check console or permissions.");
        }
    };

    return (
        <Sheet open={open} onOpenChange={onOpenChange}>
            <SheetContent className="sm:max-w-3xl w-full flex flex-col h-full p-0 gap-0 overflow-hidden bg-white dark:bg-slate-900 dark:bg-slate-950">
                <SheetHeader className="sr-only">
                    <SheetTitle>Student Profile Details</SheetTitle>
                    <SheetDescription>Detailed view of the student&apos;s academic, portfolio, and placement metrics.</SheetDescription>
                </SheetHeader>
                {/* Header Section - Modernized & Compact */}
                <div className="bg-white dark:bg-slate-900 relative z-10 border-b border-slate-200 dark:border-slate-700 shadow-sm">
                    {/* Top Decorative Bar */}
                    <div className="h-2 w-full bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500" />

                    <div className="p-5">
                        <div className="flex justify-between items-start">
                            <div className="flex items-center gap-4">
                                <Avatar className="h-16 w-16 border-2 border-slate-100 dark:border-slate-700/60 shadow-sm">
                                    <AvatarImage src={`https://avatar.iran.liara.run/public/${student.gender === 'FEMALE' ? 'girl' : 'boy'}`} />
                                    <AvatarFallback>{student.name?.substring(0, 2).toUpperCase()}</AvatarFallback>
                                </Avatar>

                                <div>
                                    <h2 className="text-xl font-black text-slate-800 dark:text-white tracking-tight flex items-center gap-2">
                                        {student.name}
                                        <Badge className={`${getRiskColor(riskLevel)} bg-opacity-10 border shadow-none px-2 py-0.5 text-[10px] uppercase font-bold tracking-wider rounded-md`}>
                                            {riskLevel} Risk
                                        </Badge>
                                    </h2>
                                    <div className="flex items-center gap-2 mt-1">
                                        <Badge variant="secondary" className="font-mono text-[10px] bg-slate-100 dark:bg-slate-900/50 dark:bg-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600">{student.registerNumber || student.registerNo || "N/A"}</Badge>
                                        <span className="text-xs font-medium text-slate-500 dark:text-slate-400 flex items-center gap-1">
                                            <Briefcase className="h-3 w-3" /> {student.department}
                                        </span>
                                    </div>
                                    <div className="flex items-center gap-4 text-[11px] font-medium text-slate-500 dark:text-slate-400 mt-2">
                                        <span className="flex items-center gap-1"><Mail className="h-3 w-3" /> {student.email || "No email"}</span>
                                        <span className="flex items-center gap-1"><Phone className="h-3 w-3" /> {student.phone || "No phone"}</span>
                                        <span className="flex items-center gap-1"><GraduationCap className="h-3 w-3" /> Batch 2022-2026</span>
                                    </div>
                                </div>
                            </div>

                            <Button variant="outline" size="sm" onClick={handleStudentDelete} className="text-red-600 dark:text-red-400 font-bold border-red-200 hover:bg-red-50 hover:border-red-300 transition-colors shadow-sm hidden md:flex">
                                <ShieldAlert className="h-4 w-4 mr-2" />
                                Remove Student
                            </Button>
                        </div>
                    </div>
                </div>

                {/* Modern Pill Tabs Section */}
                <Tabs defaultValue="overview" className="flex-1 flex flex-col overflow-hidden bg-slate-50 dark:bg-slate-800/50/50 dark:bg-slate-950">
                    <div className="px-5 py-3 border-b border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 shadow-sm z-0">
                        <TabsList className="bg-slate-100 dark:bg-slate-900/50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-1 h-auto w-full md:w-fit rounded-full flex gap-1 mx-auto overflow-x-auto">
                            <TabsTrigger value="overview" className="rounded-full px-5 py-2 text-xs font-bold data-[state=active]:bg-white dark:bg-slate-900 dark:data-[state=active]:bg-slate-700 data-[state=active]:text-indigo-700 dark:text-indigo-400 dark:data-[state=active]:text-indigo-300 data-[state=active]:shadow-sm transition-all duration-300">Overview</TabsTrigger>
                            <TabsTrigger value="academic" className="rounded-full px-5 py-2 text-xs font-bold data-[state=active]:bg-white dark:bg-slate-900 dark:data-[state=active]:bg-slate-700 data-[state=active]:text-indigo-700 dark:text-indigo-400 dark:data-[state=active]:text-indigo-300 data-[state=active]:shadow-sm transition-all duration-300">Academic</TabsTrigger>
                            <TabsTrigger value="placement" className="rounded-full px-5 py-2 text-xs font-bold data-[state=active]:bg-white dark:bg-slate-900 dark:data-[state=active]:bg-slate-700 data-[state=active]:text-indigo-700 dark:text-indigo-400 dark:data-[state=active]:text-indigo-300 data-[state=active]:shadow-sm transition-all duration-300">Placement</TabsTrigger>
                            <TabsTrigger value="portfolio" className="rounded-full px-5 py-2 text-xs font-bold data-[state=active]:bg-white dark:bg-slate-900 dark:data-[state=active]:bg-slate-700 data-[state=active]:text-indigo-700 dark:text-indigo-400 dark:data-[state=active]:text-indigo-300 data-[state=active]:shadow-sm transition-all duration-300">Portfolio</TabsTrigger>
                            <TabsTrigger value="analytics" className="rounded-full px-5 py-2 text-xs font-bold data-[state=active]:bg-white dark:bg-slate-900 dark:data-[state=active]:bg-slate-700 data-[state=active]:text-indigo-700 dark:text-indigo-400 dark:data-[state=active]:text-indigo-300 data-[state=active]:shadow-sm transition-all duration-300">Risk Roadmaps</TabsTrigger>
                        </TabsList>
                    </div>

                    <div className="flex-1 overflow-y-auto">
                        <div className="p-6">
                            {/* OVERVIEW TAB */}
                            <TabsContent value="overview" className="mt-0 space-y-6">
                                {/* Key Metrics Grid */}
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                    <Card className="bg-gradient-to-br from-indigo-500 to-indigo-700 border-none shadow-md overflow-hidden relative group">
                                        <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity" />
                                        <CardContent className="p-5 flex items-center justify-between relative z-10">
                                            <div>
                                                <p className="text-xs font-bold text-indigo-100 uppercase tracking-widest mb-1">Readiness PRI</p>
                                                <div className="flex items-baseline gap-1">
                                                    <div className="text-4xl font-black text-white">{readinessScore}</div>
                                                    <span className="text-indigo-200 font-bold text-sm">/100</span>
                                                </div>
                                            </div>
                                            <div className="p-3 bg-white/20 rounded-xl">
                                                <TrendingUp className="h-6 w-6 text-white" />
                                            </div>
                                        </CardContent>
                                    </Card>

                                    <Card className="bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-md transition-shadow">
                                        <CardContent className="p-5 flex items-center justify-between">
                                            <div>
                                                <p className="text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-widest mb-1">Certs Verified</p>
                                                <div className="text-4xl font-black text-slate-800 dark:text-white">{allCerts.length}</div>
                                            </div>
                                            <div className="p-3 bg-emerald-50 dark:bg-emerald-900/40 rounded-xl">
                                                <Award className="h-6 w-6 text-emerald-600 dark:text-emerald-400" />
                                            </div>
                                        </CardContent>
                                    </Card>

                                    <Card className="bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-md transition-shadow">
                                        <CardContent className="p-5 flex items-center justify-between">
                                            <div>
                                                <p className="text-xs font-bold text-purple-600 dark:text-purple-400 uppercase tracking-widest mb-1">Enrichment</p>
                                                <div className="text-4xl font-black text-slate-800 dark:text-white">{allEnrichment.length}</div>
                                            </div>
                                            <div className="p-3 bg-purple-50 dark:bg-purple-900/40 rounded-xl">
                                                <Activity className="h-6 w-6 text-purple-600 dark:text-purple-400" />
                                            </div>
                                        </CardContent>
                                    </Card>
                                </div>

                                {/* Summary Analysis */}
                                <Card className="border-slate-200 dark:border-slate-700 shadow-sm overflow-hidden bg-white dark:bg-slate-900">
                                    <CardHeader className="pb-3 border-b border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50/50 dark:bg-slate-800/60">
                                        <CardTitle className="text-sm font-bold flex items-center gap-2 text-slate-800 dark:text-white">
                                            <ShieldAlert className="h-4 w-4 text-indigo-600 dark:text-indigo-400" /> Faculty Insights & Intelligence
                                        </CardTitle>
                                    </CardHeader>
                                    <CardContent className="p-5 bg-white dark:bg-slate-900">
                                        <div className="space-y-4">
                                            {isAiLoading ? (
                                                <div className="flex flex-col items-center justify-center py-10 text-slate-500">
                                                    <Loader2 className="h-6 w-6 animate-spin mb-2" />
                                                    <p className="text-sm font-medium">Generating Faculty Insights...</p>
                                                </div>
                                            ) : drawbacks.length > 0 ? (
                                                <div className="grid gap-3">
                                                    {drawbacks.map((item, idx) => (
                                                        <div key={idx} className="p-4 rounded-xl border bg-amber-50/60 dark:bg-amber-950/30 border-amber-100 dark:border-amber-900/50 shadow-sm transition-transform hover:-translate-y-0.5 flex flex-col gap-2 relative overflow-hidden">
                                                            <div className="absolute top-0 left-0 w-1 h-full bg-amber-400 dark:bg-amber-600 rounded-l-xl opacity-50" />

                                                            {/* Fault / Weakness */}
                                                            <div className="flex gap-2.5 text-slate-800 dark:text-white pb-2 border-b border-amber-200/50 dark:border-amber-800/50">
                                                                <AlertTriangle className="h-4 w-4 flex-shrink-0 text-rose-500 mt-0.5" />
                                                                <div>
                                                                    <span className="font-black text-[10px] uppercase tracking-wider text-rose-600 dark:text-rose-400">Fault / Weakness</span>
                                                                    <p className="font-bold text-sm mt-0.5">{item.drawback}</p>
                                                                </div>
                                                            </div>

                                                            {/* Correction / Fix */}
                                                            <div className="flex gap-2.5 text-slate-800 dark:text-white pt-1">
                                                                <div className="h-4 w-4 shrink-0 rounded-full bg-emerald-100 dark:bg-emerald-900/50 text-emerald-600 dark:text-emerald-400 flex items-center justify-center mt-0.5"><CheckCircle2 className="h-3 w-3" /></div>
                                                                <div>
                                                                    <span className="font-black text-[10px] uppercase tracking-wider text-emerald-600 dark:text-emerald-400">Correction / Idea to Improve</span>
                                                                    <p className="text-xs text-slate-600 dark:text-slate-300 font-medium leading-relaxed mt-0.5">{item.suggestion}</p>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    ))}
                                                </div>
                                            ) : (
                                                <div className="flex flex-col items-center justify-center py-10 text-center bg-emerald-50/30 dark:bg-emerald-950/20 rounded-xl border border-emerald-100 dark:border-emerald-900/50 border-dashed">
                                                    <div className="bg-emerald-100 dark:bg-emerald-900/50 p-3 rounded-full mb-3">
                                                        <CheckCircle2 className="h-8 w-8 text-emerald-600 dark:text-emerald-400" />
                                                    </div>
                                                    <p className="font-bold text-emerald-900 dark:text-emerald-300 text-lg">Elite Profile Performance</p>
                                                    <p className="text-sm text-emerald-700 dark:text-emerald-400 mt-1 max-w-sm">This student is currently exceeding all Readiness benchmarks according to our AI analytics models.</p>
                                                </div>
                                            )}
                                        </div>
                                    </CardContent>
                                </Card>
                            </TabsContent>

                            {/* ACADEMIC TAB */}
                            <TabsContent value="academic" className="mt-0 space-y-6">
                                <div className="grid grid-cols-2 gap-4">
                                    <Card className="border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 shadow-sm hover:shadow-md transition-shadow">
                                        <CardContent className="p-6 flex flex-col items-center justify-center text-center">
                                            <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-2">Aggregate CGPA</p>
                                            <div className="text-5xl font-black text-indigo-700 dark:text-indigo-400 dark:text-indigo-300 bg-indigo-50/50 dark:bg-indigo-950/40 w-full py-4 rounded-xl border border-indigo-100 dark:border-indigo-900/50">{student.cgpa || "N/A"}</div>
                                        </CardContent>
                                    </Card>
                                    <Card className={student.standingArrears > 0 ? "bg-rose-50 dark:bg-rose-950/40 border-rose-200 dark:border-rose-900/50 shadow-sm" : "bg-emerald-50 dark:bg-emerald-950/40 border-emerald-200 dark:border-emerald-900/50 shadow-sm"}>
                                        <CardContent className="p-6 flex flex-col items-center justify-center text-center">
                                            <p className={`text-xs font-bold uppercase tracking-widest mb-2 ${student.standingArrears > 0 ? "text-rose-600 dark:text-rose-400" : "text-emerald-700 dark:text-emerald-400"}`}>Standing Arrears</p>
                                            <div className={`text-5xl font-black w-full py-4 rounded-xl border ${student.standingArrears > 0 ? "text-rose-600 dark:text-rose-400 bg-rose-100/60 dark:bg-rose-900/30 border-rose-200 dark:border-rose-800" : "text-emerald-600 dark:text-emerald-400 bg-emerald-100/60 dark:bg-emerald-900/30 border-emerald-200 dark:border-emerald-800"}`}>
                                                {student.standingArrears || 0}
                                            </div>
                                        </CardContent>
                                    </Card>
                                </div>

                                <Card className="border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 shadow-sm">
                                    <CardHeader className="pb-3 border-b border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/60">
                                        <CardTitle className="text-sm font-bold flex items-center gap-2 text-slate-800 dark:text-white">
                                            <BookOpen className="h-4 w-4 text-indigo-600 dark:text-indigo-400" /> Semester-wise Academic Records
                                        </CardTitle>
                                    </CardHeader>
                                    <CardContent className="p-4">
                                        <div className="space-y-3">
                                            {student.academicRecords && student.academicRecords.length > 0 ? (
                                                student.academicRecords
                                                    .slice()
                                                    .sort((a: any, b: any) => a.semester - b.semester)
                                                    .map((record: any, idx: number) => {
                                                        const sgpa = record.sgpa ?? record.gpa ?? null;
                                                        const hasArrear = (record.arrears ?? 0) > 0;
                                                        const sgpaColor =
                                                            sgpa === null ? "text-slate-400 dark:text-slate-500" :
                                                                sgpa >= 9 ? "text-emerald-600 dark:text-emerald-400" :
                                                                    sgpa >= 7.5 ? "text-indigo-600 dark:text-indigo-400" :
                                                                        sgpa >= 6 ? "text-amber-500 dark:text-amber-400" :
                                                                            "text-rose-500 dark:text-rose-400";
                                                        const sgpaBg =
                                                            sgpa === null ? "bg-slate-50 dark:bg-slate-800/50 border-slate-100 dark:border-slate-700/60" :
                                                                sgpa >= 9 ? "bg-emerald-50 dark:bg-emerald-950/40 border-emerald-100 dark:border-emerald-900/50" :
                                                                    sgpa >= 7.5 ? "bg-indigo-50 dark:bg-indigo-950/40 border-indigo-100 dark:border-indigo-900/50" :
                                                                        sgpa >= 6 ? "bg-amber-50 dark:bg-amber-950/40 border-amber-100 dark:border-amber-900/50" :
                                                                            "bg-rose-50 dark:bg-rose-950/40 border-rose-100 dark:border-rose-900/50";
                                                        return (
                                                            <div key={idx} className={`flex items-center justify-between px-4 py-3 rounded-xl border ${sgpaBg} transition-all hover:shadow-sm`}>
                                                                <div>
                                                                    <p className="font-black text-sm text-slate-800 dark:text-white tracking-tight">Semester {record.semester}</p>
                                                                    <div className="flex items-center gap-2 mt-0.5">
                                                                        {hasArrear ? (
                                                                            <span className="text-[10px] font-bold text-rose-600 dark:text-rose-400 bg-rose-100 dark:bg-rose-900/50 px-1.5 py-0.5 rounded-md border border-rose-200 dark:border-rose-800">
                                                                                {record.arrears} Arrear{record.arrears > 1 ? "s" : ""}
                                                                            </span>
                                                                        ) : (
                                                                            <span className="text-[10px] font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-100 dark:bg-emerald-900/50 px-1.5 py-0.5 rounded-md border border-emerald-200 dark:border-emerald-800">
                                                                                Clear
                                                                            </span>
                                                                        )}
                                                                    </div>
                                                                </div>
                                                                <div className="flex flex-col items-end gap-1">
                                                                    <span className={`text-2xl font-black ${sgpaColor}`}>
                                                                        {sgpa !== null ? Number(sgpa).toFixed(2) : "ΓÇö"}
                                                                    </span>
                                                                    <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 dark:text-slate-400 uppercase tracking-wider">SGPA</span>
                                                                </div>
                                                            </div>
                                                        );
                                                    })
                                            ) : (
                                                <div className="text-center py-6">
                                                    <p className="text-sm text-muted-foreground italic">No semester records available.</p>
                                                </div>
                                            )}
                                        </div>
                                    </CardContent>
                                </Card>
                            </TabsContent>

                            {/* PLACEMENT TAB */}
                            <TabsContent value="placement" className="mt-0 space-y-6">
                                <Card className="border-slate-200 dark:border-slate-700 shadow-sm overflow-hidden bg-white dark:bg-slate-900">
                                    <CardHeader className="pb-3 border-b border-slate-200 dark:border-slate-700 bg-blue-50/60 dark:bg-blue-950/20">
                                        <CardTitle className="text-sm font-bold flex items-center gap-2 text-slate-800 dark:text-white">
                                            <Briefcase className="h-4 w-4 text-blue-600 dark:text-blue-400" /> Core Assessment Scores
                                        </CardTitle>
                                    </CardHeader>
                                    <CardContent className="p-6 bg-white dark:bg-slate-900">
                                        <div className="space-y-6">
                                            <div className="space-y-2">
                                                <div className="flex justify-between text-sm font-bold text-slate-800 dark:text-white">
                                                    <span>Aptitude Score</span>
                                                    <span>{student.placementMetrics?.aptitudeScore || 0}%</span>
                                                </div>
                                                <Progress value={student.placementMetrics?.aptitudeScore || 0} className="h-2" />
                                            </div>
                                            <div className="space-y-2">
                                                <div className="flex justify-between text-sm font-bold text-slate-800 dark:text-white">
                                                    <span>Coding Score</span>
                                                    <span>{student.placementMetrics?.codingScore || 0}%</span>
                                                </div>
                                                <Progress value={student.placementMetrics?.codingScore || 0} className="h-2" />
                                            </div>
                                            <div className="space-y-2">
                                                <div className="flex justify-between text-sm font-bold text-slate-800 dark:text-white">
                                                    <span>Communication Score</span>
                                                    <span>{student.placementMetrics?.communicationScore || 0}%</span>
                                                </div>
                                                <Progress value={student.placementMetrics?.communicationScore || 0} className="h-2" />
                                            </div>
                                            {student.placementMetrics?.mockInterviewScore !== undefined && (
                                                <div className="space-y-2">
                                                    <div className="flex justify-between text-sm font-bold text-muted-foreground">
                                                        <span>Mock Interview Score</span>
                                                        <span>{student.placementMetrics.mockInterviewScore}%</span>
                                                    </div>
                                                    <Progress value={student.placementMetrics.mockInterviewScore} className="h-2 opacity-50" />
                                                </div>
                                            )}
                                        </div>
                                    </CardContent>
                                </Card>

                                {student.roleTrackProfile && (
                                    <Card className="border-indigo-200 dark:border-indigo-900/50 bg-white dark:bg-slate-900 shadow-sm mt-4 overflow-hidden">
                                        <CardHeader className="py-4 border-b border-slate-200 dark:border-slate-700 bg-indigo-50/60 dark:bg-indigo-950/20">
                                            <CardTitle className="text-sm font-bold flex items-center gap-2 text-slate-800 dark:text-white">
                                                <Target className="h-4 w-4 text-indigo-600 dark:text-indigo-400" /> Professional Track Alignment
                                            </CardTitle>
                                            <CardDescription className="text-xs">Mapped Career Trajectory</CardDescription>
                                        </CardHeader>
                                        <CardContent className="p-0">
                                            <div className="bg-indigo-600 p-4 text-white flex justify-between items-center">
                                                <span className="text-xs font-bold uppercase tracking-wider text-indigo-200">Selected Track</span>
                                                <span className="font-black text-lg">{student.roleTrackProfile.trackSelected || student.outcomeAlignment?.trackSelected || "Not Selected"}</span>
                                            </div>
