                                                            <h4 className="text-xs font-bold uppercase tracking-wider text-emerald-800 dark:text-emerald-300 dark:text-emerald-400 mb-3 border-b border-emerald-100/50 dark:border-emerald-900/30 pb-2">{domain}</h4>
