"use client";

import React, { createContext, useContext, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { User as AppUser, Role } from "@/types";
import { auth, db } from "@/lib/firebase";
import {
    signInWithPopup,
    GoogleAuthProvider,
    signInWithEmailAndPassword,
    createUserWithEmailAndPassword,
    onAuthStateChanged,
    signOut,
    updateProfile,
    updatePassword,
    reauthenticateWithPopup,
    signInWithRedirect,
    getRedirectResult,
    User as FirebaseUser,
} from "firebase/auth";
import { doc, setDoc, getDoc, serverTimestamp } from "firebase/firestore";
import { toast } from "sonner";
import {
    createUserDocument,
    getUserDocument,
    updateUserDocument,
    getFacultyDocument,
    getUserByEmail,
} from "@/lib/firestore";
import { normalizeDepartment } from "@/lib/department-core";
import { logSystemIssue } from "@/lib/issue-logger";

// ---- Auth Context ----
interface AuthContextType {
    user: AppUser | null;
    isLoading: boolean;
    login: (data: { email: string; password: string }) => Promise<void>;
    signup: (data: any) => Promise<void>;
    googleLogin: (preferredRole?: Role) => Promise<void>;
    logout: () => void;
    updateUserProfile: (updates: Partial<AppUser> & { newPassword?: string }) => void;
    handleRoleRedirection: (appUser: AppUser) => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

/**
 * Build an AppUser object from a Firestore document snapshot.
 */
function firestoreDocToAppUser(docData: Record<string, any>): AppUser {
    return {
        id: docData.id,
        name: docData.name ?? "",
        email: docData.email ?? "",
        role: docData.role?.toLowerCase(), // Explicit - no default
        approved: docData.approved,
        gender: docData.gender ?? "OTHER",
        avatarUrl: docData.avatarUrl,
        department: docData.department,
        designation: docData.designation,
        registerNumber: docData.registerNumber ?? docData.registerNo,
        registerNo: docData.registerNo,
        priScore: docData.priScore,
        cgpa: docData.cgpa,
        riskLevel: docData.riskLevel,
        weakestModule: docData.weakestModule,
        lastUpdated: docData.lastUpdated,
        degree: docData.degree,
        yearOfStudy: docData.yearOfStudy,
        currentSemester: docData.currentSemester,
        totalSemesters: docData.totalSemesters,
        academicRecords: docData.academicRecords,
        certifications: docData.certifications,
        competitions: docData.competitions,
        extraCurricular: docData.extraCurricular,
        placementMetrics: docData.placementMetrics,
        placement: docData.placement,
        arrears: docData.arrears,
        attendance: docData.attendance,
        isProfileComplete: docData.isProfileComplete ?? docData.profileCompleted ?? false,
        areGradesComplete: docData.areGradesComplete ?? docData.gradesCompleted ?? false,

        // New Academic Modules
        academicEnrichment: docData.academicEnrichment,
        appliedKnowledge: docData.appliedKnowledge,
        academicEngagement: docData.academicEngagement,
        outcomeAlignment: docData.outcomeAlignment,

        // Explicit Profiles
        coreAcademicProfile: docData.coreAcademicProfile,
        roleTrackProfile: docData.roleTrackProfile,
        coreAcademicTopics: docData.coreAcademicTopics,

        // Final Calc
        academicOutcomeIndex: docData.academicOutcomeIndex
    };
}

export function AuthProvider({ children }: { children: React.ReactNode }) {
    const [user, setUser] = useState<AppUser | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const router = useRouter();

    // ΓöÇΓöÇΓöÇ Firebase Auth listener ΓöÇΓöÇΓöÇ
    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, async (firebaseUser: FirebaseUser | null) => {
            if (firebaseUser) {
                try {
                    // Check if we already have a user state from a manual login/signup flow
                    // to prevent double-redirection or race conditions.
                    if (user && user.id === firebaseUser.uid && !window.location.pathname.includes("login")) {
                        setIsLoading(false);
                        return;
                    }

                    let docData = await getUserDocument(firebaseUser.uid);

                    // PRIORITY: If a student record exists in "users" by email, it OVERRIDES everything (UID doc or faculty collection doc).
                    if (firebaseUser.email) {
                        const emailData = await getUserByEmail(firebaseUser.email);
                        if (emailData && (emailData as any).role === "student") {
                            docData = emailData as any;
                            if (emailData.id !== firebaseUser.uid) {
                                await createUserDocument(firebaseUser.uid, { ...emailData, uid: firebaseUser.uid });
                            }
                        }
                    }

                    // FALLBACK: Only check isolated collections if we haven't found a record yet
                    if (!docData) {
                        const studentSnap = await getDoc(doc(db, "students", firebaseUser.uid));
                        if (studentSnap.exists()) {
                            docData = { ...studentSnap.data(), role: "student" } as any;
                        } else {
                            const facultyData = await getFacultyDocument(firebaseUser.uid);
                            if (facultyData && (facultyData as any).role !== "student") {
                                docData = { ...facultyData, role: "faculty" } as any;
                            }
                        }
                    }

                    const providerId = firebaseUser.providerData[0]?.providerId || "password";
                    const hasPwd = firebaseUser.providerData.some(p => p.providerId === "password");

                    if (docData) {
                        const anyData = docData as any;
                        // FORCE ADMIN CHECK (Internal override)
                        if (firebaseUser.email?.toLowerCase() === "heyydean001@gmail.com") {
                            anyData.role = "admin";
                            anyData.approved = true;
                            if (anyData.role !== "admin") {
                                await updateUserDocument(firebaseUser.uid, { role: "admin", approved: true });
                            }
                        }

                        const appUser = {
                            ...firestoreDocToAppUser(docData),
                            loginProvider: providerId,
                            hasPassword: hasPwd
                        };
                        setUser(appUser);

                        // Centralized mandatory flow check
                        handleRoleRedirection(appUser, true);
                    } else {
                        // Truly New User or Skeleton in-transition
                        const storedRole = localStorage.getItem("alsa_preferred_role") as Role;

                        const skeletonUser: AppUser = {
                            id: firebaseUser.uid,
                            uid: firebaseUser.uid,
                            email: firebaseUser.email || "",
                            name: firebaseUser.displayName || "New User",
                            role: (storedRole || null) as any,
                            gender: "OTHER",
                            loginProvider: providerId,
                            hasPassword: hasPwd
                        } as AppUser;
                        setUser(skeletonUser);

                        // Only redirect if we are NOT on a special page (like select-role)
                        const path = window.location.pathname;
                        if (storedRole && !path.includes("select-role") && !path.includes("complete-profile")) {
                            handleRoleRedirection(skeletonUser);
                        }
                    }
                } catch (error) {
                    console.error("Error fetching user data:", error);
                    setUser(null);
                }
            } else {
                setUser(null);
                localStorage.removeItem("alsa_preferred_role");
            }
            setIsLoading(false);
        });

        return () => unsubscribe();
    }, [user?.id]);

    // ΓöÇΓöÇΓöÇ Email / Password Login ΓöÇΓöÇΓöÇ
    const login = async (data: { email: string; password: string }) => {
        const { email, password } = data;

        const credential = await signInWithEmailAndPassword(auth, email, password);
        let docData = await getUserDocument(credential.user.uid);

        if (!docData) {
            const facultyData = await getFacultyDocument(credential.user.uid);
            if (facultyData) {
                docData = { ...facultyData, role: "faculty" } as any;
            }
        }

        if (!docData) {
            throw new Error("Account data not found. Please register first.");
        }

        const hasPwd = credential.user.providerData.some(p => p.providerId === "password");
        const appUser = {
            ...firestoreDocToAppUser(docData),
            loginProvider: credential.user.providerData[0]?.providerId || "password",
            hasPassword: hasPwd
        };
        setUser(appUser);

        if (appUser.email === "heyydean001@gmail.com" && appUser.role !== "admin") {
            await updateUserDocument(appUser.id, { role: "admin", approved: true });
            appUser.role = "admin";
            appUser.approved = true;
        }

        handleRoleRedirection(appUser);
    };

    /**
     * Centralized Redirection Engine
     * @param passive If true, only redirects if the user is NOT already on the correct flow page.
     */
    const handleRoleRedirection = (appUser: AppUser, passive: boolean = false) => {
        const path = window.location.pathname;

        // 1. Handle Students
        if (appUser.role === "student") {
            const isComplete = (appUser.isProfileComplete || appUser.profileCompleted) && !!appUser.currentSemester;

            if (!isComplete) {
                if (!path.startsWith("/complete-profile")) router.push("/complete-profile");
            } else if (!appUser.areGradesComplete) {
                if (!path.startsWith("/dashboard/student/academic-records/setup")) {
                    router.push("/dashboard/student/academic-records/setup");
                }
            } else {
                if (!passive || (path === "/" || path === "/login" || path === "/signup")) {
                    router.push("/dashboard/student");
                }
            }
            return;
        }

        // 2. Handle Admin
        if (appUser.role === "admin") {
            if (!passive || (path === "/" || path === "/login" || path === "/signup")) {
                router.push("/admin/dashboard");
            }
            return;
        }

        // 3. Handle Faculty
        if (appUser.role === "faculty") {
            const isComplete = !!appUser.department && !!appUser.designation;
            if (!isComplete) {
                if (!path.startsWith("/complete-faculty-profile")) router.push("/complete-faculty-profile");
            } else if (!appUser.approved) {
                if (!path.startsWith("/faculty/pending-approval")) router.push("/faculty/pending-approval");
            } else {
                if (!passive || (path === "/" || path === "/login" || path === "/signup")) {
                    router.push("/dashboard/faculty");
                }
            }
            return;
        }

        // 4. Default: No role assigned yet (New User)
        if (!path.includes("select-role")) {
            router.push("/select-role");
        }
    };

    // ΓöÇΓöÇΓöÇ Email / Password Signup ΓöÇΓöÇΓöÇ
    const signup = async (data: any) => {
        const { email, password, name, role, gender, ...academicData } = data;

        const credential = await createUserWithEmailAndPassword(auth, email, password);
        const uid = credential.user.uid;

        // Set display name on Firebase Auth profile
        await updateProfile(credential.user, { displayName: name });

        const isDean = email.toLowerCase() === "heyydean001@gmail.com";
        const finalRole = isDean ? "admin" : role;

        if (!finalRole) {
            throw new Error("User role is required for registration.");
        }

        const finalApproved = isDean ? true : (finalRole === "faculty" ? false : true); // Students auto-approved, faculty pending

        // Create Firestore user document
        const userData: Record<string, any> = {
            name,
            email,
            role: finalRole,
            gender: gender ?? "OTHER",
            approved: finalApproved,
            profileCompleted: finalRole === "faculty",
            gradesCompleted: false,
            isProfileComplete: finalRole === "faculty",
            areGradesComplete: false,
            ...academicData,
        };

        await createUserDocument(uid, userData);

        if (finalRole === "student") {
            await setDoc(doc(db, "students", uid), {
                uid,
                name: name || "",
                email: email || "",
                department: academicData.department || "",
                cgpa: parseFloat(academicData.cgpa) || 0,
                pri: 0,
                riskLevel: "High",
                arrears: 0,
                weakestModule: "None",
                updatedAt: new Date(),
            }, { merge: true });
        } else if (finalRole === "faculty") {
            await setDoc(doc(db, "faculty", uid), {
                uid,
                name: name || "",
                email: email || "",
                department: academicData.department || "",
                approved: finalApproved,
                designation: academicData.designation || "",
            }, { merge: true });
        }

        const hasPwd = credential.user.providerData.some(p => p.providerId === "password");
        const appUser = {
            ...firestoreDocToAppUser({ id: uid, ...userData }),
            loginProvider: credential.user.providerData[0]?.providerId || "password",
            hasPassword: hasPwd
        };
        setUser(appUser);
        toast.success("Account created successfully");

        handleRoleRedirection(appUser);
    };

    // ΓöÇΓöÇΓöÇ Google Login ΓöÇΓöÇΓöÇ
    const googleLogin = async (preferredRole?: Role) => {
        try {
            // Store preference in session for onAuthStateChanged hook
            if (preferredRole) {
                localStorage.setItem("alsa_preferred_role", preferredRole);
            }

            const provider = new GoogleAuthProvider();
            let result;
            try {
                result = await signInWithPopup(auth, provider);
            } catch (popupError: any) {
                if (popupError.code === "auth/popup-blocked") {
                    console.log("Popup blocked, falling back to redirect...");
                    toast.info("Pop-up blocked. Redirecting to Google Login...");
                    await signInWithRedirect(auth, provider);
                    return; // Redirect will happen, execution stops here
                }
                throw popupError;
            }
            const firebaseUser = result.user;
            const uid = firebaseUser.uid;

            // --- 1. ADMIN CHECK (Highest Priority for specific email) ---
            const isDean = firebaseUser.email?.toLowerCase() === "heyydean001@gmail.com";
            if (isDean) {
                const existingDoc = await getUserDocument(uid);
                const userData: Record<string, any> = {
                    name: firebaseUser.displayName || "Dean",
                    email: firebaseUser.email,
                    role: "admin",
                    approved: true,
                };
                if (!existingDoc) {
                    await createUserDocument(uid, userData);
                } else if ((existingDoc as any).role !== "admin") {
                    await updateUserDocument(uid, { role: "admin", approved: true });
                }
                const adminUser = firestoreDocToAppUser({ id: uid, ...userData });
                setUser(adminUser);
                toast.success("Welcome back, Admin");
                router.push("/admin/dashboard");
                return;
            }

            // --- 2. UID SEARCH (Fastest & Main Way) ---
            const existing = await getUserDocument(uid);

            // PRIORITY: Respect the intent from login page
            if (preferredRole && existing && (existing as any).role !== preferredRole) {
                // User has an account but wants a DIFFERENT role.
                // We treat them as a "Skeleton" for the new role.
                const skeletonUser: AppUser = {
                    id: uid,
                    uid: uid,
                    email: firebaseUser.email || "",
                    name: firebaseUser.displayName || "New User",
                    role: preferredRole as any,
                    gender: "OTHER",
                    loginProvider: "google.com",
                    hasPassword: firebaseUser.providerData.some(p => p.providerId === "password")
                } as AppUser;
                setUser(skeletonUser);
                toast.info(`Creating a new ${preferredRole} profile...`);
                handleRoleRedirection(skeletonUser);
                return;
            }

            if (existing) {
                const appUser = {
                    ...firestoreDocToAppUser(existing),
                    loginProvider: "google.com",
                    hasPassword: firebaseUser.providerData.some(p => p.providerId === "password")
                };
                setUser(appUser);
                toast.success(`Logged in as ${appUser.role}`);
                handleRoleRedirection(appUser);
                return;
            }

            // --- 3. EMAIL RECOVERY (For Pre-registered or Stranded accounts) ---
            if (firebaseUser.email) {
                const emailRecord = await getUserByEmail(firebaseUser.email);

                // If they have an email record for exactly the role they want, migrate/link it.
                if (emailRecord && (emailRecord as any).role === preferredRole) {
                    const appUser = {
                        ...firestoreDocToAppUser(emailRecord),
                        id: uid, // Use new UID for context
                        uid: uid,
                        loginProvider: "google.com",
                        hasPassword: firebaseUser.providerData.some(p => p.providerId === "password")
                    };

                    // MIGRATION: If the old record used a different ID (e.g. Register Number),
                    // we CREATE a new document with UID and then potentially clean up the old one.
                    // If IDs already match, updateUserDocument handles it.
                    if (emailRecord.id !== uid) {
                        await createUserDocument(uid, { ...emailRecord, uid: uid });
                        // Note: We keep the old document for legacy dashboard consistency (Dual-sync)
                    } else {
                        await updateUserDocument(uid, { uid: uid });
                    }

                    setUser(appUser);
                    handleRoleRedirection(appUser);
                    return;
                }
            }

            // --- 4. SKELETON or RECOVERY (No UID document found) ---
            const storedRole = localStorage.getItem("alsa_preferred_role") as Role;
            const activeRole = preferredRole || storedRole || null;

            // Optional: Recovery check (only if we have a clear role intent)
            if (activeRole) {
                let recoveryData = await getUserByEmail(firebaseUser.email || "");
                if (!recoveryData) {
                    // Check stranded collections
                    const stuSnap = await getDoc(doc(db, "students", uid));
                    if (stuSnap.exists()) {
                        recoveryData = { id: stuSnap.id, ...stuSnap.data(), role: "student" } as any;
                    } else {
                        const facSnap = await getDoc(doc(db, "faculty", uid));
                        if (facSnap.exists()) {
                            recoveryData = { id: facSnap.id, ...facSnap.data(), role: "faculty" } as any;
                        }
                    }
                }

                if (recoveryData && (recoveryData as any).role === activeRole) {
                    const recoveredUser = {
                        ...firestoreDocToAppUser(recoveryData),
                        loginProvider: "google.com",
                        hasPassword: firebaseUser.providerData.some(p => p.providerId === "password")
                    };
                    await createUserDocument(uid, recoveryData as any); // Migrate to users collection
                    setUser(recoveredUser);
                    toast.success("Account recovered successfully!");
                    handleRoleRedirection(recoveredUser);
                    return;
                }
            }

            const skeletonUser: AppUser = {
                id: uid,
                uid: uid,
                email: firebaseUser.email || "",
                name: firebaseUser.displayName || "New User",
                role: activeRole as any,
                gender: "OTHER",
                loginProvider: "google.com",
                hasPassword: firebaseUser.providerData.some(p => p.providerId === "password")
            } as AppUser;

            setUser(skeletonUser);
            localStorage.removeItem("alsa_preferred_role"); // Clean up
            handleRoleRedirection(skeletonUser);
        } catch (error: any) {
            if (error.code === "auth/popup-closed-by-user") {
                toast.warning("Google Sign-In was cancelled.");
            } else {
                console.error("Google login error:", error);
                toast.error("Google Sign-In failed: " + error.message);

                // Centralized issue logging
                logSystemIssue({
                    errorType: "AUTH_ERROR",
                    errorMessage: `Google Login Failed: ${error.code} - ${error.message}`,
                    page: window.location.pathname,
                    role: "guest"
                });
            }
        }
    };

    // ΓöÇΓöÇΓöÇ Update Profile ΓöÇΓöÇΓöÇ
    const updateUserProfileFn = async (updates: Partial<AppUser> & { newPassword?: string }) => {
        if (!user || !auth.currentUser) return;

        const { newPassword, ...otherUpdates } = updates;
        const updatedUser = { ...user, ...otherUpdates };
        setUser(updatedUser);

        try {
            // 1. Handle Password Update (if provided by Google user)
            if (newPassword) {
                try {
                    await updatePassword(auth.currentUser, newPassword);
                } catch (pwdErr: any) {
                    if (pwdErr.code === "auth/requires-recent-login") {
                        try {
                            const provider = new GoogleAuthProvider();
                            await reauthenticateWithPopup(auth.currentUser, provider);
                            await updatePassword(auth.currentUser, newPassword);
                            toast.success("Password successfully attached to your Google account.");
                        } catch (reauthErr: any) {
                            if (reauthErr.code !== "auth/popup-closed-by-user") {
                                toast.error("Re-authentication failed. Password not saved.");
                            }
                        }
                    } else {
                        toast.error("Failed to set password: " + pwdErr.message);
                    }
                }
            }

            // 2. Write to Firestore
            const firestoreUpdates: Record<string, any> = { ...otherUpdates };

            // Keep Firestore field names in sync
            if ("department" in otherUpdates && otherUpdates.department) {
                firestoreUpdates.department = normalizeDepartment(otherUpdates.department);
            }
            if ("isProfileComplete" in otherUpdates) {
                firestoreUpdates.profileCompleted = otherUpdates.isProfileComplete;
            }
            if ("areGradesComplete" in otherUpdates) {
                firestoreUpdates.gradesCompleted = otherUpdates.areGradesComplete;
            }

            // Use setDoc with merge to ensure the document is created if it doesn't exist
            const userRef = doc(db, "users", user.id);
            await setDoc(userRef, {
                ...firestoreUpdates,
                updatedAt: serverTimestamp(),
                // If initializing for first time, add email and name
                email: user.email,
                name: user.name,
                uid: user.id
            }, { merge: true });

            // 3. Synchronize to Role-Specific Collections for Dashboard Queries
            if (user.role === "student") {
                await setDoc(doc(db, "students", user.id), firestoreUpdates, { merge: true });
            } else if (user.role === "faculty") {
                await setDoc(doc(db, "faculty", user.id), firestoreUpdates, { merge: true });
            }
        } catch (err) {
            console.error("Failed to update profile:", err);
            toast.error("Failed to save profile changes.");
            throw err;
        }
    };

    // ΓöÇΓöÇΓöÇ Logout ΓöÇΓöÇΓöÇ
    const logout = async () => {
        await signOut(auth);
        setUser(null);
        router.push("/login");
        toast.success("Logged out successfully");
    };

    return (
        <AuthContext.Provider
            value={{
                user,
                isLoading,
                login,
                signup,
                googleLogin,
                logout,
                updateUserProfile: updateUserProfileFn,
                handleRoleRedirection
            }}
        >
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error("useAuth must be used within an AuthProvider");
    }
    return context;
}

import {
    User,
    AcademicEnrichment,
    AppliedKnowledge,
    AcademicEngagement,
    OutcomeAlignment,
    AcademicOutcomeIndex
} from "@/types";
import { PLACEMENT_ROLES, ROLE_SKILL_MATRIX, PlacementRole } from "@/lib/role-skills";
import { getCoreSubjects } from "@/lib/department-core";
import { CORE_ACADEMIC_TOPICS } from "@/lib/core-topics";

// -------------------------------------------------------------
// 1. ACADEMIC ENRICHMENT SCORE (Unified version)
// -------------------------------------------------------------
export function calculateEnrichmentScore(items: AcademicEnrichment[] | undefined): number {
    if (!items || items.length === 0) return 0;

    let totalScore = 0;

    items.forEach(item => {
        let score = 0;

        // Scoring rules from user:
        // Completed Certification = 10
        // Winner = 15
        // Runner = 10
        // Participation = 5
        // Workshop = 5
        // Internship = 20

        switch (item.status) {
            case "Winner": score = 15; break;
            case "Runner-up": score = 10; break;
            case "Participated": score = 5; break;
            case "Completed": {
                if (item.type === "Certification") score = 10;
                else if (item.type === "Internship") score = 20;
                else if (item.type === "Workshop") score = 5;
                else score = 10; // Default completed
                break;
            }
            default: score = 5;
        }

        // Add elite bonus if gold/elite
        if (item.isElite) score += 5;

        // Level bonus (modest)
        if (item.level === "National") score += 2;
        if (item.level === "International") score += 5;

        totalScore += score;
    });

    // Normalize to 100 as requested
    return Math.min(100, totalScore);
}

// -------------------------------------------------------------
// 2. EXTRA-CURRICULAR / APPLIED KNOWLEDGE (Now Aliased)
// -------------------------------------------------------------
export function calculateAppliedKnowledgeScore(items: AcademicEnrichment[] | undefined): number {
    return calculateEnrichmentScore(items);
}

export function calculateEngagementScore(items: AcademicEnrichment[] | undefined): number {
    return calculateEnrichmentScore(items);
}

// -------------------------------------------------------------
// 4. OUTCOME ALIGNMENT SCORE (OAS)
// -------------------------------------------------------------
// -------------------------------------------------------------
// 4. OUTCOME ALIGNMENT SCORE (OAS)
// -------------------------------------------------------------
export function calculateOutcomeAlignmentScore(data: OutcomeAlignment | undefined): number {
    if (!data) return 0;

    // 1. Calculate Core Coverage (Department Aware)
    let coreCoverage = 0;
    if (data.core) {
        // Fallback to old behavior if user dept is unknown, but ideally we have user object
        // Since OAS usually takes OutcomeAlignment which doesn't have User, 
        // we might need to rely on the saved coreCoverage or pass user.
        if (data.core.coreCoverage !== undefined) {
            coreCoverage = data.core.coreCoverage;
        } else {
            // Very legacy fallback
            const fields = Object.values(data.core).filter(v => typeof v === 'number') as number[];
            const sum = fields.reduce((a, b) => a + b, 0);
            coreCoverage = fields.length > 0 ? Math.round(sum / fields.length) : 0;
        }
    }

    // 2. Calculate Role Track Coverage
    let roleCoverage = 0;
    if (data.role && data.role.trackSelected) {
        // If we have explicit coverage calculated, use it
        if (typeof data.role.roleTrackCoverage === 'number') {
            roleCoverage = data.role.roleTrackCoverage;
        } else {
            // Otherwise calculate from concepts
            const matrix = ROLE_SKILL_MATRIX[data.role.trackSelected as PlacementRole];
            if (matrix) {
                const coreCount = matrix.core.length;
                const interCount = matrix.intermediate.length;
                const advCount = matrix.advanced.length;

                const myCore = data.role.concepts.core.length;
                const myInter = data.role.concepts.intermediate.length;
                const myAdv = data.role.concepts.advanced.length;

                const corePct = coreCount > 0 ? (myCore / coreCount) * 100 : 0;
                const interPct = interCount > 0 ? (myInter / interCount) * 100 : 0;
                const advPct = advCount > 0 ? (myAdv / advCount) * 100 : 0;

                // (0.5 * Core) + (0.3 * Inter) + (0.2 * Adv) -- applied to the Role Score
                roleCoverage = (0.5 * corePct) + (0.3 * interPct) + (0.2 * advPct);
            }
        }
    }

    // 3. Final Formula
    // OutcomeAlignmentScore = (0.5 ├ù CoreCoverage) + (0.5 ├ù RoleTrackCoverage)
    // If no role selected: OutcomeAlignmentScore = CoreCoverage

    let finalScore = 0;
    if (!data.role || !data.role.trackSelected) {
        finalScore = coreCoverage;
    } else {
        finalScore = (0.5 * coreCoverage) + (0.5 * roleCoverage);
    }

    return Math.round(Number.isNaN(finalScore) ? 0 : finalScore);
}

// -------------------------------------------------------------
// 5. ACADEMIC SEMESTER SCORE & GROWTH
// -------------------------------------------------------------
export function calculateAcademicSemesterScore(user: User): number {
    const cgpa = typeof user.cgpa === 'number' ? user.cgpa : parseFloat(user.cgpa as any || "0");
    // Normalize CGPA (0-10) to 0-100
    let score = Math.min(100, Math.round(cgpa * 10));

    // Arrear Penalty: Reduce 5 points per backlog (max -20)
    const arrears = user.standingArrears || user.arrears || 0;
    const penalty = Math.min(20, arrears * 5);

    score -= penalty;

    return Math.max(0, score);
}

export function calculateGrowthIndex(user: User): number {
    // Placeholder logic for consistency/growth
    // Ideally requires analyzing academicRecords for trend
    if (user.academicRecords && user.academicRecords.length > 1) {
        // Simple consistency check
        // If standard deviation is low, high consistency.
        // For now, return a safe default if not enough data.
        return 85;
    }
    return 80;
}


// -------------------------------------------------------------
// 6. MASTER AOI CALCULATION
// -------------------------------------------------------------
export function calculateAOI(user: User): AcademicOutcomeIndex {
    const academicScore = calculateAcademicSemesterScore(user);
    const growthIndex = calculateGrowthIndex(user);

    const enrichmentScore = calculateEnrichmentScore(user.academicEnrichment);
    const appliedScore = calculateAppliedKnowledgeScore(user.appliedKnowledge);
    const engagementScore = calculateEngagementScore(user.academicEngagement);
    const alignmentScore = calculateOutcomeAlignmentScore(user.outcomeAlignment);

    // Weighted Average
    // (0.35 ├ù Academic) + (0.2 ├ù Growth) + (0.15 ├ù Enrichment) 
    // + (0.15 ├ù Applied) + (0.1 ├ù Engagement) + (0.05 ├ù Alignment)

    const aoi = (0.35 * academicScore) +
        (0.20 * growthIndex) +
        (0.15 * enrichmentScore) +
        (0.15 * appliedScore) +
        (0.10 * engagementScore) +
        (0.05 * alignmentScore);

    const finalAOI = Math.round(Math.min(100, Math.max(0, aoi)));

    // Risk Engine
    const riskProfile = determineAcademicRisk(user, alignmentScore, enrichmentScore, appliedScore, engagementScore);

    // Text Generation
    const outcomeText = `AOI: ${finalAOI}/100`;
    const academicText = `CGPA: ${user.cgpa || "N/A"}`;
    const riskText = riskProfile.length > 0 ? `${riskProfile[0].riskLevel} Risk` : "Low Risk";

    return {
        aoi: finalAOI,
        academicScore,
        growthIndex,
        enrichmentScore,
        appliedScore,
        engagementScore,
        alignmentScore,
        riskProfile,
        overview: {
            academicText,
            outcomeText,
            riskText
        }
    };
}

function determineAcademicRisk(
    user: User,
    alignScore: number,
    enrichScore: number,
    appliedScore: number,
    engageScore: number
) {
    const risks = [];
    const cgpa = typeof user.cgpa === 'number' ? user.cgpa : parseFloat(user.cgpa as any || "0");
    const arrears = user.standingArrears || user.arrears || 0;

    // 1. Academic Risk
    if (arrears > 2) {
        risks.push({
            category: "Academic",
            riskLevel: "High Risk" as any, // Using standardized label
            missingArea: "Critical Backlogs",
            impact: "Severe impact on eligibility and degree completion.",
            suggestion: "Must clear standing arrears in the next attempt.",
            priority: "Immediate"
        });
    } else if (cgpa < 6.0) {
        risks.push({
            category: "Academic",
            riskLevel: "High Risk" as any,
            missingArea: "Low CGPA",
            impact: "Below academic tolerance threshold.",
            suggestion: "Must improvements grades to > 6.0.",
            priority: "Immediate"
        });
    }

    // 2. Enrichment Risk
    if (enrichScore === 0) {
        risks.push({
            category: "Enrichment",
            riskLevel: "Moderate" as const,
            missingArea: "No Academic Enrichment",
            impact: "Lack of domain depth.",
            suggestion: "Complete a certification or workshop.",
            priority: "Short-term"
        });
    }

    // 3. Applied Knowledge Risk
    if (appliedScore === 0) {
        risks.push({
            category: "Applied Knowledge",
            riskLevel: "Moderate" as const,
            missingArea: "Applied Learning Gap",
            impact: "Theoretical knowledge only.",
            suggestion: "Participate in a hackathon or contest.",
            priority: "Short-term"
        });
    }

    // 4. Engagement Risk
    if (engageScore === 0) {
        risks.push({
            category: "Engagement",
            riskLevel: "Low" as const,
            missingArea: "Low Engagement",
            impact: "Limited holistic development.",
            suggestion: "Join a club or coordinate an event.",
            priority: "Optional"
        });
    }

    // 5. Outcome Alignment Risk
    // Check core coverage specifically if data is available
    // Use optional chaining and default to avoid crash
    const coreCoverage = user.outcomeAlignment?.core?.coreCoverage ?? 0;

    // Only flag if they have actually started (i.e., coverage > 0 but < 60) OR if they have selected a track but have low core
    // If they haven't started (coverage 0), maybe don't flag "Weak Core" yet, or do?
    // Let's stick to simple threshold for now.
    if (user.outcomeAlignment && user.outcomeAlignment.score > 0 && coreCoverage < 60) {
        risks.push({
            category: "Outcome Alignment",
            riskLevel: "High" as const,
            missingArea: "Weak Core Fundamentals",
            impact: "Misaligned with selected academic track.",
            suggestion: "Strengthen core concepts in your track.",
            priority: "High"
        });
    }

    return risks;
}

import { User, Certification, Competition, ExtraCurricular, PlacementMetrics } from "@/types";
import {
    calculateEnrichmentScore,
    calculateAppliedKnowledgeScore,
    calculateEngagementScore
} from "./academic-calculations";
import { calculatePRI } from "./placement-calculations";

// --- Module 1: Academic Performance (APS) ---
export function calculateAcademicScore(cgpa: number | string | undefined): number {
    const val = typeof cgpa === 'number' ? cgpa : parseFloat(cgpa || "0");
    if (!val) return 0;
    return Math.min(100, Math.round(val * 10));
}

// --- Module 2: Certification Performance (CPS) ---
export function calculateCertificationScore(certifications: Certification[] | undefined = []): number {
    return calculateEnrichmentScore(certifications);
}

// --- Module 3: Competition Performance (CompS) ---
export function calculateCompetitionScore(competitions: Competition[] | undefined = []): number {
    return calculateAppliedKnowledgeScore(competitions);
}

// --- Module 4: Extra-Curricular Development (EDS) ---
export function calculateExtraCurricularScore(activities: ExtraCurricular[] | undefined = []): number {
    return calculateEngagementScore(activities);
}

// --- Module 5: Placement Readiness (PRS) ---
// Note: PRS is being superseded by PRI
export function calculatePlacementScore(user: User): number {
    return calculatePRI(user).pri;
}

// --- Balanced Student Development Index (BSDI) ---
export function calculateBSDI(user: User): {
    academic: number;
    certification: number;
    competition: number;
    extraCurricular: number;
    placement: number;
    bsdi: number;
    riskProfile: { status: string; color: string };
} {
    // Check both new and legacy properties
    const academic = calculateAcademicScore(user.cgpa);

    // Use new properties if available, fallback to legacy
    const certification = calculateEnrichmentScore(user.academicEnrichment || user.certifications);
    const competition = calculateAppliedKnowledgeScore(user.appliedKnowledge || user.competitions);
    const extraCurricular = calculateEngagementScore(user.academicEngagement || user.extraCurricular);

    // Placement - use the comprehensive PRI calculation
    const placement = calculatePRI(user).pri;

    // Equal weight: 20% each
    const bsdi = Math.round(
        (academic * 0.2) +
        (certification * 0.2) +
        (competition * 0.2) +
        (extraCurricular * 0.2) +
        (placement * 0.2)
    );

    let riskProfile = { status: "Unknown", color: "text-gray-500" };

    if (bsdi >= 80) riskProfile = { status: "Excellent Development", color: "text-green-600" };
    else if (bsdi >= 60) riskProfile = { status: "Good Development", color: "text-blue-600" };
    else if (bsdi >= 40) riskProfile = { status: "Moderate Risk", color: "text-amber-600" };
    else riskProfile = { status: "High Risk", color: "text-red-600" };

    return {
        academic,
        certification,
        competition,
        extraCurricular,
        placement,
        bsdi,
        riskProfile
    };
}

import { User } from "@/types";
import { calculatePRI } from "./placement-calculations";

export interface ClassDrawback {
    domain: string;
    affectedStudents: number;
    impactLevel: "Critical" | "High" | "Moderate" | "Low";
    primaryReason: string;
    facultyActionPlan: string[];
}

export interface ClassAnalysis {
    drawbacks: ClassDrawback[];
    overallHealth: "Excellent" | "Good" | "Needs Attention" | "Critical";
    topWeakness: string;
    studentsAtRisk: number;
}

export function analyzeClassPerformance(students: User[]): ClassAnalysis {
    if (!students || students.length === 0) {
        return { drawbacks: [], overallHealth: "Good", topWeakness: "None", studentsAtRisk: 0 };
    }

    let lowAcademicCount = 0;
    let lowCoreCount = 0;
    let lowRoleCount = 0;
    let lowAptitudeCount = 0;
    let lowEnrichmentCount = 0;
    let totalRiskCount = 0;

    students.forEach(student => {
        const { breakDown, pri } = calculatePRI(student);
        if (pri < 60) totalRiskCount++;

        // Thresholds for defining a "drawback" for a student in a specific area
        if (breakDown.academicNormalized < 60) lowAcademicCount++;
        if (breakDown.coreNormalized < 50) lowCoreCount++;
        if (breakDown.roleNormalized < 50) lowRoleCount++;
        if (breakDown.aptitudeNormalized < 50) lowAptitudeCount++;
        if (breakDown.enrichmentNormalized < 40) lowEnrichmentCount++;
    });

    const total = students.length;
    const drawbacks: ClassDrawback[] = [];

    // 1. Academic Drawbacks
    if (lowAcademicCount > 0) {
        const pct = (lowAcademicCount / total) * 100;
        if (pct > 20) {
            drawbacks.push({
                domain: "Academic Foundations",
                affectedStudents: lowAcademicCount,
                impactLevel: pct > 50 ? "Critical" : "High",
                primaryReason: "A significant portion of the class has low CGPA or standing arrears.",
                facultyActionPlan: [
                    "Identify common subjects where arrears occur and arrange remedial classes.",
                    "Implement a peer-tutoring system pairing high-CGPA students with those struggling.",
                    "Review internal assessment patterns to catch failing students earlier in the semester."
                ]
            });
        }
    }

    // 2. Core Coverage Drawbacks
    if (lowCoreCount > 0) {
        const pct = (lowCoreCount / total) * 100;
        if (pct > 30) {
            drawbacks.push({
                domain: "Core Engineering Subjects",
                affectedStudents: lowCoreCount,
                impactLevel: pct > 50 ? "Critical" : pct > 30 ? "High" : "Moderate",
                primaryReason: "Students are failing to master mandatory departmental core topics.",
                facultyActionPlan: [
                    "Integrate mini-projects into core subject curriculum to force application of theory.",
                    "Assign mandatory departmental topic revisions prior to placement season.",
                    "Conduct department-wide core competency tests."
                ]
            });
        }
    }

    // 3. Role/Skill Drawbacks
    if (lowRoleCount > 0) {
        const pct = (lowRoleCount / total) * 100;
        if (pct > 30) {
            drawbacks.push({
                domain: "Role-Specific Skills",
                affectedStudents: lowRoleCount,
                impactLevel: pct > 60 ? "Critical" : "High",
                primaryReason: "Students lack the necessary technical stack proficiencies for their chosen placement roles.",
                facultyActionPlan: [
                    "Mandate modern tech stack workshops (e.g., React, Node, DevOps).",
                    "Require students to build role-aligned portfolio projects.",
                    "Organize hackathons focused on industry-standard tools."
                ]
            });
        }
    }

    // 4. Aptitude Drawbacks
    if (lowAptitudeCount > 0) {
        const pct = (lowAptitudeCount / total) * 100;
        if (pct > 25) {
            drawbacks.push({
                domain: "Aptitude & Problem Solving",
                affectedStudents: lowAptitudeCount,
                impactLevel: pct > 50 ? "Critical" : "High",
                primaryReason: "Students are missing coverage in Quantitative, Logical, or Verbal reasoning.",
                facultyActionPlan: [
                    "Schedule mandatory weekly 2-hour aptitude solving sessions.",
                    "Integrate verbal reasoning and communication exercises into regular lab sessions.",
                    "Conduct bi-weekly mock aptitude tests mimicking company formats."
                ]
            });
        }
    }

    // 5. Enrichment Drawbacks
    if (lowEnrichmentCount > 0) {
        const pct = (lowEnrichmentCount / total) * 100;
        if (pct > 40) {
            drawbacks.push({
                domain: "Academic Enrichment",
                affectedStudents: lowEnrichmentCount,
                impactLevel: "Moderate",
                primaryReason: "The class lacks external certifications, internships, or competition participation.",
                facultyActionPlan: [
                    "Mandate at least one NPTEL or Coursera certification per semester.",
                    "Incentivize participation in platforms like LeetCode or Hackerrank.",
                    "Circulate internship opportunities actively through department channels."
                ]
            });
        }
    }

    // Sort by most affected
    drawbacks.sort((a, b) => b.affectedStudents - a.affectedStudents);

    let health: ClassAnalysis["overallHealth"] = "Good";
    const riskPct = (totalRiskCount / total) * 100;
    if (riskPct > 50) health = "Critical";
    else if (riskPct > 25) health = "Needs Attention";
    else if (riskPct < 10 && drawbacks.length === 0) health = "Excellent";

    return {
        drawbacks,
        overallHealth: health,
        topWeakness: drawbacks.length > 0 ? drawbacks[0].domain : "None",
        studentsAtRisk: totalRiskCount
    };
}

export function generateFacultyStudentRoadmap(student: User): { week: string, priority: string, focus: string, tasks: string[] }[] {
    const { breakDown, pri } = calculatePRI(student);
    const roadmap = [];

    // Week 1-2: Immediate triage based on worst area
    let primaryWeakness = "Aptitude";
    let minScore = breakDown.aptitudeNormalized;

    if (breakDown.academicNormalized < minScore) { primaryWeakness = "Academic Foundations"; minScore = breakDown.academicNormalized; }
    if (breakDown.coreNormalized < minScore) { primaryWeakness = "Core Engineering"; minScore = breakDown.coreNormalized; }
    if (breakDown.roleNormalized < minScore) { primaryWeakness = "Role Skills"; minScore = breakDown.roleNormalized; }

    if (primaryWeakness === "Academic Foundations") {
        roadmap.push({
            week: "Week 1-2: Academic Triage",
            priority: "Critical",
            focus: "Clearing Arrears & Boosting CGPA",
            tasks: [
                "Schedule a mandatory 1-on-1 counseling session to identify reasons for academic drop.",
                "Enforce a strict attendance tracking protocol.",
                "Assign peer mentor from the same department to help with difficult subjects."
            ]
        });
    } else if (primaryWeakness === "Aptitude") {
        roadmap.push({
            week: "Week 1-2: Aptitude Intensive",
            priority: "High",
            focus: "Quantitative & Logical Remediation",
            tasks: [
                "Assign 50 mandatory quantitative problems per week from generic placement platforms.",
                "Monitor completion of logical reasoning mock tests every Friday.",
                "Advise student to focus specifically on missing 'Data Interpretation' modules."
            ]
        });
    } else if (primaryWeakness === "Core Engineering") {
        roadmap.push({
            week: "Week 1-2: Core Concept Revival",
            priority: "High",
            focus: "Departmental Foundation Setup",
            tasks: [
                "Assign a mandatory review project focusing on the 'Missing' core subjects.",
                "Conduct a viva-voce on fundamental departmental topics.",
                "Recommend NPTEL crash courses on standard core mechanics."
            ]
        });
    } else {
        roadmap.push({
            week: "Week 1-2: Tech Stack Validation",
            priority: "Moderate",
            focus: "Role-specific Skill Building",
            tasks: [
                "Request submission of a working GitHub repository for an ongoing project.",
                "Assign a mini-project specifically in their preferred target placement track.",
                "Review their Data Structures & Algorithms proficiency level."
            ]
        });
    }

    // Week 3-4: Secondary Weakness or Confidence Building
    roadmap.push({
        week: "Week 3-4: Capability Expansion",
        priority: "Moderate",
        focus: "Bridging the Secondary Gap",
        tasks: [
            "Check progress on Week 1-2 remediation tasks.",
            "Introduce mock technical interviews with faculty or alumni.",
            "Mandate completion of at least one external skill certification (Coursera/Udemy)."
        ]
    });

    // Week 5-6: Placement Readiness Polish
    roadmap.push({
        week: "Week 5-6: Readiness Launchpad",
        priority: "Standard",
        focus: "Final Verification",
        tasks: [
            "Conduct a comprehensive mock interview covering HR & Technical aspects.",
            "Review and approve their final updated resume.",
            "Verify their communication checklists and fluency metrics."
        ]
    });

    return roadmap;
}

/**
 * Strict Formula for Readiness Score
 * readinessScore = (certCount * 10) + (enrichCount * 15)
 * 
 * Supports both Simplified Model and AOI Model fields.
 */
export function calculateReadinessScore(student: any): number {
    const certs = student.certifications || [];
    const enrichment = student.enrichment || [];

    // Support AOI Model fields
    const academicEnrichment = student.academicEnrichment || [];
    const appliedKnowledge = student.appliedKnowledge || [];

    // Aggregate counts
    // We treat 'certifications' and 'academicEnrichment' as pools for certCount
    // We treat 'enrichment' and 'appliedKnowledge' as pools for enrichCount
    const certCount = Math.max(certs.length, academicEnrichment.filter((i: any) => i.type === "Certification").length);
    const enrichCount = Math.max(enrichment.length, appliedKnowledge.length + academicEnrichment.filter((i: any) => i.type !== "Certification").length);

    return (certCount * 10) + (enrichCount * 15);
}

/**
 * Strict Risk Logic
 * >= 80 -> low
 * 40-79 -> moderate
 * < 40 -> high
 */
export function getRiskLevel(readinessScore: number): "Ready" | "Moderate" | "High" | "Critical" {
    if (readinessScore >= 75) return "Ready";
    if (readinessScore >= 60) return "Moderate";
    if (readinessScore >= 40) return "High";
    return "Critical";
}

export interface DrawbackItem {
    drawback: string;
    suggestion: string;
}

/**
 * Dynamic Drawback Generation Rules
 */
export function generateDrawbacks(student: any): DrawbackItem[] {
    const drawbacks: DrawbackItem[] = [];

    // Extract pools
    const certs = student.certifications || [];
    const academicEnrichment = student.academicEnrichment || [];
    const enrichment = student.enrichment || [];
    const appliedKnowledge = student.appliedKnowledge || [];

    // Calculate effective counts
    const certCount = Math.max(certs.length, academicEnrichment.filter((i: any) => i.type === "Certification").length);
    const enrichCount = Math.max(enrichment.length, appliedKnowledge.length + academicEnrichment.filter((i: any) => i.type !== "Certification").length);

    const score = student.readinessScore || ((certCount * 10) + (enrichCount * 15));

    if (certCount < 2) {
        drawbacks.push({
            drawback: "Insufficient certifications",
            suggestion: "Complete at least 2 relevant certifications to boost profile visibility."
        });
    }

    if (enrichCount < 2) {
        drawbacks.push({
            drawback: "Low participation in academic enrichment",
            suggestion: "Engage in more workshops, seminars, or technical events."
        });
    }

    // Checking for internships
    const hasInternship = student.internships?.length > 0 ||
        enrichment.some((e: any) => e.type?.toLowerCase().includes("internship") || e.title?.toLowerCase().includes("internship")) ||
        academicEnrichment.some((e: any) => e.type?.toLowerCase().includes("internship") || e.title?.toLowerCase().includes("internship"));

    if (!hasInternship) {
        drawbacks.push({
            drawback: "No internship exposure",
            suggestion: "Apply for summer/winter internships to gain industry experience."
        });
    }

    if (score < 40) {
        drawbacks.push({
            drawback: "High placement risk",
            suggestion: "Concentrate on core skills and participate in mock drives immediately."
        });
    }

    if (student.profileComplete === false && student.isProfileComplete === false) {
        drawbacks.push({
            drawback: "Incomplete student profile",
            suggestion: "Update all personal and academic details to 100% completion."
        });
    }

    return drawbacks;
}

