// ≡ƒ¢í∩╕Å Recursive Helper to clean objects of undefined values
const cleanObject = (obj: any): any => {
    if (obj === null || typeof obj !== 'object') return obj;

    // Handle Arrays
    if (Array.isArray(obj)) {
        return obj.map(item => cleanObject(item)).filter(v => v !== undefined);
    }

    // Handle Objects
    return Object.fromEntries(
        Object.entries(obj)
            .map(([k, v]) => [k, cleanObject(v)])
            .filter(([_, v]) => v !== undefined)
    );
};

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
