function calculateAptitudeScore(user: any): number {
    if (user.placementMetrics?.detailedAptitude) {
        let totalCoverage = 0;
        let numTopics = 0;
        for (const cat of Object.values(user.placementMetrics.detailedAptitude) as any[]) {
            if (cat.topics) {
                for (const top of Object.values(cat.topics) as any[]) {
                    totalCoverage += Number(top.coverage) || 0;
                    numTopics++;
                }
            }
        }
        return numTopics > 0 ? (totalCoverage / numTopics) : 0;
    }
    if (user.placementMetrics?.aptitude) {
        return user.placementMetrics.aptitude.completionPercentage || 0;
    }
    return user.placementMetrics?.aptitudeScore || 0;
}

function calculateEnrichmentScore(data: any): number {
    if (!data) return 0;
    const certsCount = data.certifications?.length || 0;
    let certScore = 0;
    if (certsCount >= 3) certScore = 100;
    else if (certsCount === 2) certScore = 70;
    else if (certsCount === 1) certScore = 40;
    const pubScore = data.publications?.length > 0 ? 10 : 0;
    const compScore = data.competitions?.length > 0 ? 15 : 0;
    const portScore = data.portfolioLink ? 20 : 0;
    return Math.min(100, certScore + pubScore + compScore + portScore);
}

function calculateCoreFoundationScore(user: any): { score: number } {
    if (!user.coreAcademicTopics || user.coreAcademicTopics.length === 0) {
        return { score: 0 };
    }
    const topicCount = user.coreAcademicTopics.length;
    let totalProgress = 0;
    for (const t of user.coreAcademicTopics) {
        if (t.status === "Completed") totalProgress += 100;
        else if (t.status === "In Progress") totalProgress += 50;
    }
    return { score: topicCount > 0 ? (totalProgress / topicCount) : 0 };
}

function calculateNewRoleScore(user: any): number {
    const roleTrackProfile = user.roleTrackProfile;
    if (!roleTrackProfile || !roleTrackProfile.trackSelected) return 0;
    return roleTrackProfile.roleSkillScore || 0;
}

function calculatePRI(user: any): { pri: number, breakDown: any } {
    const cgpa = typeof user.cgpa === 'number' ? user.cgpa : parseFloat(user.cgpa || "0");
    const standingArrears = user.standingArrears || user.arrears || 0;

    const academicNormalized = (cgpa / 10) * 100;
    const academicScore = academicNormalized * 0.40;

    const coreStats = calculateCoreFoundationScore(user);
    const coreScore = coreStats.score * 0.25;

    const roleCoverage = calculateNewRoleScore(user);
    const roleScore = roleCoverage * 0.15;

    const aptitudeCoverage = calculateAptitudeScore(user);
    const aptitudeScore = aptitudeCoverage * 0.10;

    const enrichmentNormalized = calculateEnrichmentScore(user.academicEnrichment);
    const enrichmentScore = enrichmentNormalized * 0.10;

    const arrearPenalty = standingArrears * 5;
    const pri = Math.max(0, (academicScore + coreScore + roleScore + aptitudeScore + enrichmentScore) - arrearPenalty);

    return {
        pri: Math.round(Math.min(100, pri)),
        breakDown: {
            academic: Math.round(academicScore),
            core: Math.round(coreScore),
            role: Math.round(roleScore),
            aptitude: Math.round(aptitudeScore),
            enrichment: Math.round(enrichmentScore),
            academicNormalized,
            coreNormalized: coreStats.score,
            roleNormalized: roleCoverage,
            aptitudeNormalized: aptitudeCoverage,
            enrichmentNormalized,
            riskFactor: Math.max(0, 100 - (standingArrears * 20))
        }
    };
}


